window.TXB=window.TXB||{};TXB["svd/Psa"]={"1:1":"طوبى للرجل الذي لم يسلك في مشورة الأشرار وفي طريق الخطاة لم يقف وفي مجلس المستهزئين لم يجلس.","1:2":"لكن في ناموس الرب مسرته وفي ناموسه يلهج نهارا وليلا.","1:3":"فيكون كشجرة مغروسة عند مجاري المياه التي تعطي ثمرها في أوانه وورقها لا يذبل. وكل ما يصنعه ينجح.","1:4":"ليس كذلك الأشرار لكنهم كالعصافة التي تذريها الريح.","1:5":"لذلك لا تقوم الأشرار في الدين ولا الخطاة في جماعة الأبرار.","1:6":"لأن الرب يعلم طريق الأبرار أما طريق الأشرار فتهلك.","2:1":"لماذا ارتجت الأمم وتفكر الشعوب في الباطل؟","2:2":"قام ملوك الأرض وتآمر الرؤساء معا على الرب وعلى مسيحه قائلين:","2:3":"[لنقطع قيودهما ولنطرح عنا ربطهما].","2:4":"الساكن في السماوات يضحك. الرب يستهزئ بهم.","2:5":"حينئذ يتكلم عليهم بغضبه ويرجفهم بغيظه.","2:6":"أما أنا فقد مسحت ملكي على صهيون جبل قدسي.","2:7":"إني أخبر من جهة قضاء الرب. قال لي: [أنت ابني. أنا اليوم ولدتك.","2:8":"اسألني فأعطيك الأمم ميراثا لك وأقاصي الأرض ملكا لك.","2:9":"تحطمهم بقضيب من حديد. مثل إناء خزاف تكسرهم].","2:10":"فالآن يا أيها الملوك تعقلوا. تأدبوا يا قضاة الأرض.","2:11":"اعبدوا الرب بخوف واهتفوا برعدة.","2:12":"قبلوا الابن لئلا يغضب فتبيدوا من الطريق. لأنه عن قليل يتقد غضبه. طوبى لجميع المتكلين عليه.","3:1":"مزمور لداود حينما هرب من وجه أبشالوم ابنه يا رب ما أكثر مضايقي. كثيرون قائمون علي.","3:2":"كثيرون يقولون لنفسي: [ليس له خلاص بإلهه]. سلاه.","3:3":"أما أنت يا رب فترس لي. مجدي ورافع رأسي.","3:4":"بصوتي إلى الرب أصرخ فيجيبني من جبل قدسه. سلاه.","3:5":"أنا اضطجعت ونمت. استيقظت لأن الرب يعضدني.","3:6":"لا أخاف من ربوات الشعوب المصطفين علي من حولي.","3:7":"قم يا رب. خلصني يا إلهي. لأنك ضربت كل أعدائي على الفك. هشمت أسنان الأشرار.","3:8":"للرب الخلاص. على شعبك بركتك. سلاه.","4:1":"لإمام المغنين على ذوات الأوتار. مزمور لداود عند دعائي استجب لي يا إله بري. في الضيق رحبت لي. تراءف علي واسمع صلاتي.","4:2":"يا بني البشر حتى متى يكون مجدي عارا! حتى متى تحبون الباطل وتبتغون الكذب! سلاه.","4:3":"فاعلموا أن الرب قد ميز تقيه. الرب يسمع عند ما أدعوه.","4:4":"ارتعدوا ولا تخطئوا. تكلموا في قلوبكم على مضاجعكم واسكتوا. سلاه.","4:5":"اذبحوا ذبائح البر وتوكلوا على الرب.","4:6":"كثيرون يقولون: [من يرينا خيرا؟] ارفع علينا نور وجهك يا رب.","4:7":"جعلت سرورا في قلبي أعظم من سرورهم إذ كثرت حنطتهم وخمرهم.","4:8":"بسلامة أضطجع بل أيضا أنام لأنك أنت يا رب منفردا في طمأنينة تسكنني.","5:1":"لإمام المغنين على ذوات النفخ. مزمور لداود لكلماتي أصغ يا رب. تأمل صراخي.","5:2":"استمع لصوت دعائي يا ملكي وإلهي لأني إليك أصلي.","5:3":"يا رب بالغداة تسمع صوتي. بالغداة أوجه صلاتي نحوك وأنتظر.","5:4":"لأنك أنت لست إلها يسر بالشر لا يساكنك الشرير.","5:5":"لا يقف المفتخرون قدام عينيك. أبغضت كل فاعلي الإثم.","5:6":"تهلك المتكلمين بالكذب. رجل الدماء والغش يكرهه الرب.","5:7":"أما أنا فبكثرة رحمتك أدخل بيتك. أسجد في هيكل قدسك بخوفك.","5:8":"يا رب اهدني إلى برك بسبب أعدائي. سهل قدامي طريقك.","5:9":"لأنه ليس في أفواههم صدق. جوفهم هوة. حلقهم قبر مفتوح. ألسنتهم صقلوها.","5:10":"دنهم يا الله. ليسقطوا من مؤامراتهم بكثرة ذنوبهم. طوح بهم لأنهم تمردوا عليك.","5:11":"ويفرح جميع المتكلين عليك. إلى الأبد يهتفون وتظللهم. ويبتهج بك محبو اسمك.","5:12":"لأنك أنت تبارك الصديق يا رب. كأنه بترس تحيطه بالرضا.","6:1":"لإمام المغنين على ذوات الأوتار على القرار. مزمور لداود يا رب لا توبخني بغضبك ولا تؤدبني بغيظك.","6:2":"ارحمني يا رب لأني ضعيف. اشفني يا رب لأن عظامي قد رجفت","6:3":"ونفسي قد ارتاعت جدا. وأنت يا رب فحتى متى!","6:4":"عد يا رب. نج نفسي. خلصني من أجل رحمتك.","6:5":"لأنه ليس في الموت ذكرك. في الهاوية من يحمدك؟","6:6":"تعبت في تنهدي. أعوم في كل ليلة سريري بدموعي. أذوب فراشي.","6:7":"ساخت من الغم عيني. شاخت من كل مضايقي.","6:8":"ابعدوا عني يا جميع فاعلي الإثم لأن الرب قد سمع صوت بكائي.","6:9":"سمع الرب تضرعي. الرب يقبل صلاتي.","6:10":"جميع أعدائي يخزون ويرتاعون جدا. يعودون ويخزون بغتة.","7:1":"شجوية لداود غناها للرب بسبب كلام كوش البنياميني يا رب إلهي عليك توكلت. خلصني من كل الذين يطردونني ونجني","7:2":"لئلا يفترس كأسد نفسي هاشما إياها ولا منقذ.","7:3":"يا رب إلهي إن كنت قد فعلت هذا. إن وجد ظلم في يدي.","7:4":"إن كافأت مسالمي شرا وسلبت مضايقي بلا سبب","7:5":"فليطارد عدو نفسي وليدركها وليدس إلى الأرض حياتي وليحط إلى التراب مجدي. سلاه.","7:6":"قم يا رب بغضبك. ارتفع على سخط مضايقي وانتبه لي. بالحق أوصيت.","7:7":"ومجمع القبائل يحيط بك فعد فوقها إلى العلى.","7:8":"الرب يدين الشعوب. اقض لي يا رب كحقي ومثل كمالي الذي في.","7:9":"لينته شر الأشرار وثبت الصديق. فإن فاحص القلوب والكلى الله البار.","7:10":"ترسي عند الله مخلص مستقيمي القلوب.","7:11":"الله قاض عادل وإله يسخط في كل يوم.","7:12":"إن لم يرجع يحدد سيفه. مد قوسه وهيأها","7:13":"وسدد نحوه آلة الموت. يجعل سهامه ملتهبة.","7:14":"هوذا يمخض بالإثم. حمل تعبا وولد كذبا.","7:15":"كرا جبا. حفره فسقط في الهوة التي صنع.","7:16":"يرجع تعبه على رأسه وعلى هامته يهبط ظلمه.","7:17":"أحمد الرب حسب بره. وأرنم لاسم الرب العلي.","8:1":"لإمام المغنين على الجتية. مزمور لداود أيها الرب سيدنا ما أمجد اسمك في كل الأرض حيث جعلت جلالك فوق السماوات!","8:2":"من أفواه الأطفال والرضع أسست حمدا بسبب أضدادك لتسكيت عدو ومنتقم.","8:3":"إذا أرى سماواتك عمل أصابعك القمر والنجوم التي كونتها","8:4":"فمن هو الإنسان حتى تذكره وابن آدم حتى تفتقده!","8:5":"وتنقصه قليلا عن الملائكة وبمجد وبهاء تكلله.","8:6":"تسلطه على أعمال يديك. جعلت كل شيء تحت قدميه.","8:7":"الغنم والبقر جميعا وبهائم البر أيضا","8:8":"وطيور السماء وسمك البحر السالك في سبل المياه.","8:9":"أيها الرب سيدنا ما أمجد اسمك في كل الأرض!","9:1":"لإمام المغنين. على [موت الابن]. مزمور لداود أحمد الرب بكل قلبي. أحدث بجميع عجائبك.","9:2":"أفرح وأبتهج بك. أرنم لاسمك أيها العلي.","9:3":"عند رجوع أعدائي إلى خلف يسقطون ويهلكون من قدام وجهك","9:4":"لأنك أقمت حقي ودعواي. جلست على الكرسي قاضيا عادلا.","9:5":"انتهرت الأمم. أهلكت الشرير. محوت اسمهم إلى الدهر والأبد.","9:6":"العدو تم خرابه إلى الأبد. وهدمت مدنا. باد ذكره نفسه.","9:7":"أما الرب فإلى الدهر يجلس. ثبت للقضاء كرسيه","9:8":"وهو يقضي للمسكونة بالعدل. يدين الشعوب بالاستقامة.","9:9":"ويكون الرب ملجأ للمنسحق. ملجأ في أزمنة الضيق.","9:10":"ويتكل عليك العارفون اسمك. لأنك لم تترك طالبيك يا رب.","9:11":"رنموا للرب الساكن في صهيون. أخبروا بين الشعوب بأفعاله.","9:12":"لأنه مطالب بالدماء. ذكرهم. لم ينس صراخ المساكين.","9:13":"ارحمني يا رب. انظر مذلتي من مبغضي يا رافعي من أبواب الموت.","9:14":"لكي أحدث بكل تسابيحك في أبواب ابنة صهيون مبتهجا بخلاصك.","9:15":"تورطت الأمم في الحفرة التي عملوها. في الشبكة التي أخفوها انتشبت أرجلهم.","9:16":"معروف هو الرب. قضاء أمضى. الشرير يعلق بعمل يديه. (ضرب الأوتار). سلاه.","9:17":"الأشرار يرجعون إلى الهاوية كل الأمم الناسين الله.","9:18":"لأنه لا ينسى المسكين إلى الأبد. رجاء البائسين لا يخيب إلى الدهر.","9:19":"قم يا رب. لا يعتز الإنسان. لتحاكم الأمم قدامك.","9:20":"يا رب اجعل عليهم رعبا ليعلم الأمم أنهم بشر. سلاه","10:1":"يا رب لماذا تقف بعيدا؟ لماذا تختفي في أزمنة الضيق؟","10:2":"في كبرياء الشرير يحترق المسكين. يؤخذون بالمؤامرة التي فكروا بها.","10:3":"لأن الشرير يفتخر بشهوات نفسه والخاطف يجدف. يهين الرب.","10:4":"الشرير حسب تشامخ أنفه يقول: [لا يطالب]. كل أفكاره أنه لا إله.","10:5":"تثبت سبله في كل حين. عالية أحكامك فوقه. كل أعدائه ينفث فيهم.","10:6":"قال في قلبه: [لا أتزعزع. من دور إلى دور بلا سوء].","10:7":"فمه مملوء لعنة وغشا وظلما. تحت لسانه مشقة وإثم.","10:8":"يجلس في مكمن الديار في المختفيات يقتل البريء. عيناه تراقبان المسكين.","10:9":"يكمن في المختفى كأسد في عريسه. يكمن ليخطف المسكين. يخطف المسكين بجذبه في شبكته","10:10":"فتنسحق وتنحني وتسقط المساكين ببراثنه.","10:11":"قال في قلبه: [إن الله قد نسي. حجب وجهه. لا يرى إلى الأبد].","10:12":"قم يا رب. يا الله ارفع يدك. لا تنس المساكين.","10:13":"لماذا أهان الشرير الله؟ لماذا قال في قلبه: [لا تطالب]؟","10:14":"قد رأيت. لأنك تبصر المشقة والغم لتجازي بيدك. إليك يسلم المسكين أمره. أنت صرت معين اليتيم.","10:15":"احطم ذراع الفاجر. والشرير تطلب شره ولا تجده.","10:16":"الرب ملك إلى الدهر والأبد. بادت الأمم من أرضه.","10:17":"تأوه الودعاء قد سمعت يا رب. تثبت قلوبهم. تميل أذنك","10:18":"لحق اليتيم والمنسحق لكي لا يعود أيضا يرعبهم إنسان من الأرض.","11:1":"لإمام المغنين. لداود على الرب توكلت. كيف تقولون لنفسي: [اهربوا إلى جبالكم كعصفور]؟","11:2":"لأنه هوذا الأشرار يمدون القوس. فوقوا السهم في الوتر ليرموا في الدجى مستقيمي القلوب.","11:3":"إذا انقلبت الأعمدة فالصديق ماذا يفعل؟","11:4":"الرب في هيكل قدسه. الرب في السماء كرسيه. عيناه تنظران. أجفانه تمتحن بني آدم.","11:5":"الرب يمتحن الصديق. أما الشرير ومحب الظلم فتبغضه نفسه.","11:6":"يمطر على الأشرار فخاخا نارا وكبريتا وريح السموم نصيب كأسهم.","11:7":"لأن الرب عادل ويحب العدل. المستقيم يبصر وجهه.","12:1":"لإمام المغنين على [القرار]. مزمور لداود خلص يا رب لأنه قد انقرض التقي لأنه قد انقطع الأمناء من بني البشر.","12:2":"يتكلمون بالكذب كل واحد مع صاحبه بشفاه ملقة بقلب فقلب يتكلمون.","12:3":"يقطع الرب جميع الشفاه الملقة واللسان المتكلم بالعظائم","12:4":"الذين قالوا: [بألسنتنا نتجبر. شفاهنا معنا. من هو سيد علينا؟].","12:5":"[من اغتصاب المساكين من صرخة البائسين الآن أقوم يقول الرب. [أجعل في وسع الذي ينفث فيه].","12:6":"كلام الرب كلام نقي كفضة مصفاة في بوطة في الأرض ممحوصة سبع مرات.","12:7":"أنت يا رب تحفظهم. تحرسهم من هذا الجيل إلى الدهر.","12:8":"الأشرار يتمشون من كل ناحية عند ارتفاع الأرذال بين الناس.","13:1":"لإمام المغنين. مزمور لداود إلى متى يا رب تنساني كل النسيان! إلى متى تحجب وجهك عني!","13:2":"إلى متى أجعل هموما في نفسي وحزنا في قلبي كل يوم! إلى متى يرتفع عدوي علي!","13:3":"انظر واستجب لي يا رب إلهي. أنر عيني لئلا أنام نوم الموت","13:4":"لئلا يقول عدوي: [قد قويت عليه]. لئلا يهتف مضايقي بأني تزعزعت.","13:5":"أما أنا فعلى رحمتك توكلت. يبتهج قلبي بخلاصك.","13:6":"أغني للرب لأنه أحسن إلي.","14:1":"لإمام المغنين. لداود قال الجاهل في قلبه: [ليس إله]. فسدوا ورجسوا بأفعالهم. ليس من يعمل صلاحا.","14:2":"الرب من السماء أشرف على بني البشر لينظر: هل من فاهم طالب الله؟","14:3":"الكل قد زاغوا معا فسدوا. ليس من يعمل صلاحا ليس ولا واحد.","14:4":"ألم يعلم كل فاعلي الإثم الذين يأكلون شعبي كما يأكلون الخبز والرب لم يدعوا.","14:5":"هناك خافوا خوفا لأن الله في الجيل البار.","14:6":"رأي المسكين ناقضتم لأن الرب ملجأه.","14:7":"ليت من صهيون خلاص إسرائيل. عند رد الرب سبي شعبه يهتف يعقوب ويفرح إسرائيل.","15:1":"مزمور لداود يا رب من ينزل في مسكنك؟ من يسكن في جبل قدسك؟","15:2":"السالك بالكمال والعامل الحق والمتكلم بالصدق في قلبه.","15:3":"الذي لا يشي بلسانه ولا يصنع شرا بصاحبه ولا يحمل تعييرا على قريبه.","15:4":"والرذيل محتقر في عينيه ويكرم خائفي الرب. يحلف للضرر ولا يغير.","15:5":"فضته لا يعطيها بالربا ولا يأخذ الرشوة على البريء. الذي يصنع هذا لا يتزعزع إلى الدهر.","16:1":"مذهبة لداود احفظني يا الله لأني عليك توكلت.","16:2":"قلت للرب: [أنت سيدي. خيري لا شيء غيرك.","16:3":"القديسون الذين في الأرض والأفاضل كل مسرتي بهم].","16:4":"تكثر أوجاعهم الذين أسرعوا وراء آخر. لا أسكب سكائبهم من دم ولا أذكر أسماءهم بشفتي.","16:5":"الرب نصيب قسمتي وكأسي. أنت قابض قرعتي.","16:6":"حبال وقعت لي في النعماء فالميراث حسن عندي.","16:7":"أبارك الرب الذي نصحني وأيضا بالليل تنذرني كليتاي.","16:8":"جعلت الرب أمامي في كل حين. لأنه عن يميني فلا أتزعزع.","16:9":"لذلك فرح قلبي وابتهجت روحي. جسدي أيضا يسكن مطمئنا.","16:10":"لأنك لن تترك نفسي في الهاوية. لن تدع تقيك يرى فسادا.","16:11":"تعرفني سبيل الحياة. أمامك شبع سرور. في يمينك نعم إلى الأبد.","17:1":"صلاة لداود اسمع يا رب للحق. أنصت إلى صراخي. أصغ إلى صلاتي من شفتين بلا غش.","17:2":"من قدامك يخرج قضائي. عيناك تنظران المستقيمات.","17:3":"جربت قلبي. تعهدته ليلا. محصتني. لا تجد في ذموما. لا يتعدى فمي.","17:4":"من جهة أعمال الناس فبكلام شفتيك أنا تحفظت من طرق المعتنف.","17:5":"تمسكت خطواتي بآثارك فما زلت قدماي.","17:6":"أنا دعوتك لأنك تستجيب لي يا الله. أمل أذنيك إلي. اسمع كلامي.","17:7":"ميز مراحمك يا مخلص المتكلين عليك بيمينك من المقاومين.","17:8":"احفظني مثل حدقة العين. بظل جناحيك استرني","17:9":"من وجه الأشرار الذين يخربونني أعدائي بالنفس الذين يكتنفونني.","17:10":"قلبهم السمين قد أغلقوا. بأفواههم قد تكلموا بالكبرياء.","17:11":"في خطواتنا الآن قد أحاطوا بنا. نصبوا أعينهم ليزلقونا إلى الأرض.","17:12":"مثله مثل الأسد القرم إلى الافتراس وكالشبل الكامن في عريسه.","17:13":"قم يا رب. تقدمه. اصرعه. نج نفسي من الشرير بسيفك","17:14":"من الناس بيدك يا رب من أهل الدنيا. نصيبهم في حياتهم. بذخائرك تملأ بطونهم. يشبعون أولادا ويتركون فضالتهم لأطفالهم.","17:15":"أما أنا فبالبر أنظر وجهك. أشبع إذا استيقظت بشبهك.","18:1":"لإمام المغنين. لعبد الرب داود الذي كلم الرب بكلام هذا النشيد في اليوم الذي أنقذه فيه الرب من أيدي كل أعدائه ومن يد شاول. فقال: أحبك يا رب يا قوتي.","18:2":"الرب صخرتي وحصني ومنقذي. إلهي صخرتي به أحتمي. ترسي وقرن خلاصي وملجإي.","18:3":"أدعو الرب الحميد فأتخلص من أعدائي.","18:4":"اكتنفتني حبال الموت وسيول الهلاك أفزعتني.","18:5":"حبال الهاوية حاقت بي. أشراك الموت انتشبت بي.","18:6":"في ضيقي دعوت الرب وإلى إلهي صرخت فسمع من هيكله صوتي وصراخي قدامه دخل أذنيه.","18:7":"فارتجت الأرض وارتعشت أسس الجبال. ارتعدت وارتجت لأنه غضب.","18:8":"صعد دخان من أنفه ونار من فمه أكلت. جمر اشتعلت منه.","18:9":"طأطأ السماوات ونزل وضباب تحت رجليه.","18:10":"ركب على كروب وطار وهف على أجنحة الرياح.","18:11":"جعل الظلمة ستره. حوله مظلته ضباب المياه وظلام الغمام.","18:12":"من الشعاع قدامه عبرت سحبه. برد وجمر نار.","18:13":"أرعد الرب من السماوات والعلي أعطى صوته بردا وجمر نار.","18:14":"أرسل سهامه فشتتهم وبروقا كثيرة فأزعجهم","18:15":"فظهرت أعماق المياه وانكشفت أسس المسكونة من زجرك يا رب من نسمة ريح أنفك.","18:16":"أرسل من العلى فأخذني. نشلني من مياه كثيرة.","18:17":"أنقذني من عدوي القوي ومن مبغضي لأنهم أقوى مني.","18:18":"أصابوني في يوم بليتي وكان الرب سندي.","18:19":"أخرجني إلى الرحب. خلصني لأنه سر بي.","18:20":"يكافئني الرب حسب بري. حسب طهارة يدي يرد لي.","18:21":"لأني حفظت طرق الرب ولم أعص إلهي.","18:22":"لأن جميع أحكامه أمامي وفرائضه لم أبعدها عن نفسي.","18:23":"وأكون كاملا معه وأتحفظ من إثمي.","18:24":"فيرد الرب لي كبري وكطهارة يدي أمام عينيه.","18:25":"مع الرحيم تكون رحيما. مع الرجل الكامل تكون كاملا.","18:26":"مع الطاهر تكون طاهرا. ومع الأعوج تكون ملتويا.","18:27":"لأنك أنت تخلص الشعب البائس والأعين المرتفعة تضعها.","18:28":"لأنك أنت تضيء سراجي. الرب إلهي ينير ظلمتي.","18:29":"لأني بك اقتحمت جيشا وبإلهي تسورت أسوارا.","18:30":"الله طريقه كامل. قول الرب نقي. ترس هو لجميع المحتمين به.","18:31":"لأنه من هو إله غير الرب! ومن هو صخرة سوى إلهنا!","18:32":"الإله الذي يمنطقني بالقوة ويصير طريقي كاملا.","18:33":"الذي يجعل رجلي كالإيل وعلى مرتفعاتي يقيمني.","18:34":"الذي يعلم يدي القتال فتحنى بذراعي قوس من نحاس.","18:35":"وتجعل لي ترس خلاصك ويمينك تعضدني ولطفك يعظمني.","18:36":"توسع خطواتي تحتي فلم تتقلقل عقباي.","18:37":"أتبع أعدائي فأدركهم ولا أرجع حتى أفنيهم.","18:38":"أسحقهم فلا يستطيعون القيام. يسقطون تحت رجلي.","18:39":"تمنطقني بقوة للقتال. تصرع تحتي القائمين علي.","18:40":"وتعطيني أقفية أعدائي ومبغضي أفنيهم.","18:41":"يصرخون ولا مخلص. إلى الرب فلا يستجيب لهم.","18:42":"فأسحقهم كالغبار قدام الريح. مثل طين الأسواق أطرحهم.","18:43":"تنقذني من مخاصمات الشعب. تجعلني رأسا للأمم. شعب لم أعرفه يتعبد لي.","18:44":"من سماع الأذن يسمعون لي. بنو الغرباء يتذللون لي.","18:45":"بنو الغرباء يبلون ويزحفون من حصونهم.","18:46":"حي هو الرب ومبارك صخرتي ومرتفع إله خلاصي","18:47":"الإله المنتقم لي والذي يخضع الشعوب تحتي.","18:48":"منجي من أعدائي. رافعي أيضا فوق القائمين علي. من الرجل الظالم تنقذني.","18:49":"لذلك أحمدك يا رب في الأمم وأرنم لاسمك.","18:50":"برج خلاص لملكه والصانع رحمة لمسيحه لداود ونسله إلى الأبد.","19:1":"لإمام المغنين. مزمور لداود السماوات تحدث بمجد الله والفلك يخبر بعمل يديه.","19:2":"يوم إلى يوم يذيع كلاما وليل إلى ليل يبدي علما.","19:3":"لا قول ولا كلام. لا يسمع صوتهم.","19:4":"في كل الأرض خرج منطقهم وإلى أقصى المسكونة كلماتهم. جعل للشمس مسكنا فيها","19:5":"وهي مثل العروس الخارج من حجلته. يبتهج مثل الجبار للسباق في الطريق.","19:6":"من أقصى السماوات خروجها ومدارها إلى أقاصيها ولا شيء يختفي من حرها.","19:7":"ناموس الرب كامل يرد النفس. شهادات الرب صادقة تصير الجاهل حكيما.","19:8":"وصايا الرب مستقيمة تفرح القلب. أمر الرب طاهر ينير العينين.","19:9":"خوف الرب نقي ثابت إلى الأبد. أحكام الرب حق عادلة كلها.","19:10":"أشهى من الذهب والإبريز الكثير وأحلى من العسل وقطر الشهاد.","19:11":"أيضا عبدك يحذر بها وفي حفظها ثواب عظيم.","19:12":"السهوات من يشعر بها! من الخطايا المستترة أبرئني.","19:13":"أيضا من المتكبرين احفظ عبدك فلا يتسلطوا علي. حينئذ أكون كاملا وأتبرأ من ذنب عظيم.","19:14":"لتكن أقوال فمي وفكر قلبي مرضية أمامك يا رب صخرتي ووليي.","20:1":"لإمام المغنين. مزمور لداود ليستجب لك الرب في يوم الضيق. ليرفعك اسم إله يعقوب.","20:2":"ليرسل لك عونا من قدسه ومن صهيون ليعضدك.","20:3":"ليذكر كل تقدماتك ويستسمن محرقاتك. سلاه.","20:4":"ليعطك حسب قلبك ويتمم كل رأيك.","20:5":"نترنم بخلاصك وباسم إلهنا نرفع رايتنا. ليكمل الرب كل سؤلك.","20:6":"الآن عرفت أن الرب مخلص مسيحه. يستجيبه من سماء قدسه بجبروت خلاص يمينه.","20:7":"هؤلاء بالمركبات وهؤلاء بالخيل - أما نحن فاسم الرب إلهنا نذكر.","20:8":"هم جثوا وسقطوا أما نحن فقمنا وانتصبنا.","20:9":"يا رب خلص. ليستجب لنا الملك في يوم دعائنا.","21:1":"لإمام المغنين. مزمور لداود يا رب بقوتك يفرح الملك وبخلاصك كيف لا يبتهج جدا!","21:2":"شهوة قلبه أعطيته وملتمس شفتيه لم تمنعه. سلاه.","21:3":"لأنك تتقدمه ببركات خير. وضعت على رأسه تاجا من إبريز.","21:4":"حياة سألك فأعطيته. طول الأيام إلى الدهر والأبد.","21:5":"عظيم مجده بخلاصك جلالا وبهاء تضع عليه.","21:6":"لأنك جعلته بركات إلى الأبد. تفرحه ابتهاجا أمامك.","21:7":"لأن الملك يتوكل على الرب وبنعمة العلي لا يتزعزع.","21:8":"تصيب يدك جميع أعدائك. يمينك تصيب كل مبغضيك.","21:9":"تجعلهم مثل تنور نار في زمان حضورك. الرب بسخطه يبتلعهم وتأكلهم النار.","21:10":"تبيد ثمرهم من الأرض وذريتهم من بين بني آدم.","21:11":"لأنهم نصبوا عليك شرا. تفكروا بمكيدة. لم يستطيعوها.","21:12":"لأنك تجعلهم يتولون. تفوق السهام على أوتارك تلقاء وجوههم.","21:13":"ارتفع يا رب بقوتك. نرنم وننغم بجبروتك.","22:1":"لإمام المغنين على [أيلة الصبح]. مزمور لداود إلهي! إلهي لماذا تركتني بعيدا عن خلاصي عن كلام زفيري؟","22:2":"إلهي في النهار أدعو فلا تستجيب. في الليل أدعو فلا هدوء لي.","22:3":"وأنت القدوس الجالس بين تسبيحات إسرائيل.","22:4":"عليك اتكل آباؤنا. اتكلوا فنجيتهم.","22:5":"إليك صرخوا فنجوا. عليك اتكلوا فلم يخزوا.","22:6":"أما أنا فدودة لا إنسان. عار عند البشر ومحتقر الشعب.","22:7":"كل الذين يرونني يستهزئون بي. يفغرون الشفاه وينغضون الرأس قائلين:","22:8":"[اتكل على الرب فلينجه. لينقذه لأنه سر به].","22:9":"لأنك أنت جذبتني من البطن. جعلتني مطمئنا على ثديي أمي.","22:10":"عليك ألقيت من الرحم. من بطن أمي أنت إلهي.","22:11":"لا تتباعد عني لأن الضيق قريب. لأنه لا معين.","22:12":"أحاطت بي ثيران كثيرة. أقوياء باشان اكتنفتني.","22:13":"فغروا علي أفواههم كأسد مفترس مزمجر.","22:14":"كالماء انسكبت. انفصلت كل عظامي. صار قلبي كالشمع. قد ذاب في وسط أمعائي.","22:15":"يبست مثل شقفة قوتي ولصق لساني بحنكي وإلى تراب الموت تضعني.","22:16":"لأنه قد أحاطت بي كلاب. جماعة من الأشرار اكتنفتني. ثقبوا يدي ورجلي.","22:17":"أحصي كل عظامي وهم ينظرون ويتفرسون في.","22:18":"يقسمون ثيابي بينهم وعلى لباسي يقترعون.","22:19":"أما أنت يا رب فلا تبعد. يا قوتي أسرع إلى نصرتي.","22:20":"أنقذ من السيف نفسي. من يد الكلب وحيدتي.","22:21":"خلصني من فم الأسد ومن قرون بقر الوحش استجب لي.","22:22":"أخبر باسمك إخوتي. في وسط الجماعة أسبحك.","22:23":"يا خائفي الرب سبحوه. مجدوه يا معشر ذرية يعقوب. واخشوه يا زرع إسرائيل جميعا.","22:24":"لأنه لم يحتقر ولم يرذل مسكنة المسكين ولم يحجب وجهه عنه بل عند صراخه إليه استمع.","22:25":"من قبلك تسبيحي في الجماعة العظيمة. أوفي بنذوري قدام خائفيه.","22:26":"يأكل الودعاء ويشبعون. يسبح الرب طالبوه. تحيا قلوبكم إلى الأبد.","22:27":"تذكر وترجع إلى الرب كل أقاصي الأرض. وتسجد قدامك كل قبائل الأمم.","22:28":"لأن للرب الملك وهو المتسلط على الأمم.","22:29":"أكل وسجد كل سميني الأرض. قدامه يجثو كل من ينحدر إلى التراب ومن لم يحي نفسه.","22:30":"الذرية تتعبد له. يخبر عن الرب الجيل الآتي.","22:31":"يأتون ويخبرون ببره شعبا سيولد بأنه قد فعل.","23:1":"مزمور لداود الرب راعي فلا يعوزني شيء.","23:2":"في مراع خضر يربضني. إلى مياه الراحة يوردني.","23:3":"يرد نفسي. يهديني إلى سبل البر من أجل اسمه.","23:4":"أيضا إذا سرت في وادي ظل الموت لا أخاف شرا لأنك أنت معي. عصاك وعكازك هما يعزيانني.","23:5":"ترتب قدامي مائدة تجاه مضايقي. مسحت بالدهن رأسي. كأسي ريا.","23:6":"إنما خير ورحمة يتبعانني كل أيام حياتي وأسكن في بيت الرب إلى مدى الأيام.","24:1":"لداود. مزمور للرب الأرض وملؤها. المسكونة وكل الساكنين فيها.","24:2":"لأنه على البحار أسسها وعلى الأنهار ثبتها.","24:3":"من يصعد إلى جبل الرب ومن يقوم في موضع قدسه؟","24:4":"الطاهر اليدين والنقي القلب الذي لم يحمل نفسه إلى الباطل ولا حلف كذبا.","24:5":"يحمل بركة من عند الرب وبرا من إله خلاصه.","24:6":"هذا هو الجيل الطالبه الملتمسون وجهك يا يعقوب. سلاه.","24:7":"ارفعن أيتها الأرتاج رؤوسكن وارتفعن أيتها الأبواب الدهريات فيدخل ملك المجد.","24:8":"من هو هذا ملك المجد؟ الرب القدير الجبار الرب الجبار في القتال!","24:9":"ارفعن أيتها الأرتاج رؤوسكن وارفعنها أيتها الأبواب الدهريات فيدخل ملك المجد؟","24:10":"من هو هذا ملك المجد! رب الجنود هو ملك المجد. سلاه","25:1":"لداود إليك يا رب أرفع نفسي.","25:2":"يا إلهي عليك توكلت فلا تدعني أخزى. لا تشمت بي أعدائي.","25:3":"أيضا كل منتظريك لا يخزوا. ليخز الغادرون بلا سبب.","25:4":"طرقك يا رب عرفني. سبلك علمني.","25:5":"دربني في حقك وعلمني. لأنك أنت إله خلاصي. إياك انتظرت اليوم كله.","25:6":"اذكر مراحمك يا رب وإحساناتك لأنها منذ الأزل هي.","25:7":"لا تذكر خطايا صباي ولا معاصي. كرحمتك اذكرني أنت من أجل جودك يا رب.","25:8":"الرب صالح ومستقيم لذلك يعلم الخطاة الطريق.","25:9":"يدرب الودعاء في الحق ويعلم الودعاء طرقه.","25:10":"كل سبل الرب رحمة وحق لحافظي عهده وشهاداته.","25:11":"من أجل اسمك يا رب اغفر إثمي لأنه عظيم.","25:12":"من هو الإنسان الخائف الرب؟ يعلمه طريقا يختاره.","25:13":"نفسه في الخير تبيت ونسله يرث الأرض.","25:14":"سر الرب لخائفيه وعهده لتعليمهم.","25:15":"عيناي دائما إلى الرب لأنه هو يخرج رجلي من الشبكة.","25:16":"التفت إلي وارحمني لأني وحد ومسكين أنا.","25:17":"افرج ضيقات قلبي. من شدائدي أخرجني.","25:18":"انظر إلى ذلي وتعبي واغفر جميع خطاياي.","25:19":"انظر إلى أعدائي لأنهم قد كثروا. وبغضا ظلما أبغضوني.","25:20":"احفظ نفسي وأنقذني. لا أخزى لأني عليك توكلت.","25:21":"يحفظني الكمال والاستقامة لأني انتظرتك.","25:22":"يا الله افد إسرائيل من كل ضيقاته.","26:1":"لداود اقض لي يا رب لأني بكمالي سلكت وعلى الرب توكلت بلا تقلقل.","26:2":"جربني يا رب وامتحني. صف كليتي وقلبي.","26:3":"لأن رحمتك أمام عيني. وقد سلكت بحقك.","26:4":"لم أجلس مع أناس السوء ومع الماكرين لا أدخل.","26:5":"أبغضت جماعة الأثمة ومع الأشرار لا أجلس.","26:6":"أغسل يدي في النقاوة فأطوف بمذبحك يا رب","26:7":"لأسمع بصوت الحمد وأحدث بجميع عجائبك.","26:8":"يا رب أحببت محل بيتك وموضع مسكن مجدك.","26:9":"لا تجمع مع الخطاة نفسي ولا مع رجال الدماء حياتي.","26:10":"الذين في أيديهم رذيلة ويمينهم ملآنة رشوة.","26:11":"أما أنا فبكمالي أسلك. افدني وارحمني.","26:12":"رجلي واقفة على سهل. في الجماعات أبارك الرب.","27:1":"لداود الرب نوري وخلاصي ممن أخاف؟ الرب حصن حياتي ممن أرتعب؟","27:2":"عند ما اقترب إلي الأشرار ليأكلوا لحمي مضايقي وأعدائي عثروا وسقطوا.","27:3":"إن نزل علي جيش لا يخاف قلبي. إن قامت علي حرب ففي ذلك أنا مطمئن.","27:4":"واحدة سألت من الرب وإياها ألتمس: أن أسكن في بيت الرب كل أيام حياتي لكي أنظر إلى جمال الرب وأتفرس في هيكله.","27:5":"لأنه يخبئني في مظلته في يوم الشر. يسترني بستر خيمته. على صخرة يرفعني.","27:6":"والآن يرتفع رأسي على أعدائي حولي فأذبح في خيمته ذبائح الهتاف. أغني وأرنم للرب.","27:7":"استمع يا رب. بصوتي أدعو فارحمني واستجب لي.","27:8":"لك قال قلبي: [قلت اطلبوا وجهي. وجهك يا رب أطلب].","27:9":"لا تحجب وجهك عني. لا تخيب بسخط عبدك. قد كنت عوني فلا ترفضني ولا تتركني يا إله خلاصي.","27:10":"إن أبي وأمي قد تركاني والرب يضمني.","27:11":"علمني يا رب طريقك واهدني في سبيل مستقيم بسبب أعدائي.","27:12":"لا تسلمني إلى مرام مضايقي لأنه قد قام علي شهود زور ونافث ظلم.","27:13":"لولا أنني آمنت بأن أرى جود الرب في أرض الأحياء","27:14":"انتظر الرب. ليتشدد وليتشجع قلبك وانتظر الرب.","28:1":"لداود إليك يا رب أصرخ. يا صخرتي لا تتصامم من جهتي لئلا تسكت عني فأشبه الهابطين في الجب.","28:2":"استمع صوت تضرعي إذ أستغيث بك وأرفع يدي إلى محراب قدسك.","28:3":"لا تجذبني مع الأشرار ومع فعلة الإثم المخاطبين أصحابهم بالسلام والشر في قلوبهم.","28:4":"أعطهم حسب فعلهم وحسب شر أعمالهم. حسب صنع أيديهم أعطهم. رد عليهم معاملتهم.","28:5":"لأنهم لم ينتبهوا إلى أفعال الرب ولا إلى أعمال يديه يهدمهم ولا يبنيهم.","28:6":"مبارك الرب لأنه سمع صوت تضرعي.","28:7":"الرب عزي وترسي. عليه اتكل قلبي فانتصرت. ويبتهج قلبي وبأغنيتي أحمده.","28:8":"الرب عز لهم وحصن خلاص مسيحه هو.","28:9":"خلص شعبك وبارك ميراثك وارعهم واحملهم إلى الأبد.","29:1":"مزمور لداود قدموا للرب يا أبناء الله قدموا للرب مجدا وعزا.","29:2":"قدموا للرب مجد اسمه. اسجدوا للرب في زينة مقدسة.","29:3":"صوت الرب على المياه. إله المجد أرعد. الرب فوق المياه الكثيرة.","29:4":"صوت الرب بالقوة. صوت الرب بالجلال.","29:5":"صوت الرب مكسر الأرز ويكسر الرب أرز لبنان","29:6":"ويمرحها مثل عجل. لبنان وسريون مثل فرير البقر الوحشي.","29:7":"صوت الرب يقدح لهب نار.","29:8":"صوت الرب يزلزل البرية. يزلزل الرب برية قادش.","29:9":"صوت الرب يولد الإيل ويكشف الوعور وفي هيكله الكل قائل: [مجد].","29:10":"الرب بالطوفان جلس ويجلس الرب ملكا إلى الأبد.","29:11":"الرب يعطي عزا لشعبه. الرب يبارك شعبه بالسلام.","30:1":"مزمور أغنية تدشين البيت. لداود أعظمك يا رب لأنك نشلتني ولم تشمت بي أعدائي.","30:2":"يا رب إلهي استغثت بك فشفيتني.","30:3":"يا رب أصعدت من الهاوية نفسي. أحييتني من بين الهابطين في الجب.","30:4":"رنموا للرب يا أتقياءه واحمدوا ذكر قدسه.","30:5":"لأن للحظة غضبه. حياة في رضاه. عند المساء يبيت البكاء وفي الصباح ترنم.","30:6":"وأنا قلت في طمأنينتي: [لا أتزعزع إلى الأبد].","30:7":"يا رب برضاك ثبت لجبلي عزا. حجبت وجهك فصرت مرتاعا.","30:8":"إليك يا رب أصرخ وإلى السيد أتضرع.","30:9":"ما الفائدة من دمي إذا نزلت إلى الحفرة؟ هل يحمدك التراب؟ هل يخبر بحقك؟","30:10":"استمع يا رب وارحمني. يا رب كن معينا لي.","30:11":"حولت نوحي إلى رقص لي. حللت مسحي ومنطقتني فرحا","30:12":"لكي تترنم لك روحي ولا تسكت. يا رب إلهي إلى الأبد أحمدك.","31:1":"لإمام المغنين. مزمور لداود عليك يا رب توكلت. لا تدعني أخزى مدى الدهر. بعدلك نجني.","31:2":"أمل إلي أذنك. سريعا أنقذني. كن لي صخرة حصن بيت ملجأ لتخليصي.","31:3":"لأن صخرتي ومعقلي أنت. من أجل اسمك تهديني وتقودني.","31:4":"أخرجني من الشبكة التي خبأوها لي لأنك أنت حصني.","31:5":"في يدك أستودع روحي. فديتني يا رب إله الحق.","31:6":"أبغضت الذين يراعون أباطيل كاذبة. أما أنا فعلى الرب توكلت.","31:7":"أبتهج وأفرح برحمتك لأنك نظرت إلى مذلتي وعرفت في الشدائد نفسي","31:8":"ولم تحبسني في يد العدو بل أقمت في الرحب رجلي.","31:9":"ارحمني يا رب لأني في ضيق. خسفت من الغم عيني. نفسي وبطني.","31:10":"لأن حياتي قد فنيت بالحزن وسنيني بالتنهد. ضعفت بشقاوتي قوتي وبليت عظامي.","31:11":"عند كل أعدائي صرت عارا وعند جيراني بالكلية ورعبا لمعارفي. الذين رأوني خارجا هربوا عني.","31:12":"نسيت من القلب مثل الميت. صرت مثل إناء متلف.","31:13":"لأني سمعت مذمة من كثيرين. الخوف مستدير بي بمؤامرتهم معا علي. تفكروا في أخذ نفسي.","31:14":"أما أنا فعليك توكلت يا رب. قلت: [إلهي أنت].","31:15":"في يدك آجالي. نجني من يد أعدائي ومن الذين يطردونني.","31:16":"أضئ بوجهك على عبدك. خلصني برحمتك.","31:17":"يا رب لا تدعني أخزى لأني دعوتك. ليخز الأشرار. ليسكتوا في الهاوية.","31:18":"لتبكم شفاه الكذب المتكلمة على الصديق بوقاحة بكبرياء واستهانة.","31:19":"ما أعظم جودك الذي ذخرته لخائفيك وفعلته للمتكلين عليك تجاه بني البشر.","31:20":"تسترهم بستر وجهك من مكايد الناس. تخفيهم في مظلة من مخاصمة الألسن.","31:21":"مبارك الرب لأنه قد جعل عجبا رحمته لي في مدينة محصنة.","31:22":"وأنا قلت في حيرتي: [إني قد انقطعت من قدام عينيك]. ولكنك سمعت صوت تضرعي إذ صرخت إليك.","31:23":"أحبوا الرب يا جميع أتقيائه. الرب حافظ الأمانة ومجاز بكثرة العامل بالكبرياء.","31:24":"لتتشدد ولتتشجع قلوبكم يا جميع المنتظرين الرب","32:1":"لداود. قصيدة طوبى للذي غفر إثمه وسترت خطيته.","32:2":"طوبى لرجل لا يحسب له الرب خطية ولا في روحه غش.","32:3":"لما سكت بليت عظامي من زفيري اليوم كله","32:4":"لأن يدك ثقلت علي نهارا وليلا. تحولت رطوبتي إلى يبوسة القيظ. سلاه.","32:5":"أعترف لك بخطيتي ولا أكتم إثمي. قلت: [أعترف للرب بذنبي] وأنت رفعت أثام خطيتي. سلاه.","32:6":"لهذا يصلي لك كل تقي في وقت يجدك فيه. عند غمارة المياه الكثيرة إياه لا تصيب.","32:7":"أنت ستر لي. من الضيق تحفظني. بترنم النجاة تكتنفني. سلاه.","32:8":"أعلمك وأرشدك الطريق التي تسلكها. أنصحك. عيني عليك.","32:9":"لا تكونوا كفرس أو بغل بلا فهم. بلجام وزمام زينته يكم لئلا يدنو إليك.","32:10":"كثيرة هي نكبات الشرير أما المتوكل على الرب فالرحمة تحيط به.","32:11":"افرحوا بالرب وابتهجوا يا أيها الصديقون واهتفوا يا جميع المستقيمي القلوب.","33:1":"اهتفوا أيها الصديقون بالرب. بالمستقيمين يليق التسبيح.","33:2":"احمدوا الرب بالعود. بربابة ذات عشرة أوتار رنموا له.","33:3":"غنوا له أغنية جديدة. أحسنوا العزف بهتاف.","33:4":"لأن كلمة الرب مستقيمة وكل صنعه بالأمانة.","33:5":"يحب البر والعدل. امتلأت الأرض من رحمة الرب.","33:6":"بكلمة الرب صنعت السماوات وبنسمة فمه كل جنودها.","33:7":"يجمع كند أمواه اليم. يجعل اللجج في أهراء.","33:8":"لتخش الرب كل الأرض ومنه ليخف كل سكان المسكونة.","33:9":"لأنه قال فكان. هو أمر فصار.","33:10":"الرب أبطل مؤامرة الأمم. لاشى أفكار الشعوب.","33:11":"أما مؤامرة الرب فإلى الأبد تثبت. أفكار قلبه إلى دور فدور.","33:12":"طوبى للأمة التي الرب إلهها الشعب الذي اختاره ميراثا لنفسه.","33:13":"من السماوات نظر الرب. رأى جميع بني البشر.","33:14":"من مكان سكناه تطلع إلى جميع سكان الأرض.","33:15":"المصور قلوبهم جميعا المنتبه إلى كل أعمالهم.","33:16":"لن يخلص الملك بكثرة الجيش. الجبار لا ينقذ بعظم القوة.","33:17":"باطل هو الفرس لأجل الخلاص وبشدة قوته لا ينجي.","33:18":"هوذا عين الرب على خائفيه الراجين رحمته","33:19":"لينجي من الموت أنفسهم وليستحييهم في الجوع.","33:20":"أنفسنا انتظرت الرب. معونتنا وترسنا هو.","33:21":"لأنه به تفرح قلوبنا لأننا على اسمه القدوس اتكلنا.","33:22":"لتكن يا رب رحمتك علينا حسبما انتظرناك.","34:1":"لداود عندما غير عقله قدام أبيمالك فطرده فانطلق أبارك الرب في كل حين. دائما تسبيحه في فمي.","34:2":"بالرب تفتخر نفسي. يسمع الودعاء فيفرحون.","34:3":"عظموا الرب معي ولنعل اسمه معا.","34:4":"طلبت إلى الرب فاستجاب لي ومن كل مخاوفي أنقذني.","34:5":"نظروا إليه واستناروا ووجوههم لم تخجل.","34:6":"هذا المسكين صرخ والرب استمعه ومن كل ضيقاته خلصه.","34:7":"ملاك الرب حال حول خائفيه وينجيهم.","34:8":"ذوقوا وانظروا ما أطيب الرب! طوبى للرجل المتوكل عليه.","34:9":"اتقوا الرب يا قديسيه لأنه ليس عوز لمتقيه.","34:10":"الأشبال احتاجت وجاعت وأما طالبو الرب فلا يعوزهم شيء من الخير.","34:11":"هلم أيها البنون استمعوا إلي فأعلمكم مخافة الرب.","34:12":"من هو الإنسان الذي يهوى الحياة ويحب كثرة الأيام ليرى خيرا؟","34:13":"صن لسانك عن الشر وشفتيك عن التكلم بالغش.","34:14":"حد عن الشر واصنع الخير. اطلب السلامة واسع وراءها.","34:15":"عينا الرب نحو الصديقين وأذناه إلى صراخهم.","34:16":"وجه الرب ضد عاملي الشر ليقطع من الأرض ذكرهم.","34:17":"أولئك صرخوا والرب سمع ومن كل شدائدهم أنقذهم.","34:18":"قريب هو الرب من المنكسري القلوب ويخلص المنسحقي الروح.","34:19":"كثيرة هي بلايا الصديق ومن جميعها ينجيه الرب.","34:20":"يحفظ جميع عظامه. واحد منها لا ينكسر.","34:21":"الشر يميت الشرير ومبغضو الصديق يعاقبون.","34:22":"الرب فادي نفوس عبيده وكل من اتكل عليه لا يعاقب.","35:1":"لداود خاصم يا رب مخاصمي. قاتل مقاتلي.","35:2":"أمسك مجنا وترسا وانهض إلى معونتي","35:3":"وأشرع رمحا وصد تلقاء مطاردي. قل لنفسي: [خلاصك أنا].","35:4":"ليخز وليخجل الذين يطلبون نفسي. ليرتد إلى الوراء ويخجل المتفكرون بإساءتي.","35:5":"ليكونوا مثل العصافة قدام الريح وملاك الرب داحرهم.","35:6":"ليكن طريقهم ظلاما وزلقا وملاك الرب طاردهم.","35:7":"لأنهم بلا سبب أخفوا لي هوة شبكتهم. بلا سبب حفروا لنفسي.","35:8":"لتأته التهلكة وهو لا يعلم ولتنشب به الشبكة التي أخفاها وفي التهلكة نفسها ليقع.","35:9":"أما نفسي فتفرح بالرب وتبتهج بخلاصه.","35:10":"جميع عظامي تقول: [يا رب من مثلك المنقذ المسكين ممن هو أقوى منه والفقير والبائس من سالبه؟].","35:11":"شهود زور يقومون وعما لم أعلم يسألونني.","35:12":"يجازونني عن الخير شرا ثكلا لنفسي.","35:13":"أما أنا ففي مرضهم كان لباسي مسحا. أذللت بالصوم نفسي. وصلاتي إلى حضني ترجع.","35:14":"كأنه قريب كأنه أخي كنت أتمشى. كمن ينوح على أمه انحنيت حزينا.","35:15":"ولكنهم في ظلعي فرحوا واجتمعوا. اجتمعوا علي شاتمين ولم أعلم. مزقوا ولم يكفوا.","35:16":"بين الفجار المجان لأجل كعكة حرقوا علي أسنانهم.","35:17":"يا رب إلى متى تنظر؟ استرد نفسي من تهلكاتهم وحيدتي من الأشبال.","35:18":"أحمدك في الجماعة الكثيرة. في شعب عظيم أسبحك.","35:19":"لا يشمت بي الذين هم أعدائي باطلا ولا يتغامز بالعين الذين يبغضونني بلا سبب.","35:20":"لأنهم لا يتكلمون بالسلام وعلى الهادئين في الأرض يتفكرون بكلام مكر.","35:21":"فغروا علي أفواههم. قالوا: [هه هه! قد رأت أعيننا].","35:22":"قد رأيت يا رب. لا تسكت يا سيد. لا تبتعد عني.","35:23":"استيقظ وانتبه إلى حكمي يا إلهي وسيدي إلى دعواي.","35:24":"اقض لي حسب عدلك يا رب إلهي فلا يشمتوا بي.","35:25":"لا يقولوا في قلوبهم: [هه! شهوتنا]. لا يقولوا: [قد ابتلعناه!]","35:26":"ليخز وليخجل معا الفرحون بمصيبتي. ليلبس الخزي والخجل المتعظمون علي.","35:27":"ليهتف ويفرح المبتغون حقي وليقولوا دائما: [ليتعظم الرب المسرور بسلامة عبده].","35:28":"ولساني يلهج بعدلك. اليوم كله بحمدك.","36:1":"لإمام المغنين. لعبد الرب داود نأمة معصية الشرير في داخل قلبي أن ليس خوف الله أمام عينيه.","36:2":"لأنه ملق نفسه لنفسه من جهة وجدان إثمه وبغضه.","36:3":"كلام فمه إثم وغش. كف عن التعقل عن عمل الخير.","36:4":"يتفكر بالإثم على مضجعه. يقف في طريق غير صالح. لا يرفض الشر.","36:5":"يا رب في السماوات رحمتك. أمانتك إلى الغمام.","36:6":"عدلك مثل جبال الله وأحكامك لجة عظيمة. الناس والبهائم تخلص يا رب.","36:7":"ما أكرم رحمتك يا الله فبنو البشر في ظل جناحيك يحتمون.","36:8":"يروون من دسم بيتك ومن نهر نعمك تسقيهم.","36:9":"لأن عندك ينبوع الحياة. بنورك نرى نورا.","36:10":"أدم رحمتك للذين يعرفونك وعدلك للمستقيمي القلب.","36:11":"لا تأتني رجل الكبرياء ويد الأشرار لا تزحزحني.","36:12":"هناك سقط فاعلو الإثم. دحروا فلم يستطيعوا القيام.","37:1":"لداود لا تغر من الأشرار ولا تحسد عمال الإثم","37:2":"فإنهم مثل الحشيش سريعا يقطعون ومثل العشب الأخضر يذبلون.","37:3":"اتكل على الرب وافعل الخير. اسكن الأرض وارع الأمانة.","37:4":"وتلذذ بالرب فيعطيك سؤل قلبك.","37:5":"سلم للرب طريقك واتكل عليه وهو يجري","37:6":"ويخرج مثل النور برك وحقك مثل الظهيرة.","37:7":"انتظر الرب واصبر له ولا تغر من الذي ينجح في طريقه من الرجل المجري مكايد.","37:8":"كف عن الغضب واترك السخط ولا تغر لفعل الشر","37:9":"لأن عاملي الشر يقطعون والذين ينتظرون الرب هم يرثون الأرض.","37:10":"بعد قليل لا يكون الشرير. تطلع في مكانه فلا يكون.","37:11":"أما الودعاء فيرثون الأرض ويتلذذون في كثرة السلامة.","37:12":"الشرير يتفكر ضد الصديق ويحرق عليه أسنانه.","37:13":"الرب يضحك به لأنه رأى أن يومه آت!","37:14":"الأشرار قد سلوا السيف ومدوا قوسهم لرمي المسكين والفقير لقتل المستقيم طريقهم.","37:15":"سيفهم يدخل في قلبهم وقسيهم تنكسر.","37:16":"القليل الذي للصديق خير من ثروة أشرار كثيرين.","37:17":"لأن سواعد الأشرار تنكسر وعاضد الصديقين الرب.","37:18":"الرب عارف أيام الكملة وميراثهم إلى الأبد يكون.","37:19":"لا يخزون في زمن السوء وفي أيام الجوع يشبعون.","37:20":"لأن الأشرار يهلكون وأعداء الرب كبهاء المراعي. فنوا. كالدخان فنوا.","37:21":"الشرير يستقرض ولا يفي أما الصديق فيترأف ويعطي.","37:22":"لأن المباركين منه يرثون الأرض والملعونين منه يقطعون.","37:23":"من قبل الرب تتثبت خطوات الإنسان وفي طريقه يسر.","37:24":"إذا سقط لا ينطرح لأن الرب مسند يده.","37:25":"أيضا كنت فتى وقد شخت ولم أر صديقا تخلي عنه ولا ذرية له تلتمس خبزا.","37:26":"اليوم كله يترأف ويقرض ونسله للبركة.","37:27":"حد عن الشر وافعل الخير واسكن إلى الأبد.","37:28":"لأن الرب يحب الحق ولا يتخلى عن أتقيائه. إلى الأبد يحفظون. أما نسل الأشرار فينقطع.","37:29":"الصديقون يرثون الأرض ويسكنونها إلى الأبد.","37:30":"فم الصديق يلهج بالحكمة ولسانه ينطق بالحق.","37:31":"شريعة إلهه في قلبه. لا تتقلقل خطواته.","37:32":"الشرير يراقب الصديق محاولا أن يميته.","37:33":"الرب لا يتركه في يده ولا يحكم عليه عند محاكمته.","37:34":"انتظر الرب واحفظ طريقه فيرفعك لترث الأرض. إلى انقراض الأشرار تنظر.","37:35":"قد رأيت الشرير عاتيا وارفا مثل شجرة شارقة ناضرة.","37:36":"عبر فإذا هو ليس بموجود والتمسته فلم يوجد.","37:37":"لاحظ الكامل وانظر المستقيم فإن العقب لإنسان السلامة.","37:38":"أما الأشرار فيبادون جميعا. عقب الأشرار ينقطع.","37:39":"أما خلاص الصديقين فمن قبل الرب حصنهم في زمان الضيق.","37:40":"ويعينهم الرب وينجيهم. ينقذهم من الأشرار ويخلصهم لأنهم احتموا به.","38:1":"مزمور لداود للتذكير يا رب لا توبخني بسخطك ولا تؤدبني بغيظك","38:2":"لأن سهامك قد انتشبت في ونزلت علي يدك.","38:3":"ليست في جسدي صحة من جهة غضبك. ليست في عظامي سلامة من جهة خطيتي.","38:4":"لأن آثامي قد طمت فوق رأسي. كحمل ثقيل أثقل مما أحتمل.","38:5":"قد أنتنت قاحت حبر ضربي من جهة حماقتي.","38:6":"لويت. انحنيت إلى الغاية. اليوم كله ذهبت حزينا.","38:7":"لأن خاصرتي قد امتلأتا احتراقا وليست في جسدي صحة.","38:8":"خدرت وانسحقت إلى الغاية. كنت أئن من زفير قلبي.","38:9":"يا رب أمامك كل تأوهي وتنهدي ليس بمستور عنك.","38:10":"قلبي خافق. قوتي فارقتني ونور عيني أيضا ليس معي.","38:11":"أحبائي وأصحابي يقفون تجاه ضربتي وأقاربي وقفوا بعيدا.","38:12":"وطالبو نفسي نصبوا شركا والملتمسون لي الشر تكلموا بالمفاسد واليوم كله يلهجون بالغش.","38:13":"وأما أنا فكأصم لا أسمع. وكأبكم لا يفتح فاه.","38:14":"وأكون مثل إنسان لا يسمع وليس في فمه حجة.","38:15":"لأني لك يا رب صبرت أنت تستجيب يا رب إلهي.","38:16":"لأني قلت: [لئلا يشمتوا بي]. عندما زلت قدمي تعظموا علي.","38:17":"لأني موشك أن أظلع ووجعي مقابلي دائما.","38:18":"لأنني أخبر بإثمي وأغتم من خطيتي.","38:19":"وأما أعدائي فأحياء. عظموا. والذين يبغضونني ظلما كثروا.","38:20":"والمجازون عن الخير بشر يقاومونني لأجل اتباعي الصلاح.","38:21":"لا تتركني يا رب. يا إلهي لا تبعد عني.","38:22":"أسرع إلى معونتي يا رب يا خلاصي.","39:1":"لإمام المغنين. ليدوثون. مزمور لداود قلت أتحفظ لسبيلي من الخطإ بلساني. أحفظ لفمي كمامة فيما الشرير مقابلي.","39:2":"صمت صمتا سكت عن الخير فتحرك وجعي.","39:3":"حمي قلبي في جوفي. عند لهجي اشتعلت النار. تكلمت بلساني.","39:4":"عرفني يا رب نهايتي ومقدار أيامي كم هي فأعلم كيف أنا زائل.","39:5":"هوذا جعلت أيامي أشبارا وعمري كلا شيء قدامك. إنما نفخة كل إنسان قد جعل. سلاه.","39:6":"إنما كخيال يتمشى الإنسان. إنما باطلا يضجون. يذخر ذخائر ولا يدري من يضمها.","39:7":"والآن ماذا انتظرت يا رب؟ رجائي فيك هو.","39:8":"من كل معاصي نجني. لا تجعلني عارا عند الجاهل.","39:9":"صمت. لا أفتح فمي لأنك أنت فعلت.","39:10":"ارفع عني ضربك. من مهاجمة يدك أنا قد فنيت.","39:11":"بتأديبات إن أدبت الإنسان من أجل إثمه أفنيت مثل العث مشتهاه. إنما كل إنسان نفخة. سلاه.","39:12":"استمع صلاتي يا رب واصغ إلى صراخي. لا تسكت عن دموعي. لأني أنا غريب عندك. نزيل مثل جميع آبائي.","39:13":"اقتصر عني فأتبلج قبل أن أذهب فلا أوجد.","40:1":"لإمام المغنين. مزمور لداود انتظارا انتظرت الرب فمال إلي وسمع صراخي","40:2":"وأصعدني من جب الهلاك من طين الحمأة وأقام على صخرة رجلي. ثبت خطواتي","40:3":"وجعل في فمي ترنيمة جديدة تسبيحة لإلهنا. كثيرون يرون ويخافون ويتوكلون على الرب.","40:4":"طوبى للرجل الذي جعل الرب متكله ولم يلتفت إلى الغطاريس والمنحرفين إلى الكذب.","40:5":"كثيرا ما جعلت أنت أيها الرب إلهي عجائبك وأفكارك من جهتنا. لا تقوم لديك. لأخبرن وأتكلمن بها. زادت عن أن تعد.","40:6":"بذبيحة وتقدمة لم تسر. أذني فتحت. محرقة وذبيحة خطية لم تطلب.","40:7":"حينئذ قلت: [هئنذا جئت. بدرج الكتاب مكتوب عني","40:8":"أن أفعل مشيئتك يا إلهي سررت. وشريعتك في وسط أحشائي].","40:9":"بشرت ببر في جماعة عظيمة. هوذا شفتاي لم أمنعهما. أنت يا رب علمت.","40:10":"لم أكتم عدلك في وسط قلبي. تكلمت بأمانتك وخلاصك. لم أخف رحمتك وحقك عن الجماعة العظيمة.","40:11":"أما أنت يا رب فلا تمنع رأفتك عني. تنصرني رحمتك وحقك دائما.","40:12":"لأن شرورا لا تحصى قد اكتنفتني. حاقت بي آثامي ولا أستطيع أن أبصر. كثرت أكثر من شعر رأسي وقلبي قد تركني.","40:13":"ارتض يا رب بأن تنجيني. يا رب إلى معونتي أسرع.","40:14":"ليخز وليخجل معا الذين يطلبون نفسي لإهلاكها. ليرتد إلى الوراء وليخز المسرورون بأذيتي.","40:15":"ليستوحش من أجل خزيهم القائلون لي: [هه هه!]","40:16":"ليبتهج ويفرح بك جميع طالبيك. ليقل أبدا محبو خلاصك: [يتعظم الرب].","40:17":"أما أنا فمسكين وبائس. الرب يهتم بي. عوني ومنقذي أنت. يا إلهي لا تبطئ.","41:1":"لإمام المغنين. مزمور لداود طوبى للذي ينظر إلى المسكين. في يوم الشر ينجيه الرب.","41:2":"الرب يحفظه ويحييه. يغتبط في الأرض ولا يسلمه إلى مرام أعدائه.","41:3":"الرب يعضده وهو على فراش الضعف. مهدت مضجعه كله في مرضه.","41:4":"أنا قلت: [يا رب ارحمني. اشف نفسي لأني قد أخطأت إليك].","41:5":"أعدائي يتقاولون علي بشر: [متى يموت ويبيد اسمه؟]","41:6":"وإن دخل ليراني يتكلم بالكذب. قلبه يجمع لنفسه إثما. يخرج في الخارج يتكلم.","41:7":"كل مبغضي يتناجون معا علي. علي تفكروا بأذيتي.","41:8":"يقولون: [أمر رديء قد انسكب عليه. حيث اضطجع لا يعود يقوم].","41:9":"أيضا رجل سلامتي الذي وثقت به آكل خبزي رفع علي عقبه!","41:10":"أما أنت يا رب فارحمني وأقمني فأجازيهم.","41:11":"بهذا علمت أنك سررت بي أنه لم يهتف علي عدوي.","41:12":"أما أنا فبكمالي دعمتني وأقمتني قدامك إلى الأبد.","41:13":"مبارك الرب إله إسرائيل من الأزل وإلى الأبد. آمين فآمين.","42:1":"لإمام المغنين. قصيدة لبني قورح كما يشتاق الإيل إلى جداول المياه هكذا تشتاق نفسي إليك يا الله.","42:2":"عطشت نفسي إلى الله إلى الإله الحي. متى أجيء وأتراءى قدام الله!","42:3":"صارت لي دموعي خبزا نهارا وليلا إذ قيل لي كل يوم أين إلهك","42:4":"هذه أذكرها فأسكب نفسي علي. لأني كنت أمر مع الجماع أتدرج معهم إلى بيت الله بصوت ترنم وحمد جمهور معيد.","42:5":"لماذا أنت منحنية يا نفسي ولماذا تئنين في؟ ارتجي الله لأني بعد أحمده لأجل خلاص وجهه.","42:6":"يا إلهي نفسي منحنية في لذلك أذكرك من أرض الأردن وجبال حرمون من جبل مصعر.","42:7":"غمر ينادي غمرا عند صوت ميازيبك. كل تياراتك ولججك طمت علي.","42:8":"بالنهار يوصي الرب رحمته وبالليل تسبيحه عندي صلاة لإله حياتي.","42:9":"أقول لله صخرتي: [لماذا نسيتني؟ لماذا أذهب حزينا من مضايقة العدو؟]","42:10":"بسحق في عظامي عيرني مضايقي بقولهم لي كل يوم: [أين إلهك؟]","42:11":"لماذا أنت منحنية يا نفسي ولماذا تئنين في؟ ترجي الله لأني بعد أحمده خلاص وجهي وإلهي.","43:1":"اقض لي يا الله وخاصم مخاصمتي مع أمة غير راحمة ومن إنسان غش وظلم نجني.","43:2":"لأنك أنت إله حصني. لماذا رفضتني؟ لماذا أتمشى حزينا من مضايقة العدو؟","43:3":"أرسل نورك وحقك هما يهديانني ويأتيان بي إلى جبل قدسك وإلى مساكنك.","43:4":"فآتي إلى مذبح الله إلى الله بهجة فرحي وأحمدك بالعود يا الله إلهي.","43:5":"لماذا أنت منحنية يا نفسي ولماذا تئنين في؟ ترجي الله لأني بعد أحمده خلاص وجهي وإلهي.","44:1":"لإمام المغنين. لبني قورح. قصيدة اللهم بآذاننا قد سمعنا. آباؤنا أخبرونا بعمل عملته في أيامهم في أيام القدم.","44:2":"أنت بيدك استأصلت الأمم وغرستهم. حطمت شعوبا ومددتهم.","44:3":"لأنه ليس بسيفهم امتلكوا الأرض ولا ذراعهم خلصتهم لكن يمينك وذراعك ونور وجهك لأنك رضيت عنهم.","44:4":"أنت هو ملكي يا الله. فأمر بخلاص يعقوب.","44:5":"بك ننطح مضايقينا. باسمك ندوس القائمين علينا.","44:6":"لأني على قوسي لا أتكل وسيفي لا يخلصني.","44:7":"لأنك أنت خلصتنا من مضايقينا وأخزيت مبغضينا.","44:8":"بالله نفتخر اليوم كله واسمك نحمد إلى الدهر. سلاه.","44:9":"لكنك قد رفضتنا وأخجلتنا ولا تخرج مع جنودنا.","44:10":"ترجعنا إلى الوراء عن العدو ومبغضونا نهبوا لأنفسهم.","44:11":"جعلتنا كالضأن أكلا. ذريتنا بين الأمم.","44:12":"بعت شعبك بغير مال وما ربحت بثمنهم.","44:13":"تجعلنا عارا عند جيراننا هزأة وسخرة للذين حولنا.","44:14":"تجعلنا مثلا بين الشعوب. لإنغاض الرأس بين الأمم.","44:15":"اليوم كله خجلي أمامي وخزي وجهي قد غطاني.","44:16":"من صوت المعير والشاتم. من وجه عدو ومنتقم.","44:17":"هذا كله جاء علينا وما نسيناك ولا خنا في عهدك.","44:18":"لم يرتد قلبنا إلى وراء ولا مالت خطوتنا عن طريقك","44:19":"حتى سحقتنا في مكان التنانين وغطيتنا بظل الموت.","44:20":"إن نسينا اسم إلهنا أو بسطنا أيدينا إلى إله غريب","44:21":"أفلا يفحص الله عن هذا لأنه هو يعرف خفيات القلب؟","44:22":"لأننا من أجلك نمات اليوم كله. قد حسبنا مثل غنم للذبح.","44:23":"استيقظ. لماذا تتغافى يا رب؟ انتبه. لا ترفض إلى الأبد.","44:24":"لماذا تحجب وجهك وتنسى مذلتنا وضيقنا؟","44:25":"لأن أنفسنا منحنية إلى التراب. لصقت في الأرض بطوننا.","44:26":"قم عونا لنا وافدنا من أجل رحمتك.","45:1":"لإمام المغنين. على السوسن. لبني قورح. قصيدة. ترنيمة محبة فاض قلبي بكلام صالح. متكلم أنا بإنشائي للملك. لساني قلم كاتب ماهر.","45:2":"أنت أبرع جمالا من بني البشر. انسكبت النعمة على شفتيك لذلك باركك الله إلى الأبد.","45:3":"تقلد سيفك على فخذك أيها الجبار جلالك وبهاءك.","45:4":"وبجلالك اقتحم. اركب. من أجل الحق والدعة والبر فتريك يمينك مخاوف.","45:5":"نبلك المسنونة في قلب أعداء الملك. شعوب تحتك يسقطون.","45:6":"كرسيك يا الله إلى دهر الدهور. قضيب استقامة قضيب ملكك.","45:7":"أحببت البر وأبغضت الإثم من أجل ذلك مسحك الله إلهك بدهن الابتهاج أكثر من رفقائك.","45:8":"كل ثيابك مر وعود وسليخة. من قصور العاج سرتك الأوتار.","45:9":"بنات ملوك بين حظياتك. جعلت الملكة عن يمينك بذهب أوفير.","45:10":"اسمعي يا بنت وانظري وأميلي أذنك وانسي شعبك وبيت أبيك","45:11":"فيشتهي الملك حسنك لأنه هو سيدك فاسجدي له.","45:12":"وبنت صور أغنى الشعوب تترضى وجهك بهدية.","45:13":"كلها مجد ابنة الملك في خدرها. منسوجة بذهب ملابسها.","45:14":"بملابس مطرزة تحضر إلى الملك. في أثرها عذارى صاحباتها. مقدمات إليك","45:15":"يحضرن بفرح وابتهاج. يدخلن إلى قصر الملك.","45:16":"عوضا عن آبائك يكون بنوك تقيمهم رؤساء في كل الأرض.","45:17":"أذكر اسمك في كل دور فدور. من أجل ذلك تحمدك الشعوب إلى الدهر والأبد.","46:1":"لإمام المغنين. لبني قورح. على الجواب. ترنيمة الله لنا ملجأ وقوة. عونا في الضيقات وجد شديدا.","46:2":"لذلك لا نخشى ولو تزحزحت الأرض ولو انقلبت الجبال إلى قلب البحار.","46:3":"تعج وتجيش مياهها. تتزعزع الجبال بطموها. سلاه.","46:4":"نهر سواقيه تفرح مدينة الله مقدس مساكن العلي.","46:5":"الله في وسطها فلن تتزعزع. يعينها الله عند إقبال الصبح.","46:6":"عجت الأمم. تزعزعت الممالك. أعطى صوته ذابت الأرض.","46:7":"رب الجنود معنا. ملجأنا إله يعقوب. سلاه.","46:8":"هلموا انظروا أعمال الله كيف جعل خربا في الأرض.","46:9":"مسكن الحروب إلى أقصى الأرض. يكسر القوس ويقطع الرمح. المركبات يحرقها بالنار.","46:10":"كفوا واعلموا أني أنا الله. أتعالى بين الأمم. أتعالى في الأرض.","46:11":"رب الجنود معنا. ملجأنا إله يعقوب. سلاه.","47:1":"لإمام المغنين. لبني قورح. مزمور يا جميع الأمم صفقوا بالأيادي. اهتفوا لله بصوت الابتهاج.","47:2":"لأن الرب علي مخوف ملك كبير على كل الأرض.","47:3":"يخضع الشعوب تحتنا والأمم تحت أقدامنا.","47:4":"يختار لنا نصيبنا فخر يعقوب الذي أحبه. سلاه.","47:5":"صعد الله بهتاف الرب بصوت الصور.","47:6":"رنموا لله رنموا. رنموا لملكنا رنموا.","47:7":"لأن الله ملك الأرض كلها رنموا قصيدة.","47:8":"ملك الله على الأمم. الله جلس على كرسي قدسه.","47:9":"شرفاء الشعوب اجتمعوا. شعب إله إبراهيم. لأن لله مجان الأرض. هو متعال جدا.","48:1":"تسبيحة. مزمور لبني قورح عظيم هو الرب وحميد جدا في مدينة إلهنا جبل قدسه.","48:2":"جميل الارتفاع فرح كل الأرض جبل صهيون. فرح أقاصي الشمال مدينة الملك العظيم.","48:3":"الله في قصورها يعرف ملجأ.","48:4":"لأنه هوذا الملوك اجتمعوا. مضوا جميعا.","48:5":"لما رأوا بهتوا ارتاعوا فروا.","48:6":"أخذتهم الرعدة هناك والمخاض كوالدة","48:7":"بريح شرقية تكسر سفن ترشيش.","48:8":"كما سمعنا هكذا رأينا في مدينة رب الجنود في مدينة إلهنا. الله يثبتها إلى الأبد. سلاه.","48:9":"ذكرنا يا الله رحمتك في وسط هيكلك.","48:10":"نظير اسمك يا الله تسبيحك إلى أقاصي الأرض. يمينك ملآنة برا.","48:11":"يفرح جبل صهيون تبتهج بنات يهوذا من أجل أحكامك.","48:12":"طوفوا بصهيون ودوروا حولها. عدوا أبراجها.","48:13":"ضعوا قلوبكم على متارسها. تأملوا قصورها لكي تحدثوا بها جيلا آخر.","48:14":"لأن الله هذا هو إلهنا إلى الدهر والأبد. هو يهدينا حتى إلى الموت.","49:1":"لإمام المغنين. لبني قورح. مزمور اسمعوا هذا يا جميع الشعوب. أصغوا يا جميع سكان الدنيا","49:2":"عال ودون أغنياء وفقراء سواء.","49:3":"فمي يتكلم بالحكم ولهج قلبي فهم.","49:4":"أميل أذني إلى مثل وأوضح بعود لغزي.","49:5":"لماذا أخاف في أيام الشر عندما يحيط بي إثم متعقبي؟","49:6":"الذين يتكلون على ثروتهم وبكثرة غناهم يفتخرون.","49:7":"الأخ لن يفدي الإنسان فداء ولا يعطي الله كفارة عنه.","49:8":"وكريمة هي فدية نفوسهم فغلقت إلى الدهر -","49:9":"حتى يحيا إلى الأبد فلا يرى القبر.","49:10":"بل يراه! الحكماء يموتون. كذلك الجاهل والبليد يهلكان ويتركان ثروتهما لآخرين.","49:11":"باطنهم أن بيوتهم إلى الأبد مساكنهم إلى دور فدور. ينادون بأسمائهم في الأراضي.","49:12":"والإنسان في كرامة لا يبيت. يشبه البهائم التي تباد.","49:13":"هذا طريقهم اعتمادهم وخلفاؤهم يرتضون بأقوالهم. سلاه.","49:14":"مثل الغنم للهاوية يساقون. الموت يرعاهم ويسودهم المستقيمون. غداة وصورتهم تبلى. الهاوية مسكن لهم.","49:15":"إنما الله يفدي نفسي من يد الهاوية لأنه يأخذني. سلاه.","49:16":"لا تخش إذا استغنى إنسان إذا زاد مجد بيته.","49:17":"لأنه عند موته كله لا يأخذ. لا ينزل وراءه مجده.","49:18":"لأنه في حياته يبارك نفسه. ويحمدونك إذا أحسنت إلى نفسك.","49:19":"تدخل إلى جيل آبائه الذين لا يعاينون النور إلى الأبد.","49:20":"إنسان في كرامة ولا يفهم يشبه البهائم التي تباد.","50:1":"مزمور لآساف إله الآلهة الرب تكلم ودعا الأرض من مشرق الشمس إلى مغربها.","50:2":"من صهيون كمال الجمال الله أشرق.","50:3":"يأتي إلهنا ولا يصمت. نار قدامه تأكل وحوله عاصف جدا.","50:4":"يدعو السماوات من فوق والأرض إلى مداينة شعبه.","50:5":"اجمعوا إلي أتقيائي القاطعين عهدي على ذبيحة.","50:6":"وتخبر السماوات بعدله لأن الله هو الديان. سلاه.","50:7":"اسمع يا شعبي فأتكلم. يا إسرائيل فأشهد عليك. الله إلهك أنا.","50:8":"لا على ذبائحك أوبخك فإن محرقاتك هي دائما قدامي.","50:9":"لا آخذ من بيتك ثورا ولا من حظائرك أعتدة.","50:10":"لأن لي حيوان الوعر والبهائم على الجبال الألوف.","50:11":"قد علمت كل طيور الجبال ووحوش البرية عندي.","50:12":"إن جعت فلا أقول لك لأن لي المسكونة وملأها.","50:13":"هل آكل لحم الثيران أو أشرب دم التيوس؟","50:14":"اذبح لله حمدا وأوف العلي نذورك","50:15":"وادعني في يوم الضيق أنقذك فتمجدني.","50:16":"وللشرير قال الله: [ما لك تحدث بفرائضي وتحمل عهدي على فمك","50:17":"وأنت قد أبغضت التأديب وألقيت كلامي خلفك.","50:18":"إذا رأيت سارقا وافقته ومع الزناة نصيبك.","50:19":"أطلقت فمك بالشر ولسانك يخترع غشا.","50:20":"تجلس تتكلم على أخيك. لابن أمك تضع معثرة.","50:21":"هذه صنعت وسكت. ظننت أني مثلك. أوبخك وأصف خطاياك أمام عينيك.","50:22":"افهموا هذا يا أيها الناسون الله لئلا أفترسكم ولا منقذ.","50:23":"ذابح الحمد يمجدني والمقوم طريقه أريه خلاص الله].","51:1":"لإمام المغنين. مزمور لداود عندما جاء إليه ناثان النبي بعد ما دخل إلى بثشبع ارحمني يا الله حسب رحمتك. حسب كثرة رأفتك امح معاصي.","51:2":"اغسلني كثيرا من إثمي ومن خطيتي طهرني.","51:3":"لأني عارف بمعاصي وخطيتي أمامي دائما.","51:4":"إليك وحدك أخطأت والشر قدام عينيك صنعت لكي تتبرر في أقوالك وتزكو في قضائك.","51:5":"هئنذا بالإثم صورت وبالخطية حبلت بي أمي.","51:6":"ها قد سررت بالحق في الباطن ففي السريرة تعرفني حكمة.","51:7":"طهرني بالزوفا فأطهر. اغسلني فأبيض أكثر من الثلج.","51:8":"أسمعني سرورا وفرحا فتبتهج عظام سحقتها.","51:9":"استر وجهك عن خطاياي وامح كل آثامي.","51:10":"قلبا نقيا اخلق في يا الله وروحا مستقيما جدد في داخلي.","51:11":"لا تطرحني من قدام وجهك وروحك القدوس لا تنزعه مني.","51:12":"رد لي بهجة خلاصك وبروح منتدبة اعضدني.","51:13":"فأعلم الأثمة طرقك والخطاة إليك يرجعون.","51:14":"نجني من الدماء يا الله إله خلاصي فيسبح لساني برك.","51:15":"يا رب افتح شفتي فيخبر فمي بتسبيحك.","51:16":"لأنك لا تسر بذبيحة وإلا فكنت أقدمها. بمحرقة لا ترضى.","51:17":"ذبائح الله هي روح منكسرة. القلب المنكسر والمنسحق يا الله لا تحتقره.","51:18":"أحسن برضاك إلى صهيون. ابن أسوار أورشليم.","51:19":"حينئذ تسر بذبائح البر محرقة وتقدمة تامة. حينئذ يصعدون على مذبحك عجولا.","52:1":"لإمام المغنين. قصيدة لداود عندما جاء دواغ الأدومي وأخبر شاول وقال له: [جاء داود إلى بيت أخيمالك]. لماذا تفتخر بالشر أيها الجبار؟ رحمة الله هي كل يوم!","52:2":"لسانك يخترع مفاسد. كموسى مسنونة يعمل بالغش.","52:3":"أحببت الشر أكثر من الخير الكذب أكثر من التكلم بالصدق. سلاه.","52:4":"أحببت كل كلام مهلك ولسان غش.","52:5":"أيضا يهدمك الله إلى الأبد. يخطفك ويقلعك من مسكنك ويستأصلك من أرض الأحياء. سلاه.","52:6":"فيرى الصديقون ويخافون وعليه يضحكون:","52:7":"[هوذا الإنسان الذي لم يجعل الله حصنه بل اتكل على كثرة غناه واعتز بفساده].","52:8":"أما أنا فمثل زيتونة خضراء في بيت الله. توكلت على رحمة الله إلى الدهر والأبد.","52:9":"أحمدك إلى الدهر لأنك فعلت وأنتظر اسمك فإنه صالح قدام أتقيائك.","53:1":"لإمام المغنين على العود. قصيدة لداود قال الجاهل في قلبه: [ليس إله]. فسدوا ورجسوا رجاسة. ليس من يعمل صلاحا.","53:2":"الله من السماء أشرف على بني البشر لينظر: هل من فاهم طالب الله؟","53:3":"كلهم قد ارتدوا معا فسدوا ليس من يعمل صلاحا ليس ولا واحد.","53:4":"ألم يعلم فاعلو الإثم الذين يأكلون شعبي كما يأكلون الخبز والله لم يدعوا؟","53:5":"هناك خافوا خوفا ولم يكن خوف لأن الله قد بدد عظام محاصرك. أخزيتهم لأن الله قد رفضهم.","53:6":"ليت من صهيون خلاص إسرائيل. عند رد الله سبي شعبه يهتف يعقوب ويفرح إسرائيل.الأصحاح الرابع والخمسون لإمام المغنين على ذوات الأوتار. قصيدة لداود عندما أتى الزيفيون وقالوا لشاول: [أليس داود مختبئا عندنا؟]","54:1":"اللهم باسمك خلصني وبقوتك احكم لي.","54:2":"اسمع يا الله صلاتي. اصغ إلى كلام فمي.","54:3":"لأن غرباء قد قاموا علي وعتاة طلبوا نفسي. لم يجعلوا الله أمامهم. سلاه.","54:4":"هوذا الله معين لي. الرب بين عاضدي نفسي.","54:5":"يرجع الشر على أعدائي. بحقك أفنهم.","54:6":"أذبح لك منتدبا. أحمد اسمك يا رب لأنه صالح.","54:7":"لأنه من كل ضيق نجاني وبأعدائي رأت عيني.","55:1":"لإمام المغنين على ذوات الأوتار. قصيدة لداود اصغ يا الله إلى صلاتي ولا تتغاض عن تضرعي.","55:2":"استمع لي واستجب لي. أتحير في كربتي وأضطرب","55:3":"من صوت العدو من قبل ظلم الشرير. لأنهم يحيلون علي إثما وبغضب يضطهدونني.","55:4":"يمخض قلبي في داخلي وأهوال الموت سقطت علي","55:5":"خوف ورعدة أتيا علي وغشيني رعب.","55:6":"فقلت: [ليت لي جناحا كالحمامة فأطير وأستريح!","55:7":"هئنذا كنت أبعد هاربا وأبيت في البرية. سلاه.","55:8":"كنت أسرع في نجاتي من الريح العاصفة ومن النوء].","55:9":"أهلك يا رب فرق ألسنتهم لأني قد رأيت ظلما وخصاما في المدينة.","55:10":"نهارا وليلا يحيطون بها على أسوارها وإثم ومشقة في وسطها.","55:11":"مفاسد في وسطها ولا يبرح من ساحتها ظلم وغش.","55:12":"لأنه ليس عدو يعيرني فأحتمل. ليس مبغضي تعظم علي فأختبئ منه.","55:13":"بل أنت إنسان عديلي إلفي وصديقي","55:14":"الذي معه كانت تحلو لنا العشرة. إلى بيت الله كنا نذهب في الجمهور.","55:15":"ليبغتهم الموت. لينحدروا إلى الهاوية أحياء لأن في مساكنهم في وسطهم شرورا.","55:16":"أما أنا فإلى الله أصرخ والرب يخلصني.","55:17":"مساء وصباحا وظهرا أشكو وأنوح فيسمع صوتي.","55:18":"فدى بسلام نفسي من قتال علي لأنهم بكثرة كانوا حولي.","55:19":"يسمع الله فيذلهم والجالس منذ القدم. سلاه. الذين ليس لهم تغير ولا يخافون الله.","55:20":"ألقى يديه على مسالميه. نقض عهده.","55:21":"أنعم من الزبدة فمه وقلبه قتال. ألين من الزيت كلماته وهي سيوف مسلولة.","55:22":"ألق على الرب همك فهو يعولك. لا يدع الصديق يتزعزع إلى الأبد.","55:23":"وأنت يا الله تحدرهم إلى جب الهلاك. رجال الدماء والغش لا ينصفون أيامهم. أما أنا فأتكل عليك.","56:1":"لإمام المغنين على [الحمامة البكماء بين الغرباء]. مذهبة لداود عندما أخذه الفلسطينيون في جت. ارحمني يا الله لأن الإنسان يتهممني واليوم كله محاربا يضايقني.","56:2":"تهممني أعدائي اليوم كله لأن كثيرين يقاومونني بكبرياء.","56:3":"في يوم خوفي أنا عليك أتكل.","56:4":"الله أفتخر بكلامه. على الله توكلت فلا أخاف. ماذا يصنعه بي البشر!","56:5":"اليوم كله يحرفون كلامي. علي كل أفكارهم بالشر.","56:6":"يجتمعون يختفون يلاحظون خطواتي عندما ترصدوا نفسي.","56:7":"على إثمهم جازهم. بغضب أخضع الشعوب يا الله.","56:8":"تيهاني راقبت. اجعل أنت دموعي في زقك. أما هي في سفرك؟","56:9":"حينئذ ترتد أعدائي إلى الوراء في يوم أدعوك فيه. هذا قد علمته لأن الله لي.","56:10":"الله أفتخر بكلامه. الرب أفتخر بكلامه.","56:11":"على الله توكلت فلا أخاف. ماذا يصنعه بي الإنسان؟","56:12":"اللهم علي نذورك. أوفي ذبائح شكر لك.","56:13":"لأنك نجيت نفسي من الموت. نعم ورجلي من الزلق لكي أسير قدام الله في نور الأحياء.","57:1":"لإمام المغنين. على [لا تهلك]. مذهبة لداود عندما هرب من قدام شاول في المغارة. ارحمني يا الله ارحمني لأنه بك احتمت نفسي وبظل جناحيك أحتمي إلى أن تعبر المصائب.","57:2":"أصرخ إلى الله العلي إلى الله المحامي عني.","57:3":"يرسل من السماء ويخلصني. عير الذي يتهممني. سلاه. يرسل الله رحمته وحقه.","57:4":"نفسي بين الأشبال. أضطجع بين المتقدين بني آدم. أسنانهم أسنة وسهام ولسانهم سيف ماض.","57:5":"ارتفع اللهم على السماوات. ليرتفع على كل الأرض مجدك.","57:6":"هيأوا شبكة لخطواتي. انحنت نفسي. حفروا قدامي حفرة. سقطوا في وسطها. سلاه.","57:7":"ثابت قلبي يا الله ثابت قلبي. أغني وأرنم.","57:8":"استيقظ يا مجدي. استيقظي يا رباب ويا عود. أنا أستيقظ سحرا.","57:9":"أحمدك بين الشعوب يا رب. أرنم لك بين الأمم.","57:10":"لأن رحمتك قد عظمت إلى السماوات وإلى الغمام حقك.","57:11":"ارتفع اللهم على السماوات. ليرتفع على كل الأرض مجدك.","58:1":"لإمام المغنين. على [لا تهلك]. لداود. مذهبة أحقا بالحق الأخرس تتكلمون بالمستقيمات تقضون يا بني آدم؟","58:2":"بل بالقلب تعملون شرورا في الأرض. ظلم أيديكم تزنون.","58:3":"زاغ الأشرار من الرحم. ضلوا من البطن متكلمين كذبا.","58:4":"لهم حمة مثل حمة الحية. مثل الصل الأصم يسد أذنه","58:5":"الذي لا يستمع إلى صوت الحواة الراقين رقى حكيم.","58:6":"اللهم كسر أسنانهم في أفواههم. اهشم أضراس الأشبال يا رب.","58:7":"ليذوبوا كالماء ليذهبوا. إذا فوق سهامه فلتنب.","58:8":"كما يذوب الحلزون ماشيا. مثل سقط المرأة لا يعاينوا الشمس.","58:9":"قبل أن تشعر قدوركم بالشوك نيئا أو محروقا يجرفهم.","58:10":"يفرح الصديق إذا رأى النقمة. يغسل خطواته بدم الشرير.","58:11":"ويقول الإنسان: [إن للصديق ثمرا. إنه يوجد إله قاض في الأرض].","59:1":"لإمام المغنين. على [لا تهلك]. مذهبة لداود لما أرسل شاول وراقبوا البيت ليقتلوه. أنقذني من أعدائي يا إلهي. من مقاومي احمني.","59:2":"نجني من فاعلي الإثم ومن رجال الدماء خلصني","59:3":"لأنهم يكمنون لنفسي. الأقوياء يجتمعون علي لا لإثمي ولا لخطيتي يا رب.","59:4":"بلا إثم مني يجرون ويعدون أنفسهم. استيقظ إلى لقائي وانظر.","59:5":"وأنت يا رب إله الجنود إله إسرائيل انتبه لتطالب كل الأمم. كل غادر أثيم لا ترحم. سلاه.","59:6":"يعودون عند المساء يهرون مثل الكلب ويدورون في المدينة.","59:7":"هوذا يبقون بأفواههم. سيوف في شفاههم. لأنهم يقولون: [من سامع؟]","59:8":"أما أنت يا رب فتضحك بهم. تستهزئ بجميع الأمم.","59:9":"من قوته إليك ألتجئ لأن الله ملجإي.","59:10":"إلهي رحمته تتقدمني. الله يريني بأعدائي.","59:11":"لا تقتلهم لئلا ينسى شعبي. تيههم بقوتك وأهبطهم يا رب ترسنا.","59:12":"خطية أفواههم هي كلام شفاههم. وليؤخذوا بكبريائهم ومن اللعنة ومن الكذب الذي يحدثون به.","59:13":"أفن بحنق أفن ولا يكونوا وليعلموا أن الله متسلط في يعقوب إلى أقاصي الأرض. سلاه.","59:14":"ويعودون عند المساء. يهرون مثل الكلب ويدورون في المدينة.","59:15":"هم يتيهون للأكل. إن لم يشبعوا ويبيتوا.","59:16":"أما أنا فأغني بقوتك وأرنم بالغداة برحمتك لأنك كنت ملجأ لي ومناصا في يوم ضيقي.","59:17":"يا قوتي لك أرنم لأن الله ملجإي إله رحمتي.","60:1":"لإمام المغنين على السوسن. شهادة مذهبة لداود للتعليم. عند محاربته أرام النهرين وأرام صوبة فرجع يوآب وضرب من أدوم في وادي الملح اثني عشر ألفا. يا الله رفضتنا. اقتحمتنا. سخطت. أرجعنا.","60:2":"زلزلت الأرض. فصمتها. اجبر كسرها لأنها متزعزعة.","60:3":"أريت شعبك عسرا. سقيتنا خمر الترنح.","60:4":"أعطيت خائفيك راية ترفع لأجل الحق. سلاه.","60:5":"لكي ينجو أحباؤك. خلص بيمينك واستجب لي.","60:6":"الله قد تكلم بقدسه. أبتهج. أقسم شكيم وأقيس وادي سكوت.","60:7":"لي جلعاد ولي منسى وأفرايم خوذة رأسي. يهوذا صولجاني.","60:8":"موآب مرحضتي. على أدوم أطرح نعلي. يا فلسطين اهتفي علي.","60:9":"من يقودني إلى المدينة المحصنة؟ من يهديني إلى أدوم؟","60:10":"أليس أنت يا الله الذي رفضتنا ولا تخرج يا الله مع جيوشنا؟","60:11":"أعطنا عونا في الضيق فباطل هو خلاص الإنسان.","60:12":"بالله نصنع ببأس وهو يدوس أعداءنا.","61:1":"لإمام المغنين على ذوات الأوتار. لداود اسمع يا الله صراخي واصغ إلى صلاتي.","61:2":"من أقصى الأرض أدعوك إذا غشي على قلبي. إلى صخرة أرفع مني تهديني.","61:3":"لأنك كنت ملجأ لي برج قوة من وجه العدو.","61:4":"لأسكنن في مسكنك إلى الدهور. أحتمي بستر جناحيك. سلاه.","61:5":"لأنك أنت يا الله استمعت نذوري. أعطيت ميراث خائفي اسمك.","61:6":"إلى أيام الملك تضيف أياما. سنينه كدور فدور.","61:7":"يجلس قدام الله إلى الدهر. اجعل رحمة وحقا يحفظانه.","61:8":"هكذا أرنم لاسمك إلى الأبد. لوفاء نذوري يوما فيوما.","62:1":"لإمام المغنين على [يدوثون]. مزمور لداود إنما لله انتظرت نفسي. من قبله خلاصي.","62:2":"إنما هو صخرتي وخلاصي ملجإي. لا أتزعزع كثيرا.","62:3":"إلى متى تهجمون على الإنسان؟ تهدمونه كلكم كحائط منقض كجدار واقع!","62:4":"إنما يتآمرون ليدفعوه عن شرفه. يرضون بالكذب. بأفواههم يباركون وبقلوبهم يلعنون. سلاه.","62:5":"إنما لله انتظري يا نفسي لأن من قبله رجائي.","62:6":"إنما هو صخرتي وخلاصي. ملجإي فلا أتزعزع.","62:7":"على الله خلاصي ومجدي. صخرة قوتي محتماي في الله.","62:8":"توكلوا عليه في كل حين يا قوم. اسكبوا قدامه قلوبكم. الله ملجأ لنا. سلاه.","62:9":"إنما باطل بنو آدم. كذب بنو البشر. في الموازين هم إلى فوق. هم من باطل أجمعون.","62:10":"لا تتكلوا على الظلم ولا تصيروا باطلا في الخطف. إن زاد الغنى فلا تضعوا عليه قلبا.","62:11":"مرة واحدة تكلم الرب وهاتين الاثنتين سمعت أن العزة لله.","62:12":"ولك يا رب الرحمة لأنك أنت تجازي الإنسان كعمله.","63:1":"مزمور لداود لما كان في برية يهوذا يا الله إلهي أنت. إليك أبكر. عطشت إليك نفسي يشتاق إليك جسدي في أرض ناشفة ويابسة بلا ماء","63:2":"لكي أبصر قوتك ومجدك كما قد رأيتك في قدسك.","63:3":"لأن رحمتك أفضل من الحياة. شفتاي تسبحانك.","63:4":"هكذا أباركك في حياتي. باسمك أرفع يدي.","63:5":"كما من شحم ودسم تشبع نفسي وبشفتي الابتهاج يسبحك فمي.","63:6":"إذا ذكرتك على فراشي في السهد ألهج بك","63:7":"لأنك كنت عونا لي وبظل جناحيك أبتهج.","63:8":"التصقت نفسي بك. يمينك تعضدني.","63:9":"أما الذين هم للتهلكة يطلبون نفسي فيدخلون في أسافل الأرض.","63:10":"يدفعون إلى يدي السيف. يكونون نصيبا لبنات آوى.","63:11":"أما الملك فيفرح بالله. يفتخر كل من يحلف به. لأن أفواه المتكلمين بالكذب تسد.","64:1":"لإمام المغنين. مزمور لداود استمع يا الله صوتي في شكواي. من خوف العدو احفظ حياتي.","64:2":"استرني من مؤامرة الأشرار من جمهور فاعلي الإثم","64:3":"الذين صقلوا ألسنتهم كالسيف. فوقوا سهمهم كلاما مرا","64:4":"ليرموا الكامل في المختفى بغتة. يرمونه ولا يخشون.","64:5":"يشددون أنفسهم لأمر رديء. يتحادثون بطمر فخاخ. قالوا: [من يراهم؟]","64:6":"يخترعون إثما تمموا اختراعا محكما. وداخل الإنسان وقلبه عميق.","64:7":"فيرميهم الله بسهم. بغتة كانت ضربتهم.","64:8":"ويوقعون ألسنتهم على أنفسهم. ينغض الرأس كل من ينظر إليهم.","64:9":"ويخشى كل إنسان ويخبر بفعل الله وبعمله يفطنون.","64:10":"يفرح الصديق بالرب ويحتمي به ويبتهج كل المستقيمي القلوب.","65:1":"لإمام المغنين. مزمور لداود. تسبيحة لك ينبغي التسبيح يا الله في صهيون ولك يوفى النذر.","65:2":"يا سامع الصلاة إليك يأتي كل بشر.","65:3":"آثام قد قويت علي. معاصينا أنت تكفر عنها.","65:4":"طوبى للذي تختاره وتقربه ليسكن في ديارك. لنشبعن من خير بيتك قدس هيكلك.","65:5":"بمخاوف في العدل تستجيبنا يا إله خلاصنا يا متكل جميع أقاصي الأرض والبحر البعيدة.","65:6":"المثبت الجبال بقوته المتنطق بالقدرة","65:7":"المهدئ عجيج البحار عجيج أمواجها وضجيج الأمم.","65:8":"وتخاف سكان الأقاصي من آياتك. تجعل مطالع الصباح والمساء تبتهج.","65:9":"تعهدت الأرض وجعلتها تفيض. تغنيها جدا. سواقي الله ملآنة ماء. تهيئ طعامهم لأنك هكذا تعدها.","65:10":"أرو أتلامها. مهد أخاديدها. بالغيوث تحللها. تبارك غلتها.","65:11":"كللت السنة بجودك وآثارك تقطر دسما.","65:12":"تقطر مراعي البرية وتتنطق الآكام بالبهجة.","65:13":"اكتست المروج غنما والأودية تتعطف برا. تهتف وأيضا تغني.","66:1":"لإمام المغنين. تسبيحة. مزمور اهتفي لله يا كل الأرض.","66:2":"رنموا بمجد اسمه. اجعلوا تسبيحه ممجدا.","66:3":"قولوا لله: [ما أهيب أعمالك. من عظم قوتك تتملق لك أعداؤك.","66:4":"كل الأرض تسجد لك وترنم لك. ترنم لاسمك]. سلاه.","66:5":"هلم انظروا أعمال الله. فعله المرهب نحو بني آدم.","66:6":"حول البحر إلى يبس وفي النهر عبروا بالرجل. هناك فرحنا به.","66:7":"متسلط بقوته إلى الدهر. عيناه تراقبان الأمم. المتمردون لا يرفعن أنفسهم. سلاه.","66:8":"باركوا إلهنا يا أيها الشعوب وسمعوا صوت تسبيحه.","66:9":"الجاعل أنفسنا في الحياة ولم يسلم أرجلنا إلى الزلل.","66:10":"لأنك جربتنا يا الله. محصتنا كمحص الفضة.","66:11":"أدخلتنا إلى الشبكة. جعلت ضغطا على متوننا.","66:12":"ركبت أناسا على رؤوسنا. دخلنا في النار والماء ثم أخرجتنا إلى الخصب.","66:13":"أدخل إلى بيتك بمحرقات أوفيك نذوري","66:14":"التي نطقت بها شفتاي وتكلم بها فمي في ضيقي.","66:15":"أصعد لك محرقات سمينة مع بخور كباش. أقدم بقرا مع تيوس. سلاه","66:16":"هلم اسمعوا فأخبركم يا كل الخائفين الله بما صنع لنفسي.","66:17":"صرخت إليه بفمي وتبجيل على لساني.","66:18":"إن راعيت إثما في قلبي لا يستمع لي الرب.","66:19":"لكن قد سمع الله. أصغى إلى صوت صلاتي.","66:20":"مبارك الله الذي لم يبعد صلاتي ولا رحمته عني.","67:1":"لإمام المغنين على ذوات الأوتار. مزمور. تسبيحة ليتحنن الله علينا وليباركنا. لينر بوجهه علينا. سلاه.","67:2":"لكي يعرف في الأرض طريقك وفي كل الأمم خلاصك.","67:3":"يحمدك الشعوب يا الله. يحمدك الشعوب كلهم.","67:4":"تفرح وتبتهج الأمم لأنك تدين الشعوب بالاستقامة وأمم الأرض تهديهم. سلاه.","67:5":"يحمدك الشعوب يا الله. يحمدك الشعوب كلهم.","67:6":"الأرض أعطت غلتها. يباركنا الله إلهنا.","67:7":"يباركنا الله وتخشاه كل أقاصي الأرض.","68:1":"لإمام المغنين. لداود. مزمور. تسبيحة يقوم الله. يتبدد أعداؤه ويهرب مبغضوه من أمام وجهه.","68:2":"كما يذرى الدخان تذريهم. كما يذوب الشمع قدام النار يبيد الأشرار قدام الله.","68:3":"والصديقون يفرحون. يبتهجون أمام الله ويطفرون فرحا.","68:4":"غنوا لله. رنموا لاسمه. أعدوا طريقا للراكب في القفار باسمه ياه واهتفوا أمامه.","68:5":"أبو اليتامى وقاضي الأرامل الله في مسكن قدسه.","68:6":"الله مسكن المتوحدين في بيت. مخرج الأسرى إلى فلاح. إنما المتمردون يسكنون الرمضاء.","68:7":"اللهم عند خروجك أمام شعبك عند صعودك في القفر - سلاه.","68:8":"الأرض ارتعدت. السماوات أيضا قطرت أمام وجه الله. سيناء نفسه من وجه الله إله إسرائيل.","68:9":"مطرا غزيرا نضحت يا الله. ميراثك وهو معي أنت أصلحته.","68:10":"قطيعك سكن فيه. هيأت بجودك للمساكين يا الله.","68:11":"الرب يعطي كلمة. المبشرات بها جند كثير:","68:12":"[ملوك جيوش يهربون يهربون. الملازمة البيت تقسم الغنائم.","68:13":"إذا اضطجعتم بين الحظائر فأجنحة حمامة مغشاة بفضة وريشها بصفرة الذهب].","68:14":"عندما شتت القدير ملوكا فيها أثلجت في صلمون.","68:15":"جبل الله جبل باشان. جبل أسنمة جبل باشان.","68:16":"لماذا أيتها الجبال المسنمة ترصدن الجبل الذي اشتهاه الله لسكنه؟ بل الرب يسكن فيه إلى الأبد.","68:17":"مركبات الله ربوات ألوف مكررة. الرب فيها. سينا في القدس.","68:18":"صعدت إلى العلاء. سبيت سبيا. قبلت عطايا بين الناس وأيضا المتمردين للسكن أيها الرب الإله.","68:19":"مبارك الرب يوما فيوما. يحملنا إله خلاصنا. سلاه.","68:20":"الله لنا إله خلاص وعند الرب السيد للموت مخارج.","68:21":"ولكن الله يسحق رؤوس أعدائه الهامة الشعراء للسالك في ذنوبه.","68:22":"قال الرب: [من باشان أرجع. أرجع من أعماق البحر","68:23":"لكي تصبغ رجلك بالدم. ألسن كلابك من الأعداء نصيبهم].","68:24":"رأوا طرقك يا الله طرق إلهي ملكي في القدس.","68:25":"من قدام المغنون. من وراء ضاربو الأوتار. في الوسط فتيات ضاربات الدفوف.","68:26":"في الجماعات باركوا الله الرب أيها الخارجون من عين إسرائيل.","68:27":"هناك بنيامين الصغير متسلطهم رؤساء يهوذا جلهم رؤساء زبولون رؤساء نفتالي.","68:28":"قد أمر إلهك بعزك. أيد يا الله هذا الذي فعلته لنا.","68:29":"من هيكلك فوق أورشليم لك تقدم ملوك هدايا.","68:30":"انتهر وحش القصب صوار الثيران مع عجول الشعوب المترامين بقطع فضة. شتت الشعوب الذين يسرون بالقتال.","68:31":"يأتي شرفاء من مصر. كوش تسرع بيديها إلى الله.","68:32":"يا ممالك الأرض غنوا لله. رنموا للسيد. سلاه.","68:33":"للراكب على سماء السماوات القديمة. هوذا يعطي صوته صوت قوة.","68:34":"أعطوا عزا لله. على إسرائيل جلاله وقوته في الغمام.","68:35":"مخوف أنت يا الله من مقادسك. إله إسرائيل هو المعطي قوة وشدة للشعب. مبارك الله!","69:1":"لإمام المغنين. على السوسن. لداود خلصني يا الله لأن المياه قد دخلت إلى نفسي.","69:2":"غرقت في حمأة عميقة وليس مقر. دخلت إلى أعماق المياه والسيل غمرني.","69:3":"تعبت من صراخي. يبس حلقي. كلت عيناي من انتظار إلهي.","69:4":"أكثر من شعر رأسي الذين يبغضونني بلا سبب. اعتز مستهلكي أعدائي ظلما. حينئذ رددت الذي لم أخطفه.","69:5":"يا الله أنت عرفت حماقتي وذنوبي عنك لم تخف.","69:6":"لا يخز بي منتظروك يا سيد رب الجنود. لا يخجل بي ملتمسوك يا إله إسرائيل.","69:7":"لأني من أجلك احتملت العار. غطى الخجل وجهي.","69:8":"صرت أجنبيا عند إخوتي وغريبا عند بني أمي.","69:9":"لأن غيرة بيتك أكلتني وتعييرات معيريك وقعت علي.","69:10":"وأبكيت بصوم نفسي فصار ذلك عارا علي.","69:11":"جعلت لباسي مسحا وصرت لهم مثلا.","69:12":"يتكلم في الجالسون في الباب وأغاني شرابي المسكر.","69:13":"أما أنا فلك صلاتي يا رب في وقت رضى. يا الله بكثرة رحمتك استجب لي بحق خلاصك.","69:14":"نجني من الطين فلا أغرق. نجني من مبغضي ومن أعماق المياه.","69:15":"لا يغمرني سيل المياه ولا يبتلعني العمق ولا تطبق الهاوية علي فاها.","69:16":"استجب لي يا رب لأن رحمتك صالحة. ككثرة مراحمك التفت إلي.","69:17":"ولا تحجب وجهك عن عبدك لأن لي ضيقا. استجب لي سريعا.","69:18":"اقترب إلى نفسي. فكها. بسبب أعدائي افدني.","69:19":"أنت عرفت عاري وخزيي وخجلي. قدامك جميع مضايقي.","69:20":"العار قد كسر قلبي فمرضت. انتظرت رقة فلم تكن ومعزين فلم أجد.","69:21":"ويجعلون في طعامي علقما وفي عطشي يسقونني خلا.","69:22":"لتصر مائدتهم قدامهم فخا وللآمنين شركا.","69:23":"لتظلم عيونهم عن البصر وقلقل متونهم دائما.","69:24":"صب عليهم سخطك وليدركهم حمو غضبك.","69:25":"لتصر دارهم خرابا وفي خيامهم لا يكن ساكن.","69:26":"لأن الذي ضربته أنت هم طردوه وبوجع الذين جرحتهم يتحدثون.","69:27":"اجعل إثما على إثمهم ولا يدخلوا في برك.","69:28":"ليمحوا من سفر الأحياء ومع الصديقين لا يكتبوا.","69:29":"أما أنا فمسكين وكئيب. خلاصك يا الله فليرفعني.","69:30":"أسبح اسم الله بتسبيح وأعظمه بحمد.","69:31":"فيستطاب عند الرب أكثر من ثور بقر ذي قرون وأظلاف.","69:32":"يرى ذلك الودعاء فيفرحون وتحيا قلوبكم يا طالبي الله.","69:33":"لأن الرب سامع للمساكين ولا يحتقر أسراه.","69:34":"تسبحه السماوات والأرض البحار وكل ما يدب فيها.","69:35":"لأن الله يخلص صهيون ويبني مدن يهوذا فيسكنون هناك ويرثونها.","69:36":"ونسل عبيده يملكونها ومحبو اسمه يسكنون فيها.","70:1":"لإمام المغنين. لداود للتذكير اللهم إلى تنجيتي يا رب إلى معونتي أسرع.","70:2":"ليخز ويخجل طالبو نفسي. ليرتد إلى خلف ويخجل المشتهون لي شرا.","70:3":"ليرجع من أجل خزيهم القائلون: [هه هه!]","70:4":"وليبتهج ويفرح بك كل طالبيك وليقل دائما محبو خلاصك: [ليتعظم الرب!]","70:5":"أما أنا فمسكين وفقير. اللهم أسرع إلي. معيني ومنقذي أنت. يا رب لا تبطؤ.","71:1":"بك يا رب احتميت فلا أخزى إلى الدهر.","71:2":"بعدلك نجني وأنقذني. أمل إلي أذنك وخلصني.","71:3":"كن لي صخرة ملجأ أدخله دائما. أمرت بخلاصي لأنك صخرتي وحصني.","71:4":"يا إلهي نجني من يد الشرير من كف فاعل الشر والظالم.","71:5":"لأنك أنت رجائي يا سيدي. الرب متكلي منذ صباي.","71:6":"عليك استندت من البطن وأنت مخرجي من أحشاء أمي. بك تسبيحي دائما.","71:7":"صرت كآية لكثيرين. أما أنت فملجإي القوي.","71:8":"يمتلئ فمي من تسبيحك اليوم كله من مجدك.","71:9":"لا ترفضني في زمن الشيخوخة. لا تتركني عند فناء قوتي.","71:10":"لأن أعدائي تقاولوا علي والذين يرصدون نفسي تآمروا معا","71:11":"قائلين: [إن الله قد تركه. الحقوه وأمسكوه لأنه لا منقذ له].","71:12":"يا الله لا تبعد عني. يا إلهي إلى معونتي أسرع.","71:13":"ليخز ويفن مخاصمو نفسي. ليلبس العار والخجل الملتمسون لي شرا.","71:14":"أما أنا فأرجو دائما وأزيد على كل تسبيحك.","71:15":"فمي يحدث بعدلك اليوم كله بخلاصك لأني لا أعرف لها أعدادا.","71:16":"آتي بجبروت السيد الرب. أذكر برك وحدك.","71:17":"اللهم قد علمتني منذ صباي وإلى الآن أخبر بعجائبك.","71:18":"وأيضا إلى الشيخوخة والشيب يا الله لا تتركني حتى أخبر بذراعك الجيل المقبل وبقوتك كل آت.","71:19":"وبرك إلى العلياء يا الله الذي صنعت العظائم. يا الله من مثلك!","71:20":"أنت الذي أريتنا ضيقات كثيرة ورديئة تعود فتحيينا ومن أعماق الأرض تعود فتصعدنا.","71:21":"تزيد عظمتي وترجع فتعزيني.","71:22":"فأنا أيضا أحمدك برباب حقك يا إلهي. أرنم لك بالعود يا قدوس إسرائيل.","71:23":"تبتهج شفتاي إذ أرنم لك ونفسي التي فديتها","71:24":"ولساني أيضا اليوم كله يلهج ببرك. لأنه قد خزي لأنه قد خجل الملتمسون لي شرا.","72:1":"لسليمان اللهم أعط أحكامك للملك وبرك لابن الملك.","72:2":"يدين شعبك بالعدل ومساكينك بالحق.","72:3":"تحمل الجبال سلاما للشعب والآكام بالبر.","72:4":"يقضي لمساكين الشعب. يخلص بني البائسين ويسحق الظالم.","72:5":"يخشونك ما دامت الشمس وقدام القمر إلى دور فدور.","72:6":"ينزل مثل المطر على الجزاز ومثل الغيوث الذارفة على الأرض.","72:7":"يشرق في أيامه الصديق وكثرة السلام إلى أن يضمحل القمر.","72:8":"ويملك من البحر إلى البحر ومن النهر إلى أقاصي الأرض.","72:9":"أمامه تجثو أهل البرية وأعداؤه يلحسون التراب.","72:10":"ملوك ترشيش والجزائر يرسلون تقدمة. ملوك شبا وسبأ يقدمون هدية","72:11":"ويسجد له كل الملوك. كل الأمم تتعبد له","72:12":"لأنه ينجي الفقير المستغيث والمسكين إذ لا معين له.","72:13":"يشفق على المسكين والبائس ويخلص أنفس الفقراء.","72:14":"من الظلم والخطف يفدي أنفسهم ويكرم دمهم في عينيه.","72:15":"ويعيش ويعطيه من ذهب شبا. ويصلي لأجله دائما. اليوم كله يباركه.","72:16":"تكون حفنة بر في الأرض في رؤوس الجبال. تتمايل مثل لبنان ثمرتها ويزهرون من المدينة مثل عشب الأرض.","72:17":"يكون اسمه إلى الدهر. قدام الشمس يمتد اسمه. ويتباركون به. كل أمم الأرض يطوبونه.","72:18":"مبارك الرب الله إله إسرائيل الصانع العجائب وحده.","72:19":"ومبارك اسم مجده إلى الدهر ولتمتلئ الأرض كلها من مجده. آمين ثم آمين.","72:20":"تمت صلوات داود بن يسى","73:1":"مزمور. لآساف إنما صالح الله لإسرائيل لأنقياء القلب.","73:2":"أما أنا فكادت تزل قدماي. لولا قليل لزلقت خطواتي","73:3":"لأني غرت من المتكبرين إذ رأيت سلامة الأشرار.","73:4":"لأنه ليست في موتهم شدائد وجسمهم سمين.","73:5":"ليسوا في تعب الناس ومع البشر لا يصابون.","73:6":"لذلك تقلدوا الكبرياء. لبسوا كثوب ظلمهم.","73:7":"جحظت عيونهم من الشحم. جاوزوا تصورات القلب.","73:8":"يستهزئون ويتكلمون بالشر ظلما. من العلاء يتكلمون.","73:9":"جعلوا أفواههم في السماء وألسنتهم تتمشى في الأرض.","73:10":"لذلك يرجع شعبه إلى هنا وكمياه مروية يمتصون منهم.","73:11":"وقالوا: [كيف يعلم الله وهل عند العلي معرفة؟]","73:12":"هوذا هؤلاء هم الأشرار ومستريحين إلى الدهر يكثرون ثروة.","73:13":"حقا قد زكيت قلبي باطلا وغسلت بالنقاوة يدي.","73:14":"وكنت مصابا اليوم كله وتأدبت كل صباح.","73:15":"لو قلت أحدث هكذا لغدرت بجيل بنيك.","73:16":"فلما قصدت معرفة هذا إذا هو تعب في عيني.","73:17":"حتى دخلت مقادس الله وانتبهت إلى آخرتهم.","73:18":"حقا في مزالق جعلتهم. أسقطتهم إلى البوار.","73:19":"كيف صاروا للخراب بغتة! اضمحلوا فنوا من الدواهي.","73:20":"كحلم عند التيقظ يا رب عند التيقظ تحتقر خيالهم.","73:21":"لأنه تمرمر قلبي وانتخست في كليتي.","73:22":"وأنا بليد ولا أعرف. صرت كبهيم عندك.","73:23":"ولكني دائما معك. أمسكت بيدي اليمنى.","73:24":"برأيك تهديني وبعد إلى مجد تأخذني.","73:25":"من لي في السماء؟ ومعك لا أريد شيئا في الأرض.","73:26":"قد فني لحمي وقلبي. صخرة قلبي ونصيبي الله إلى الدهر.","73:27":"لأنه هوذا البعداء عنك يبيدون. تهلك كل من يزني عنك.","73:28":"أما أنا فالاقتراب إلى الله حسن لي. جعلت بالسيد الرب ملجإي لأخبر بكل صنائعك.","74:1":"قصيدة لآساف لماذا رفضتنا يا الله إلى الأبد؟ لماذا يدخن غضبك على غنم مرعاك؟","74:2":"اذكر جماعتك التي اقتنيتها منذ القدم وفديتها سبط ميراثك جبل صهيون هذا الذي سكنت فيه.","74:3":"ارفع خطواتك إلى الخرب الأبدية. الكل قد حطم العدو في المقدس.","74:4":"قد زمجر مقاوموك في وسط معهدك جعلوا آياتهم آيات.","74:5":"يبان كأنه رافع فؤوس على الأشجار المشتبكة.","74:6":"والآن منقوشاته معا بالفؤوس والمعاول يكسرون.","74:7":"أطلقوا النار في مقدسك. دنسوا للأرض مسكن اسمك.","74:8":"قالوا في قلوبهم: [لنفنينهم معا]. أحرقوا كل معاهد الله في الأرض.","74:9":"آياتنا لا نرى. لا نبي بعد. ولا بيننا من يعرف حتى متى.","74:10":"حتى متى يا الله يعير المقاوم ويهين العدو اسمك إلى الغاية؟","74:11":"لماذا ترد يدك ويمينك؟ أخرجها من وسط حضنك. أفن.","74:12":"والله ملكي منذ القدم فاعل الخلاص في وسط الأرض.","74:13":"أنت شققت البحر بقوتك. كسرت رؤوس التنانين على المياه.","74:14":"أنت رضضت رؤوس لوياثان. جعلته طعاما للشعب لأهل البرية.","74:15":"أنت فجرت عينا وسيلا. أنت يبست أنهارا دائمة الجريان.","74:16":"لك النهار ولك أيضا الليل. أنت هيأت النور والشمس.","74:17":"أنت نصبت كل تخوم الأرض. الصيف والشتاء أنت خلقتهما.","74:18":"اذكر هذا: أن العدو قد عير الرب وشعبا جاهلا قد أهان اسمك.","74:19":"لا تسلم للوحش نفس يمامتك. قطيع بائسيك لا تنس إلى الأبد.","74:20":"انظر إلى العهد. لأن مظلمات الأرض امتلأت من مساكن الظلم.","74:21":"لا يرجعن المنسحق خازيا. الفقير والبائس ليسبحا اسمك.","74:22":"قم يا الله. أقم دعواك. اذكر تعيير الجاهل إياك اليوم كله.","74:23":"لا تنس صوت أضدادك ضجيج مقاوميك الصاعد دائما.","75:1":"لإمام المغنين. على [لا تهلك]. مزمور لآساف. تسبيحة نحمدك يا الله. نحمدك واسمك قريب. يحدثون بعجائبك.","75:2":"[لأني أعين ميعادا. أنا بالمستقيمات أقضي.","75:3":"ذابت الأرض وكل سكانها. أنا وزنت أعمدتها]. سلاه.","75:4":"قلت للمفتخرين: [لا تفتخروا] وللأشرار: [لا ترفعوا قرنا.","75:5":"لا ترفعوا إلى العلى قرنكم. لا تتكلموا بعنق متصلب].","75:6":"لأنه لا من المشرق ولا من المغرب ولا من برية الجبال.","75:7":"ولكن الله هو القاضي. هذا يضعه وهذا يرفعه.","75:8":"لأن في يد الرب كأسا وخمرها مختمرة. ملآنة شرابا ممزوجا. وهو يسكب منها. لكن عكرها يمصه يشربه كل أشرار الأرض.","75:9":"أما أنا فأخبر إلى الدهر. أرنم لإله يعقوب.","75:10":"وكل قرون الأشرار أعضب. قرون الصديق تنتصب.","76:1":"لإمام المغنين على ذوات الأوتار. مزمور لآساف. تسبيحة الله معروف في يهوذا. اسمه عظيم في إسرائيل.","76:2":"كانت في ساليم مظلته ومسكنه في صهيون.","76:3":"هناك سحق القسي البارقة. المجن والسيف والقتال. سلاه.","76:4":"أبهى أنت أمجد من جبال السلب.","76:5":"سلب أشداء القلب. ناموا سنتهم. كل رجال البأس لم يجدوا أيديهم.","76:6":"من انتهارك يا إله يعقوب يسبخ فارس وخيل.","76:7":"أنت مهوب أنت. فمن يقف قدامك حال غضبك؟","76:8":"من السماء أسمعت حكما. الأرض فزعت وسكتت","76:9":"عند قيام الله للقضاء لتخليص كل ودعاء الأرض. سلاه.","76:10":"لأن غضب الإنسان يحمدك. بقية الغضب تتمنطق بها.","76:11":"انذروا وأوفوا للرب إلهكم يا جميع الذين حوله. ليقدموا هدية للمهوب.","76:12":"يقطف روح الرؤساء. هو مهوب لملوك الأرض.","77:1":"لإمام المغنين على [يدوثون]. لآساف. مزمور صوتي إلى الله فأصرخ. صوتي إلى الله فأصغى إلي.","77:2":"في يوم ضيقي التمست الرب. يدي في الليل انبسطت ولم تخدر. أبت نفسي التعزية.","77:3":"أذكر الله فأئن. أناجي نفسي فيغشى على روحي. سلاه.","77:4":"أمسكت أجفان عيني. انزعجت فلم أتكلم.","77:5":"تفكرت في أيام القدم السنين الدهرية.","77:6":"أذكر ترنمي في الليل. مع قلبي أناجي وروحي تبحث.","77:7":"هل إلى الدهور يرفض الرب ولا يعود للرضا بعد؟","77:8":"هل انتهت إلى الأبد رحمته؟ هل انقطعت كلمته إلى دور فدور؟","77:9":"هل نسي الله رأفة أو قفص برجزه مراحمه؟ سلاه.","77:10":"فقلت: [هذا ما يعلني: تغير يمين العلي].","77:11":"أذكر أعمال الرب إذ أتذكر عجائبك منذ القدم","77:12":"وألهج بجميع أفعالك وبصنائعك أناجي.","77:13":"اللهم في القدس طريقك. أي إله عظيم مثل الله!","77:14":"أنت الإله الصانع العجائب. عرفت بين الشعوب قوتك.","77:15":"فككت بذراعك شعبك بني يعقوب ويوسف. سلاه.","77:16":"أبصرتك المياه يا الله أبصرتك المياه ففزعت. ارتعدت أيضا اللجج.","77:17":"سكبت الغيوم مياها. أعطت السحب صوتا. أيضا سهامك طارت.","77:18":"صوت رعدك في الزوبعة. البروق أضاءت المسكونة. ارتعدت ورجفت الأرض.","77:19":"في البحر طريقك وسبلك في المياه الكثيرة وآثارك لم تعرف.","77:20":"هديت شعبك كالغنم بيد موسى وهارون.","78:1":"قصيدة لآساف اصغ يا شعبي إلى شريعتي. أميلوا آذانكم إلى كلام فمي.","78:2":"أفتح بمثل فمي. أذيع ألغازا منذ القدم.","78:3":"التي سمعناها وعرفناها وآباؤنا أخبرونا.","78:4":"لا نخفي عن بنيهم إلى الجيل الآخر مخبرين بتسابيح الرب وقوته وعجائبه التي صنع.","78:5":"أقام شهادة في يعقوب ووضع شريعة في إسرائيل التي أوصى آباءنا أن يعرفوا بها أبناءهم","78:6":"لكي يعلم الجيل الآخر. بنون يولدون فيقومون ويخبرون أبناءهم","78:7":"فيجعلون على الله اعتمادهم ولا ينسون أعمال الله بل يحفظون وصاياه","78:8":"ولا يكونون مثل آبائهم جيلا زائغا وماردا جيلا لم يثبت قلبه ولم تكن روحه أمينة لله.","78:9":"بنو أفرايم النازعون في القوس الرامون انقلبوا في يوم الحرب.","78:10":"لم يحفظوا عهد الله وأبوا السلوك في شريعته","78:11":"ونسوا أفعاله وعجائبه التي أراهم.","78:12":"قدام آبائهم صنع أعجوبة في أرض مصر بلاد صوعن.","78:13":"شق البحر فعبرهم ونصب المياه كند.","78:14":"وهداهم بالسحاب نهارا والليل كله بنور نار.","78:15":"شق صخورا في البرية وسقاهم كأنه من لجج عظيمة.","78:16":"أخرج مجاري من صخرة وأجرى مياها كالأنهار.","78:17":"ثم عادوا أيضا ليخطئوا إليه لعصيان العلي في الأرض الناشفة.","78:18":"وجربوا الله في قلوبهم بسؤالهم طعاما لشهوتهم.","78:19":"فوقعوا في الله. قالوا: [هل يقدر الله أن يرتب مائدة في البرية؟","78:20":"هوذا ضرب الصخرة فجرت المياه وفاضت الأودية. هل يقدر أيضا أن يعطي خبزا أو يهيئ لحما لشعبه؟]","78:21":"لذلك سمع الرب فغضب واشتعلت نار في يعقوب وسخط أيضا صعد على إسرائيل","78:22":"لأنهم لم يؤمنوا بالله ولم يتكلوا على خلاصه.","78:23":"فأمر السحاب من فوق وفتح مصاريع السماوات","78:24":"وأمطر عليهم منا للأكل وبر السماء أعطاهم.","78:25":"أكل الإنسان خبز الملائكة. أرسل عليهم زادا للشبع.","78:26":"أهاج ريحا شرقية في السماء وساق بقوته جنوبية","78:27":"وأمطر عليهم لحما مثل التراب وكرمل البحر طيورا ذوات أجنحة.","78:28":"وأسقطها في وسط محلتهم حوالي مساكنهم.","78:29":"فأكلوا وشبعوا جدا وأتاهم بشهوتهم.","78:30":"لم يزوغوا عن شهوتهم. طعامهم بعد في أفواههم","78:31":"فصعد عليهم غضب الله وقتل من أسمنهم. وصرع مختاري إسرائيل.","78:32":"في هذا كله أخطأوا بعد ولم يؤمنوا بعجائبه.","78:33":"فأفنى أيامهم بالباطل وسنيهم بالرعب.","78:34":"إذ قتلهم طلبوه ورجعوا وبكروا إلى الله","78:35":"وذكروا أن الله صخرتهم والله العلي وليهم.","78:36":"فخادعوه بأفواههم وكذبوا عليه بألسنتهم.","78:37":"أما قلوبهم فلم تثبت معه ولم يكونوا أمناء في عهده.","78:38":"أما هو فرأوف يغفر الإثم ولا يهلك وكثيرا ما رد غضبه ولم يشعل كل سخطه.","78:39":"ذكر أنهم بشر. ريح تذهب ولا تعود.","78:40":"كم عصوه في البرية وأحزنوه في القفر!","78:41":"رجعوا وجربوا الله وعنوا قدوس إسرائيل.","78:42":"لم يذكروا يده يوم فداهم من العدو","78:43":"حيث جعل في مصر آياته وعجائبه في بلاد صوعن","78:44":"إذ حول خلجانهم إلى دم ومجاريهم لكي لا يشربوا.","78:45":"أرسل عليهم بعوضا فأكلهم وضفادع فأفسدتهم.","78:46":"أسلم للجردم غلتهم وتعبهم للجراد.","78:47":"أهلك بالبرد كرومهم وجميزهم بالصقيع.","78:48":"ودفع إلى البرد بهائمهم ومواشيهم للبروق.","78:49":"أرسل عليهم حمو غضبه سخطا ورجزا وضيقا جيش ملائكة أشرار.","78:50":"مهد سبيلا لغضبه. لم يمنع من الموت أنفسهم بل دفع حياتهم للوبإ.","78:51":"وضرب كل بكر في مصر. أوائل القدرة في خيام حام.","78:52":"وساق مثل الغنم شعبه وقادهم مثل قطيع في البرية.","78:53":"وهداهم آمنين فلم يجزعوا. أما أعداؤهم فغمرهم البحر.","78:54":"وأدخلهم في تخوم قدسه هذا الجبل الذي اقتنته يمينه.","78:55":"وطرد الأمم من قدامهم وقسمهم بالحبل ميراثا وأسكن في خيامهم أسباط إسرائيل.","78:56":"فجربوا وعصوا الله العلي وشهاداته لم يحفظوا","78:57":"بل ارتدوا وغدروا مثل آبائهم. انحرفوا كقوس مخطئة.","78:58":"أغاظوه بمرتفعاتهم وأغاروه بتماثيلهم.","78:59":"سمع الله فغضب ورذل إسرائيل جدا","78:60":"ورفض مسكن شيلوه الخيمة التي نصبها بين الناس.","78:61":"وسلم للسبي عزه وجلاله ليد العدو.","78:62":"ودفع إلى السيف شعبه وغضب على ميراثه.","78:63":"مختاروه أكلتهم النار وعذاراه لم يحمدن.","78:64":"كهنته سقطوا بالسيف وأرامله لم يبكين.","78:65":"فاستيقظ الرب كنائم كجبار معيط من الخمر.","78:66":"فضرب أعداءه إلى الوراء. جعلهم عارا أبديا.","78:67":"ورفض خيمة يوسف ولم يختر سبط أفرايم.","78:68":"بل اختار سبط يهوذا جبل صهيون الذي أحبه.","78:69":"وبنى مثل مرتفعات مقدسه كالأرض التي أسسها إلى الأبد.","78:70":"واختار داود عبده وأخذه من حظائر الغنم.","78:71":"من خلف المرضعات أتى به ليرعى يعقوب شعبه وإسرائيل ميراثه.","78:72":"فرعاهم حسب كمال قلبه وبمهارة يديه هداهم.","79:1":"مزمور. لآساف اللهم إن الأمم قد دخلوا ميراثك. نجسوا هيكل قدسك. جعلوا أورشليم أكواما.","79:2":"دفعوا جثث عبيدك طعاما لطيور السماء لحم أتقيائك لوحوش الأرض.","79:3":"سفكوا دمهم كالماء حول أورشليم وليس من يدفن.","79:4":"صرنا عارا عند جيراننا هزءا وسخرة للذين حولنا.","79:5":"إلى متى يا رب تغضب كل الغضب وتتقد كالنار غيرتك؟","79:6":"أفض رجزك على الأمم الذين لا يعرفونك وعلى الممالك التي لم تدع باسمك.","79:7":"لأنهم قد أكلوا يعقوب وأخربوا مسكنه.","79:8":"لا تذكر علينا ذنوب الأولين. لتتقدمنا مراحمك سريعا لأننا قد تذللنا جدا.","79:9":"أعنا يا إله خلاصنا من أجل مجد اسمك ونجنا واغفر خطايانا من أجل اسمك.","79:10":"لماذا يقول الأمم: [أين هو إلههم؟] لتعرف عند الأمم قدام أعيننا نقمة دم عبيدك المهراق.","79:11":"ليدخل قدامك أنين الأسير. كعظمة ذراعك استبق بني الموت.","79:12":"ورد على جيراننا سبعة أضعاف في أحضانهم العار الذي عيروك به يا رب.","79:13":"أما نحن شعبك وغنم رعايتك نحمدك إلى الدهر. إلى دور فدور نحدث بتسبيحك.","80:1":"لإمام المغنين على السوسن. شهادة. لآساف. مزمور يا راعي إسرائيل اصغ يا قائد يوسف كالضأن يا جالسا على الكروبيم أشرق.","80:2":"قدام أفرايم وبنيامين ومنسى أيقظ جبروتك وهلم لخلاصنا.","80:3":"يا الله أرجعنا وأنر بوجهك فنخلص.","80:4":"يا رب إله الجنود إلى متى تدخن على صلاة شعبك؟","80:5":"قد أطعمتهم خبز الدموع وسقيتهم الدموع بالكيل.","80:6":"جعلتنا نزاعا عند جيراننا وأعداؤنا يستهزئون بين أنفسهم.","80:7":"يا إله الجنود أرجعنا وأنر بوجهك فنخلص.","80:8":"كرمة من مصر نقلت. طردت أمما وغرستها.","80:9":"هيأت قدامها فأصلت أصولها فملأت الأرض.","80:10":"غطى الجبال ظلها وأغصانها أرز الله.","80:11":"مدت قضبانها إلى البحر وإلى النهر فروعها.","80:12":"فلماذا هدمت جدرانها فيقطفها كل عابري الطريق؟","80:13":"يفسدها الخنزير من الوعر ويرعاها وحش البرية!","80:14":"يا إله الجنود ارجعن. اطلع من السماء وانظر وتعهد هذه الكرمة","80:15":"والغرس الذي غرسته يمينك والابن الذي اخترته لنفسك.","80:16":"هي محروقة بنار مقطوعة. من انتهار وجهك يبيدون.","80:17":"لتكن يدك على رجل يمينك وعلى ابن آدم الذي اخترته لنفسك","80:18":"فلا نرتد عنك. أحينا فندعو باسمك.","80:19":"يا رب إله الجنود أرجعنا. أنر بوجهك فنخلص.","81:1":"لإمام المغنين على الجتية. لآساف رنموا لله قوتنا. اهتفوا لإله يعقوب.","81:2":"ارفعوا نغمة وهاتوا دفا عودا حلوا مع رباب.","81:3":"انفخوا في رأس الشهر بالبوق عند الهلال ليوم عيدنا.","81:4":"لأن هذا فريضة لإسرائيل حكم لإله يعقوب.","81:5":"جعله شهادة في يوسف عند خروجه على أرض مصر. سمعت لسانا لم أعرفه.","81:6":"[أبعدت من الحمل كتفه. يداه تحولتا عن السل.","81:7":"في الضيق دعوت فنجيتك. استجبتك في ستر الرعد. جربتك على ماء مريبة]. سلاه.","81:8":"[اسمع يا شعبي فأحذرك. يا إسرائيل إن سمعت لي.","81:9":"لا يكن فيك إله غريب ولا تسجد لإله أجنبي.","81:10":"أنا الرب إلهك الذي أصعدك من أرض مصر. أفغر فاك فأملأه.","81:11":"فلم يسمع شعبي لصوتي وإسرائيل لم يرض بي.","81:12":"فسلمتهم إلى قساوة قلوبهم ليسلكوا في مؤامرات أنفسهم.","81:13":"لو سمع لي شعبي وسلك إسرائيل في طرقي","81:14":"سريعا كنت أخضع أعداءهم وعلى مضايقيهم كنت أرد يدي.","81:15":"مبغضو الرب يتذللون له ويكون وقتهم إلى الدهر.","81:16":"وكان أطعمه من شحم الحنطة ومن الصخرة كنت أشبعك عسلا].","82:1":"مزمور لآساف الله قائم في مجمع الله. في وسط الآلهة يقضي.","82:2":"حتى متى تقضون جورا وترفعون وجوه الأشرار؟ سلاه.","82:3":"اقضوا للذليل ولليتيم. أنصفوا المسكين والبائس.","82:4":"نجوا المسكين والفقير. من يد الأشرار أنقذوا.","82:5":"لا يعلمون ولا يفهمون. في الظلمة يتمشون. تتزعزع كل أسس الأرض.","82:6":"أنا قلت إنكم آلهة وبنو العلي كلكم.","82:7":"لكن مثل الناس تموتون وكأحد الرؤساء تسقطون.","82:8":"قم يا الله. دن الأرض لأنك أنت تمتلك كل الأمم.","83:1":"تسبيحة. مزمور لآساف اللهم لا تصمت لا تسكت ولا تهدأ يا الله","83:2":"فهوذا أعداؤك يعجون ومبغضوك قد رفعوا الرأس.","83:3":"على شعبك مكروا مؤامرة وتشاوروا على أحميائك.","83:4":"قالوا: [هلم نبدهم من بين الشعوب ولا يذكر اسم إسرائيل بعد].","83:5":"لأنهم تآمروا بالقلب معا. عليك تعاهدوا عهدا.","83:6":"خيام أدوم والإسماعيليين. موآب والهاجريون.","83:7":"جبال وعمون وعماليق. فلسطين مع سكان صور.","83:8":"أشور أيضا اتفق معهم. صاروا ذراعا لبني لوط. سلاه","83:9":"افعل بهم كما بمديان كما بسيسرا كما بيابين في وادي قيشون.","83:10":"بادوا في عين دور. صاروا دمنا للأرض.","83:11":"اجعل شرفاءهم مثل غراب ومثل ذئب. ومثل زبح ومثل صلمناع كل أمرائهم.","83:12":"الذين قالوا: [لنمتلك لأنفسنا مساكن الله].","83:13":"يا إلهي اجعلهم مثل الجل مثل القش أمام الريح.","83:14":"كنار تحرق الوعر كلهيب يشعل الجبال.","83:15":"هكذا اطردهم بعاصفتك وبزوبعتك روعهم.","83:16":"املأ وجوههم خزيا فيطلبوا اسمك يا رب.","83:17":"ليخزوا ويرتاعوا إلى الأبد وليخجلوا ويبيدوا","83:18":"ويعلموا أنك اسمك يهوه وحدك العلي على كل الأرض.","84:1":"لإمام المغنين على الجتية. لبني قورح. مزمور ما أحلى مساكنك يا رب الجنود.","84:2":"تشتاق بل تتوق نفسي إلى ديار الرب. قلبي ولحمي يهتفان بالإله الحي.","84:3":"العصفور أيضا وجد بيتا والسنونة عشا لنفسها حيث تضع أفراخها مذابحك يا رب الجنود ملكي وإلهي.","84:4":"طوبى للساكنين في بيتك أبدا يسبحونك. سلاه.","84:5":"طوبى لأناس عزهم بك. طرق بيتك في قلوبهم.","84:6":"عابرين في وادي البكاء يصيرونه ينبوعا. أيضا ببركات يغطون مورة.","84:7":"يذهبون من قوة إلى قوة. يرون قدام الله في صهيون.","84:8":"يا رب إله الجنود اسمع صلاتي واصغ يا إله يعقوب. سلاه.","84:9":"يا مجننا انظر يا الله والتفت إلى وجه مسيحك.","84:10":"لأن يوما واحدا في ديارك خير من ألف. اخترت الوقوف على العتبة في بيت إلهي على السكن في خيام الأشرار.","84:11":"لأن الرب الله شمس ومجن. الرب يعطي رحمة ومجدا. لا يمنع خيرا عن السالكين بالكمال.","84:12":"يا رب الجنود طوبى للإنسان المتكل عليك!","85:1":"لإمام المغنين. لبني قورح. مزمور رضيت يا رب على أرضك. أرجعت سبي يعقوب.","85:2":"غفرت إثم شعبك. سترت كل خطيتهم. سلاه.","85:3":"حجزت كل رجزك. رجعت عن حمو غضبك.","85:4":"أرجعنا يا إله خلاصنا وانف غضبك عنا.","85:5":"هل إلى الدهر تسخط علينا؟ هل تطيل غضبك إلى دور فدور؟","85:6":"ألا تعود أنت فتحيينا فيفرح بك شعبك؟","85:7":"أرنا يا رب رحمتك وأعطنا خلاصك.","85:8":"إني أسمع ما يتكلم به الله الرب. لأنه يتكلم بالسلام لشعبه ولأتقيائه فلا يرجعن إلى الحماقة.","85:9":"لأن خلاصه قريب من خائفيه ليسكن المجد في أرضنا.","85:10":"الرحمة والحق التقيا. البر والسلام تلاثما.","85:11":"الحق من الأرض ينبت والبر من السماء يطلع.","85:12":"أيضا الرب يعطي الخير وأرضنا تعطي غلتها.","85:13":"البر قدامه يسلك ويطأ في طريق خطواته.","86:1":"صلاة لداود أمل يا رب أذنك. استجب لي لأني مسكين وبائس أنا.","86:2":"احفظ نفسي لأني تقي. يا إلهي خلص أنت عبدك المتكل عليك.","86:3":"ارحمني يا رب لأني إليك أصرخ اليوم كله.","86:4":"فرح نفس عبدك لأنني إليك يا رب أرفع نفسي.","86:5":"لأنك أنت يا رب صالح وغفور وكثير الرحمة لكل الداعين إليك.","86:6":"اصغ يا رب إلى صلاتي وأنصت إلى صوت تضرعاتي.","86:7":"في يوم ضيقي أدعوك لأنك تستجيب لي.","86:8":"لا مثل لك بين الآلهة يا رب ولا مثل أعمالك.","86:9":"كل الأمم الذين صنعتهم يأتون ويسجدون أمامك يا رب ويمجدون اسمك.","86:10":"لأنك عظيم أنت وصانع عجائب. أنت الله وحدك.","86:11":"علمني يا رب طريقك أسلك في حقك. وحد قلبي لخوف اسمك.","86:12":"أحمدك يا رب إلهي من كل قلبي وأمجد اسمك إلى الدهر.","86:13":"لأن رحمتك عظيمة نحوي وقد نجيت نفسي من الهاوية السفلى.","86:14":"اللهم المتكبرون قد قاموا علي وجماعة العتاة طلبوا نفسي ولم يجعلوك أمامهم.","86:15":"أما أنت يا رب فإله رحيم ورأوف طويل الروح وكثير الرحمة والحق.","86:16":"التفت إلي وارحمني. أعط عبدك قوتك وخلص ابن أمتك.","86:17":"اصنع معي آية للخير فيرى ذلك مبغضي فيخزوا لأنك أنت يا رب أعنتني وعزيتني.","87:1":"لبني قورح. مزمور تسبيحة أساسه في الجبال المقدسة.","87:2":"الرب أحب أبواب صهيون أكثر من جميع مساكن يعقوب.","87:3":"قد قيل بك أمجاد يا مدينة الله. سلاه","87:4":"أذكر رهب وبابل عارفتي. هوذا فلسطين وصور مع كوش. هذا ولد هناك.","87:5":"ولصهيون يقال: [هذا الإنسان وهذا الإنسان ولد فيها وهي العلي يثبتها].","87:6":"الرب يعد في كتابة الشعوب أن هذا ولد هناك. سلاه.","87:7":"ومغنون كعازفين كل السكان فيك.","88:1":"تسبيحة. مزمور لبني قورح. لإمام المغنين على العود للغناء. قصيدة لهيمان الأزراحي يا رب إله خلاصي بالنهار والليل صرخت أمامك","88:2":"فلتأت قدامك صلاتي. أمل أذنك إلى صراخي","88:3":"لأنه قد شبعت من المصائب نفسي وحياتي إلى الهاوية دنت.","88:4":"حسبت مثل المنحدرين إلى الجب. صرت كرجل لا قوة له.","88:5":"بين الأموات فراشي مثل القتلى المضطجعين في القبر الذين لا تذكرهم بعد وهم من يدك انقطعوا.","88:6":"وضعتني في الجب الأسفل في ظلمات في أعماق.","88:7":"علي استقر غضبك وبكل تياراتك ذللتني. سلاه.","88:8":"أبعدت عني معارفي. جعلتني رجسا لهم. أغلق علي فما أخرج.","88:9":"عيني ذابت من الذل. دعوتك يا رب كل يوم. بسطت إليك يدي.","88:10":"أفلعلك للأموات تصنع عجائب أم الأخيلة تقوم تمجدك؟ سلاه.","88:11":"هل يحدث في القبر برحمتك أو بحقك في الهلاك؟","88:12":"هل تعرف في الظلمة عجائبك وبرك في أرض النسيان؟","88:13":"أما أنا فإليك يا رب صرخت وفي الغداة صلاتي تتقدمك.","88:14":"لماذا يا رب ترفض نفسي؟ لماذا تحجب وجهك عني؟","88:15":"أنا مسكين ومسلم الروح منذ صباي. احتملت أهوالك. تحيرت.","88:16":"علي عبر سخطك. أهوالك أهلكتني.","88:17":"أحاطت بي كالمياه اليوم كله. اكتنفتني معا.","88:18":"أبعدت عني محبا وصاحبا. معارفي في الظلمة.","89:1":"قصيدة لأيثان الأزراحي بمراحم الرب أغني إلى الدهر. لدور فدور أخبر عن حقك بفمي.","89:2":"لأني قلت: [إن الرحمة إلى الدهر تبنى. السماوات تثبت فيها حقك].","89:3":"[قطعت عهدا مع مختاري. حلفت لداود عبدي.","89:4":"إلى الدهر أثبت نسلك وأبني إلى دور فدور كرسيك]. سلاه.","89:5":"والسماوات تحمد عجائبك يا رب وحقك أيضا في جماعة القديسين.","89:6":"لأنه من في السماء يعادل الرب. من يشبه الرب بين أبناء الله؟","89:7":"إله مهوب جدا في مؤامرة القديسين ومخوف عند جميع الذين حوله.","89:8":"يا رب إله الجنود من مثلك قوي رب وحقك من حولك؟","89:9":"أنت متسلط على كبرياء البحر. عند ارتفاع لججه أنت تسكنها.","89:10":"أنت سحقت رهب مثل القتيل. بذراع قوتك بددت أعداءك.","89:11":"لك السماوات. لك أيضا الأرض. المسكونة وملؤها أنت أسستهما.","89:12":"الشمال والجنوب أنت خلقتهما. تابور وحرمون باسمك يهتفان.","89:13":"لك ذراع القدرة. قوية يدك. مرتفعة يمينك.","89:14":"العدل والحق قاعدة كرسيك. الرحمة والأمانة تتقدمان أمام وجهك.","89:15":"طوبى للشعب العارفين الهتاف. يا رب بنور وجهك يسلكون.","89:16":"باسمك يبتهجون اليوم كله وبعدلك يرتفعون.","89:17":"لأنك أنت فخر قوتهم وبرضاك ينتصب قرننا.","89:18":"لأن الرب مجننا وقدوس إسرائيل ملكنا.","89:19":"حينئذ كلمت برؤيا تقيك وقلت جعلت: [عونا على قوي. رفعت مختارا من بين الشعب.","89:20":"وجدت داود عبدي. بدهن قدسي مسحته.","89:21":"الذي تثبت يدي معه. أيضا ذراعي تشدده.","89:22":"لا يرغمه عدو وابن الإثم لا يذلله.","89:23":"وأسحق أعداءه أمام وجهه وأضرب مبغضيه.","89:24":"أما أمانتي ورحمتي فمعه وباسمي ينتصب قرنه.","89:25":"وأجعل على البحر يده وعلى الأنهار يمينه.","89:26":"هو يدعوني: أبي أنت. إلهي وصخرة خلاصي.","89:27":"أنا أيضا أجعله بكرا أعلى من ملوك الأرض.","89:28":"إلى الدهر أحفظ له رحمتي. وعهدي يثبت له.","89:29":"وأجعل إلى الأبد نسله وكرسيه مثل أيام السماوات.","89:30":"إن ترك بنوه شريعتي ولم يسلكوا بأحكامي","89:31":"إن نقضوا فرائضي ولم يحفظوا وصاياي","89:32":"أفتقد بعصا معصيتهم وبضربات إثمهم.","89:33":"أما رحمتي فلا أنزعها عنه ولا أكذب من جهة أمانتي.","89:34":"لا أنقض عهدي ولا أغير ما خرج من شفتي.","89:35":"مرة حلفت بقدسي أني لا أكذب لداود.","89:36":"نسله إلى الدهر يكون وكرسيه كالشمس أمامي.","89:37":"مثل القمر يثبت إلى الدهر. والشاهد في السماء أمين]. سلاه","89:38":"لكنك رفضت ورذلت. غضبت على مسيحك.","89:39":"نقضت عهد عبدك. نجست تاجه في التراب.","89:40":"هدمت كل جدرانه. جعلت حصونه خرابا.","89:41":"أفسده كل عابري الطريق. صار عارا عند جيرانه.","89:42":"رفعت يمين مضايقيه. فرحت جميع أعدائه.","89:43":"أيضا رددت حد سيفه ولم تنصره في القتال.","89:44":"أبطلت بهاءه وألقيت كرسيه إلى الأرض.","89:45":"قصرت أيام شبابه. غطيته بالخزي. سلاه.","89:46":"حتى متى يا رب تختبئ كل الاختباء؟ حتى متى يتقد كالنار غضبك؟","89:47":"اذكر كيف أنا زائل. إلى أي باطل خلقت جميع بني آدم؟","89:48":"أي إنسان يحيا ولا يرى الموت؟ أي ينجي نفسه من يد الهاوية؟ سلاه.","89:49":"أين مراحمك الأول يا رب التي حلفت بها لداود بأمانتك؟","89:50":"اذكر يا رب عار عبيدك الذي أحتمله في حضني من كثرة الأمم كلها","89:51":"الذي به عير أعداؤك يا رب الذين عيروا آثار مسيحك.","89:52":"مبارك الرب إلى الدهر. آمين فآمين.","90:1":"صلاة لموسى رجل الله يا رب ملجأ كنت لنا في دور فدور.","90:2":"من قبل أن تولد الجبال أو أبدأت الأرض والمسكونة منذ الأزل إلى الأبد أنت الله.","90:3":"ترجع الإنسان إلى الغبار وتقول: [ارجعوا يا بني آدم].","90:4":"لأن ألف سنة في عينيك مثل يوم أمس بعد ما عبر وكهزيع من الليل.","90:5":"جرفتهم. كسنة يكونون. بالغداة كعشب يزول.","90:6":"بالغداة يزهر فيزول. عند المساء يجز فييبس.","90:7":"لأننا قد فنينا بسخطك وبغضبك ارتعبنا.","90:8":"قد جعلت آثامنا أمامك خفياتنا في ضوء وجهك.","90:9":"لأن كل أيامنا قد انقضت برجزك. أفنينا سنينا كقصة.","90:10":"أيام سنينا هي سبعون سنة وإن كانت مع القوة فثمانون سنة وأفخرها تعب وبلية لأنها تقرض سريعا فنطير.","90:11":"من يعرف قوة غضبك وكخوفك سخطك.","90:12":"إحصاء أيامنا هكذا علمنا فنؤتى قلب حكمة.","90:13":"ارجع يا رب. حتى متى؟ وترأف على عبيدك.","90:14":"أشبعنا بالغداة من رحمتك فنبتهج ونفرح كل أيامنا.","90:15":"فرحنا كالأيام التي فيها أذللتنا كالسنين التي رأينا فيها شرا.","90:16":"ليظهر فعلك لعبيدك وجلالك لبنيهم.","90:17":"ولتكن نعمة الرب إلهنا علينا وعمل أيدينا ثبت علينا وعمل أيدينا ثبته.","91:1":"الساكن في ستر العلي في ظل القدير يبيت.","91:2":"أقول للرب: [ملجإي وحصني. إلهي فأتكل عليه].","91:3":"لأنه ينجيك من فخ الصياد ومن الوبإ الخطر.","91:4":"بخوافيه يظللك وتحت أجنحته تحتمي. ترس ومجن حقه.","91:5":"لا تخشى من خوف الليل ولا من سهم يطير في النهار","91:6":"ولا من وبأ يسلك في الدجى ولا من هلاك يفسد في الظهيرة.","91:7":"يسقط عن جانبك ألف وربوات عن يمينك. إليك لا يقرب.","91:8":"إنما بعينيك تنظر وترى مجازاة الأشرار.","91:9":"لأنك قلت: [أنت يا رب ملجإي]. جعلت العلي مسكنك","91:10":"لا يلاقيك شر ولا تدنو ضربة من خيمتك.","91:11":"لأنه يوصي ملائكته بك لكي يحفظوك في كل طرقك.","91:12":"على الأيدي يحملونك لئلا تصدم بحجر رجلك.","91:13":"على الأسد والصل تطأ. الشبل والثعبان تدوس.","91:14":"لأنه تعلق بي أنجيه. أرفعه لأنه عرف اسمي.","91:15":"يدعوني فأستجيب له. معه أنا في الضيق. أنقذه وأمجده.","91:16":"من طول الأيام أشبعه وأريه خلاصي.","92:1":"مزمور تسبيحة. ليوم السبت حسن هو الحمد للرب والترنم لاسمك أيها العلي.","92:2":"أن يخبر برحمتك في الغداة وأمانتك كل ليلة","92:3":"على ذات عشرة أوتار وعلى الرباب على عزف العود.","92:4":"لأنك فرحتني يا رب بصنائعك. بأعمال يديك أبتهج.","92:5":"ما أعظم أعمالك يا رب وأعمق جدا أفكارك.","92:6":"الرجل البليد لا يعرف والجاهل لا يفهم هذا.","92:7":"إذا زها الأشرار كالعشب وأزهر كل فاعلي الإثم فلكي يبادوا إلى الدهر.","92:8":"أما أنت يا رب فمتعال إلى الأبد.","92:9":"لأنه هوذا أعداؤك يا رب لأنه هوذا أعداؤك يبيدون. يتبدد كل فاعلي الإثم.","92:10":"وتنصب مثل البقر الوحشي قرني. تدهنت بزيت طري.","92:11":"وتبصر عيني بمراقبي وبالقائمين علي بالشر تسمع أذناي.","92:12":"الصديق كالنخلة يزهو كالأرز في لبنان ينمو.","92:13":"مغروسين في بيت الرب في ديار إلهنا يزهرون.","92:14":"أيضا يثمرون في الشيبة. يكونون دساما وخضرا","92:15":"ليخبروا بأن الرب مستقيم. صخرتي هو ولا ظلم فيه.","93:1":"الرب قد ملك. لبس الجلال. لبس الرب القدرة. اتزر بها. أيضا تثبتت المسكونة. لا تتزعزع.","93:2":"كرسيك مثبتة منذ القدم. منذ الأزل أنت.","93:3":"رفعت الأنهار يا رب رفعت الأنهار صوتها. ترفع الأنهار عجيجها.","93:4":"من أصوات مياه كثيرة من غمار أمواج البحر الرب في العلى أقدر.","93:5":"شهاداتك ثابتة جدا. ببيتك تليق القداسة يا رب إلى طول الأيام.","94:1":"يا إله النقمات يا رب يا إله النقمات أشرق.","94:2":"ارتفع يا ديان الأرض. جاز صنيع المستكبرين.","94:3":"حتى متى الخطاة يا رب حتى متى الخطاة يشمتون؟","94:4":"يبقون يتكلمون بوقاحة. كل فاعلي الإثم يفتخرون.","94:5":"يسحقون شعبك يا رب ويذلون ميراثك.","94:6":"يقتلون الأرملة والغريب ويميتون اليتيم.","94:7":"ويقولون: [الرب لا يبصر وإله يعقوب لا يلاحظ].","94:8":"افهموا أيها البلداء في الشعب ويا جهلاء متى تعقلون؟","94:9":"الغارس الأذن ألا يسمع؟ الصانع العين ألا يبصر؟","94:10":"المؤدب الأمم ألا يبكت؟ المعلم الإنسان معرفة.","94:11":"الرب يعرف أفكار الإنسان أنها باطلة.","94:12":"طوبى للرجل الذي تؤدبه يا رب وتعلمه من شريعتك","94:13":"لتريحه من أيام الشر حتى تحفر للشرير حفرة.","94:14":"لأن الرب لا يرفض شعبه ولا يترك ميراثه.","94:15":"لأنه إلى العدل يرجع القضاء وعلى أثره كل مستقيمي القلوب.","94:16":"من يقوم لي على المسيئين؟ من يقف لي ضد فعلة الإثم؟","94:17":"لولا أن الرب معيني لسكنت نفسي سريعا أرض السكوت.","94:18":"إذ قلت: [قد زلت قدمي] فرحمتك يا رب تعضدني.","94:19":"عند كثرة همومي في داخلي تعزياتك تلذذ نفسي.","94:20":"هل يعاهدك كرسي المفاسد المختلق إثما على فريضة؟","94:21":"يزدحمون على نفس الصديق ويحكمون على دم زكي.","94:22":"فكان الرب لي صرحا وإلهي صخرة ملجإي","94:23":"ويرد عليهم إثمهم وبشرهم يفنيهم. يفنيهم الرب إلهنا.","95:1":"هلم نرنم للرب نهتف لصخرة خلاصنا.","95:2":"نتقدم أمامه بحمد وبترنيمات نهتف له.","95:3":"لأن الرب إله عظيم ملك كبير على كل الآلهة.","95:4":"الذي بيده مقاصير الأرض وخزائن الجبال له.","95:5":"الذي له البحر وهو صنعه ويداه سبكتا اليابسة.","95:6":"هلم نسجد ونركع ونجثو أمام الرب خالقنا","95:7":"لأنه هو إلهنا ونحن شعب مرعاه وغنم يده. اليوم إن سمعتم صوته","95:8":"فلا تقسوا قلوبكم كما في مريبة مثل يوم مسة في البرية","95:9":"حيث جربني آباؤكم. اختبروني. أبصروا أيضا فعلي","95:10":"أربعين سنة مقت ذلك الجيل وقلت: [هم شعب ضال قلبهم وهم لم يعرفوا سبلي].","95:11":"فأقسمت في غضبي لا يدخلون راحتي!","96:1":"رنموا للرب ترنيمة جديدة. رنمي للرب يا كل الأرض.","96:2":"رنموا للرب باركوا اسمه بشروا من يوم إلى يوم بخلاصه.","96:3":"حدثوا بين الأمم بمجده بين جميع الشعوب بعجائبه.","96:4":"لأن الرب عظيم وحميد جدا مهوب هو على كل الآلهة.","96:5":"لأن كل آلهة الشعوب أصنام أما الرب فقد صنع السماوات.","96:6":"مجد وجلال قدامه. العز والجمال في مقدسه.","96:7":"قدموا للرب يا قبائل الشعوب قدموا للرب مجدا وقوة.","96:8":"قدموا للرب مجد اسمه. هاتوا تقدمة وادخلوا دياره.","96:9":"اسجدوا للرب في زينة مقدسة. ارتعدي قدامه يا كل الأرض.","96:10":"قولوا بين الأمم: [الرب قد ملك. أيضا تثبتت المسكونة فلا تتزعزع. يدين الشعوب بالاستقامة].","96:11":"لتفرح السماوات ولتبتهج الأرض ليعج البحر وملؤه.","96:12":"ليجذل الحقل وكل ما فيه. لتترنم حينئذ كل أشجار الوعر","96:13":"أمام الرب لأنه جاء. جاء ليدين الأرض. يدين المسكونة بالعدل والشعوب بأمانته","97:1":"الرب قد ملك فلتبتهج الأرض ولتفرح الجزائر الكثيرة.","97:2":"السحاب والضباب حوله. العدل والحق قاعدة كرسيه.","97:3":"قدامه تذهب نار وتحرق أعداءه حوله.","97:4":"أضاءت بروقه المسكونة. رأت الأرض وارتعدت.","97:5":"ذابت الجبال مثل الشمع قدام الرب قدام سيد الأرض كلها.","97:6":"أخبرت السماوات بعدله ورأى جميع الشعوب مجده.","97:7":"يخزى كل عابدي تمثال منحوت المفتخرين بالأصنام. اسجدوا له يا جميع الآلهة.","97:8":"سمعت صهيون ففرحت وابتهجت بنات يهوذا من أجل أحكامك يا رب.","97:9":"لأنك أنت يا رب علي على كل الأرض. علوت جدا على كل الآلهة.","97:10":"يا محبي الرب أبغضوا الشر. هو حافظ نفوس أتقيائه. من يد الأشرار ينقذهم.","97:11":"نور قد زرع للصديق وفرح للمستقيمي القلب.","97:12":"افرحوا أيها الصديقون بالرب واحمدوا ذكر قدسه.","98:1":"رنموا للرب ترنيمة جديدة لأنه صنع عجائب. خلصته يمينه وذراع قدسه.","98:2":"أعلن الرب خلاصه. لعيون الأمم كشف بره.","98:3":"ذكر رحمته وأمانته لبيت إسرائيل. رأت كل أقاصي الأرض خلاص إلهنا.","98:4":"اهتفي للرب يا كل الأرض. اهتفوا ورنموا وغنوا.","98:5":"رنموا للرب بعود. بعود وصوت نشيد.","98:6":"بالأبواق وصوت الصور اهتفوا قدام الملك الرب.","98:7":"ليعج البحر وملؤه المسكونة والساكنون فيها.","98:8":"الأنهار لتصفق بالأيادي الجبال لترنم معا","98:9":"أمام الرب لأنه جاء ليدين الأرض. يدين المسكونة بالعدل والشعوب بالاستقامة.","99:1":"الرب قد ملك. ترتعد الشعوب. هو جالس على الكروبيم. تتزلزل الأرض.","99:2":"الرب عظيم في صهيون وعال هو على كل الشعوب.","99:3":"يحمدون اسمك العظيم والمهوب. قدوس هو.","99:4":"وعز الملك أن يحب الحق. أنت ثبت الاستقامة. أنت أجريت حقا وعدلا في يعقوب.","99:5":"علوا الرب إلهنا واسجدوا عند موطئ قدميه. قدوس هو.","99:6":"موسى وهارون بين كهنته وصموئيل بين الذين يدعون باسمه. دعوا الرب وهو استجاب لهم.","99:7":"بعمود السحاب كلمهم. حفظوا شهاداته والفريضة التي أعطاهم.","99:8":"أيها الرب إلهنا أنت استجبت لهم. إلها غفورا كنت لهم ومنتقما على أفعالهم.","99:9":"علوا الرب إلهنا واسجدوا في جبل قدسه لأن الرب إلهنا قدوس.","100:1":"مزمور حمد اهتفي للرب يا كل الأرض.","100:2":"اعبدوا الرب بفرح. ادخلوا إلى حضرته بترنم.","100:3":"اعلموا أن الرب هو الله. هو صنعنا وله نحن شعبه وغنم مرعاه.","100:4":"ادخلوا أبوابه بحمد دياره بالتسبيح. احمدوه باركوا اسمه","100:5":"لأن الرب صالح. إلى الأبد رحمته وإلى دور فدور أمانته.","101:1":"لداود. مزمور رحمة وحكما أغني. لك يا رب أرنم.","101:2":"أتعقل في طريق كامل. متى تأتي إلي؟ أسلك في كمال قلبي في وسط بيتي.","101:3":"لا أضع قدام عيني أمرا رديئا. عمل الزيغان أبغضت. لا يلصق بي.","101:4":"قلب معوج يبعد عني. الشرير لا أعرفه.","101:5":"الذي يغتاب صاحبه سرا هذا أقطعه. مستكبر العين ومنتفخ القلب لا أحتمله.","101:6":"عيناي على أمناء الأرض لكي أجلسهم معي. السالك طريقا كاملا هو يخدمني.","101:7":"لا يسكن وسط بيتي عامل غش. المتكلم بالكذب لا يثبت أمام عيني.","101:8":"باكرا أبيد جميع أشرار الأرض لأقطع من مدينة الرب كل فاعلي الإثم.","102:1":"صلاة لمسكين إذا أعيا وسكب شكواه قدام الله يا رب استمع صلاتي وليدخل إليك صراخي.","102:2":"لا تحجب وجهك عني في يوم ضيقي. أمل إلي أذنك في يوم أدعوك. استجب لي سريعا.","102:3":"لأن أيامي قد فنيت في دخان وعظامي مثل وقيد قد يبست.","102:4":"ملفوح كالعشب ويابس قلبي حتى سهوت عن أكل خبزي.","102:5":"من صوت تنهدي لصق عظمي بلحمي.","102:6":"أشبهت قوق البرية. صرت مثل بومة الخرب.","102:7":"سهدت وصرت كعصفور منفرد على السطح.","102:8":"اليوم كله عيرني أعدائي. الحنقون علي حلفوا علي.","102:9":"إني قد أكلت الرماد مثل الخبز ومزجت شرابي بدموع","102:10":"بسبب غضبك وسخطك لأنك حملتني وطرحتني.","102:11":"أيامي كظل مائل وأنا مثل العشب يبست.","102:12":"أما أنت يا رب فإلى الدهر جالس وذكرك إلى دور فدور.","102:13":"أنت تقوم وترحم صهيون لأنه وقت الرأفة لأنه جاء الميعاد.","102:14":"لأن عبيدك قد سروا بحجارتها وحنوا إلى ترابها.","102:15":"فتخشى الأمم اسم الرب وكل ملوك الأرض مجدك.","102:16":"إذا بنى الرب صهيون يرى بمجده.","102:17":"التفت إلى صلاة المضطر ولم يرذل دعاءهم.","102:18":"يكتب هذا للدور الآخر وشعب سوف يخلق يسبح الرب.","102:19":"لأنه أشرف من علو قدسه. الرب من السماء إلى الأرض نظر","102:20":"ليسمع أنين الأسير ليطلق بني الموت","102:21":"لكي يحدث في صهيون باسم الرب وبتسبيحه في أورشليم","102:22":"عند اجتماع الشعوب معا والممالك لعبادة الرب.","102:23":"ضعف في الطريق قوتي. قصر أيامي.","102:24":"أقول: [يا إلهي لا تقبضني في نصف أيامي. إلى دهر الدهور سنوك.","102:25":"من قدم أسست الأرض والسماوات هي عمل يديك.","102:26":"هي تبيد وأنت تبقى وكلها كثوب تبلى كرداء تغيرهن فتتغير.","102:27":"وأنت هو وسنوك لن تنتهي.","102:28":"أبناء عبيدك يسكنون وذريتهم تثبت أمامك].","103:1":"لداود باركي يا نفسي الرب وكل ما في باطني ليبارك اسمه القدوس.","103:2":"باركي يا نفسي الرب ولا تنسي كل حسناته.","103:3":"الذي يغفر جميع ذنوبك. الذي يشفي كل أمراضك.","103:4":"الذي يفدي من الحفرة حياتك. الذي يكللك بالرحمة والرأفة.","103:5":"الذي يشبع بالخير عمرك فيتجدد مثل النسر شبابك.","103:6":"الرب مجري العدل والقضاء لجميع المظلومين.","103:7":"عرف موسى طرقه وبني إسرائيل أفعاله.","103:8":"الرب رحيم ورأوف طويل الروح وكثير الرحمة.","103:9":"لا يحاكم إلى الأبد ولا يحقد إلى الدهر.","103:10":"لم يصنع معنا حسب خطايانا ولم يجازنا حسب آثامنا.","103:11":"لأنه مثل ارتفاع السماوات فوق الأرض قويت رحمته على خائفيه.","103:12":"كبعد المشرق من المغرب أبعد عنا معاصينا.","103:13":"كما يترأف الأب على البنين يترأف الرب على خائفيه.","103:14":"لأنه يعرف جبلتنا. يذكر أننا تراب نحن.","103:15":"الإنسان مثل العشب أيامه. كزهر الحقل كذلك يزهر.","103:16":"لأن ريحا تعبر عليه فلا يكون ولا يعرفه موضعه بعد.","103:17":"أما رحمة الرب فإلى الدهر والأبد على خائفيه وعدله على بني البنين","103:18":"لحافظي عهده وذاكري وصاياه ليعملوها.","103:19":"الرب في السماوات ثبت كرسيه ومملكته على الكل تسود.","103:20":"باركوا الرب يا ملائكته المقتدرين قوة الفاعلين أمره عند سماع صوت كلامه.","103:21":"باركوا الرب يا جميع جنوده خدامه العاملين مرضاته.","103:22":"باركوا الرب يا جميع أعماله. في كل مواضع سلطانه باركي يا نفسي الرب.","104:1":"باركي يا نفسي الرب. يا رب إلهي قد عظمت جدا. مجدا وجلالا لبست.","104:2":"اللابس النور كثوب الباسط السماوات كشقة.","104:3":"المسقف علاليه بالمياه. الجاعل السحاب مركبته. الماشي على أجنحة الريح.","104:4":"الصانع ملائكته رياحا وخدامه نارا ملتهبة.","104:5":"المؤسس الأرض على قواعدها فلا تتزعزع إلى الدهر والأبد.","104:6":"كسوتها الغمر كثوب. فوق الجبال تقف المياه.","104:7":"من انتهارك تهرب من صوت رعدك تفر.","104:8":"تصعد إلى الجبال. تنزل إلى البقاع إلى الموضع الذي أسسته لها.","104:9":"وضعت لها تخما لا تتعداه. لا ترجع لتغطي الأرض.","104:10":"المفجر عيونا في الأودية. بين الجبال تجري.","104:11":"تسقي كل حيوان البر. تكسر الفراء ظمأها.","104:12":"فوقها طيور السماء تسكن. من بين الأغصان تسمع صوتا.","104:13":"الساقي الجبال من علاليه. من ثمر أعمالك تشبع الأرض.","104:14":"المنبت عشبا للبهائم وخضرة لخدمة الإنسان لإخراج خبز من الأرض","104:15":"وخمر تفرح قلب الإنسان لإلماع وجهه أكثر من الزيت وخبز يسند قلب الإنسان.","104:16":"تشبع أشجار الرب أرز لبنان الذي نصبه.","104:17":"حيث تعشش هناك العصافير. أما اللقلق فالسرو بيته.","104:18":"الجبال العالية للوعول. الصخور ملجأ للوبار.","104:19":"صنع القمر للمواقيت. الشمس تعرف مغربها.","104:20":"تجعل ظلمة فيصير ليل. فيه يدب كل حيوان الوعر.","104:21":"الأشبال تزمجر لتخطف ولتلتمس من الله طعامها.","104:22":"تشرق الشمس فتجتمع وفي مآويها تربض.","104:23":"الإنسان يخرج إلى عمله وإلى شغله إلى المساء.","104:24":"ما أعظم أعمالك يا رب! كلها بحكمة صنعت. ملآنة الأرض من غناك.","104:25":"هذا البحر الكبير الواسع الأطراف. هناك دبابات بلا عدد. صغار حيوان مع كبار.","104:26":"هناك تجري السفن. لوياثان هذا خلقته ليلعب فيه.","104:27":"كلها إياك تترجى لترزقها قوتها في حينه.","104:28":"تعطيها فتلتقط. تفتح يدك فتشبع خيرا.","104:29":"تحجب وجهك فترتاع. تنزع أرواحها فتموت وإلى ترابها تعود.","104:30":"ترسل روحك فتخلق. وتجدد وجه الأرض.","104:31":"يكون مجد الرب إلى الدهر. يفرح الرب بأعماله.","104:32":"الناظر إلى الأرض فترتعد. يمس الجبال فتدخن.","104:33":"أغني للرب في حياتي. أرنم لإلهي ما دمت موجودا","104:34":"فيلذ له نشيدي وأنا أفرح بالرب.","104:35":"لتبد الخطاة من الأرض والأشرار لا يكونوا بعد. باركي يا نفسي الرب. هللويا.","105:1":"احمدوا الرب. ادعوا باسمه. عرفوا بين الأمم بأعماله.","105:2":"غنوا له. رنموا له. أنشدوا بكل عجائبه.","105:3":"افتخروا باسمه القدوس. لتفرح قلوب الذين يلتمسون الرب.","105:4":"اطلبوا الرب وقدرته. التمسوا وجهه دائما.","105:5":"اذكروا عجائبه التي صنع آياته وأحكام فمه","105:6":"يا ذرية إبراهيم عبده يا بني يعقوب مختاريه.","105:7":"هو الرب إلهنا في كل الأرض أحكامه.","105:8":"ذكر إلى الدهر عهده كلاما أوصى به إلى ألف دور","105:9":"الذي عاهد به إبراهيم وقسمه لإسحاق","105:10":"فثبته ليعقوب فريضة ولإسرائيل عهدا أبديا","105:11":"قائلا: [لك أعطي أرض كنعان حبل ميراثكم].","105:12":"إذ كانوا عددا يحصى قليلين وغرباء فيها.","105:13":"ذهبوا من أمة إلى أمة من مملكة إلى شعب آخر.","105:14":"فلم يدع إنسانا يظلمهم بل وبخ ملوكا من أجلهم","105:15":"قائلا: [لا تمسوا مسحائي ولا تسيئوا إلى أنبيائي].","105:16":"دعا بالجوع على الأرض. كسر قوام الخبز كله.","105:17":"أرسل أمامهم رجلا. بيع يوسف عبدا.","105:18":"آذوا بالقيد رجليه. في الحديد دخلت نفسه","105:19":"إلى وقت مجيء كلمته. قول الرب امتحنه.","105:20":"أرسل الملك فحله. أرسل سلطان الشعب فأطلقه.","105:21":"أقامه سيدا على بيته ومسلطا على كل ملكه","105:22":"ليأسر رؤساءه حسب إرادته ويعلم مشايخه حكمة.","105:23":"فجاء إسرائيل إلى مصر ويعقوب تغرب في أرض حام.","105:24":"جعل شعبه مثمرا جدا وأعزه على أعدائه.","105:25":"حول قلوبهم ليبغضوا شعبه ليحتالوا على عبيده.","105:26":"أرسل موسى عبده وهارون الذي اختاره.","105:27":"أقاما بينهم كلام آياته وعجائب في أرض حام.","105:28":"أرسل ظلمة فأظلمت ولم يعصوا كلامه.","105:29":"حول مياههم إلى دم وقتل أسماكهم.","105:30":"أفاضت أرضهم ضفادع حتى في مخادع ملوكهم.","105:31":"أمر فجاء الذبان والبعوض في كل تخومهم.","105:32":"جعل أمطارهم بردا ونارا ملتهبة في أرضهم.","105:33":"ضرب كرومهم وتينهم وكسر كل أشجار تخومهم.","105:34":"أمر فجاء الجراد وغوغاء بلا عدد","105:35":"فأكل كل عشب في بلادهم. وأكل أثمار أرضهم.","105:36":"قتل كل بكر في أرضهم أوائل كل قوتهم.","105:37":"فأخرجهم بفضة وذهب ولم يكن في أسباطهم عاثر.","105:38":"فرحت مصر بخروجهم لأن رعبهم سقط عليهم.","105:39":"بسط سحابا سجفا ونارا لتضيء الليل.","105:40":"سألوا فأتاهم بالسلوى وخبز السماء أشبعهم.","105:41":"شق الصخرة فانفجرت المياه. جرت في اليابسة نهرا.","105:42":"لأنه ذكر كلمة قدسه مع إبراهيم عبده","105:43":"فأخرج شعبه بابتهاج ومختاريه بترنم.","105:44":"وأعطاهم أراضي الأمم. وتعب الشعوب ورثوه","105:45":"لكي يحفظوا فرائضه ويطيعوا شرائعه. هللويا.","106:1":"هللويا. احمدوا الرب لأنه صالح لأن إلى الأبد رحمته.","106:2":"من يتكلم بجبروت الرب؟ من يخبر بكل تسابيحه؟","106:3":"طوبى للحافظين الحق وللصانع البر في كل حين.","106:4":"اذكرني يا رب برضا شعبك. تعهدني بخلاصك","106:5":"لأرى خير مختاريك. لأفرح بفرح أمتك. لأفتخر مع ميراثك.","106:6":"أخطأنا مع آبائنا. أسأنا وأذنبنا.","106:7":"آباؤنا في مصر لم يفهموا عجائبك. لم يذكروا كثرة مراحمك فتمردوا عند البحر عند بحر سوف.","106:8":"فخلصهم من أجل اسمه ليعرف بجبروته.","106:9":"وانتهر بحر سوف فيبس وسيرهم في اللجج كالبرية.","106:10":"وخلصهم من يد المبغض وفداهم من يد العدو.","106:11":"وغطت المياه مضايقيهم. واحد منهم لم يبق.","106:12":"فآمنوا بكلامه. غنوا بتسبيحه.","106:13":"أسرعوا فنسوا أعماله. لم ينتظروا مشورته.","106:14":"بل اشتهوا شهوة في البرية وجربوا الله في القفر.","106:15":"فأعطاهم سؤلهم وأرسل هزالا في أنفسهم.","106:16":"وحسدوا موسى في المحلة وهارون قدوس الرب.","106:17":"فتحت الأرض وابتلعت داثان وطبقت على جماعة أبيرام","106:18":"واشتعلت نار في جماعتهم. اللهيب أحرق الأشرار.","106:19":"صنعوا عجلا في حوريب وسجدوا لتمثال مسبوك","106:20":"وأبدلوا مجدهم بمثال ثور آكل عشب.","106:21":"نسوا الله مخلصهم الصانع عظائم في مصر","106:22":"وعجائب في أرض حام ومخاوف على بحر سوف","106:23":"فقال بإهلاكهم. لولا موسى مختاره وقف في الثغر قدامه ليصرف غضبه عن إتلافهم.","106:24":"ورذلوا الأرض الشهية. لم يؤمنوا بكلمته.","106:25":"بل تمرمروا في خيامهم. لم يسمعوا لصوت الرب","106:26":"فرفع يده عليهم ليسقطهم في البرية","106:27":"وليسقط نسلهم بين الأمم وليبددهم في الأراضي.","106:28":"وتعلقوا ببعل فغور وأكلوا ذبائح الموتى.","106:29":"وأغاظوه بأعمالهم فاقتحمهم الوبأ.","106:30":"فوقف فينحاس ودان فامتنع الوبأ.","106:31":"فحسب له ذلك برا إلى دور فدور إلى الأبد.","106:32":"وأسخطوه على ماء مريبة حتى تأذى موسى بسببهم.","106:33":"لأنهم أمروا روحه حتى فرط بشفتيه.","106:34":"لم يستأصلوا الأمم الذين قال لهم الرب عنهم","106:35":"بل اختلطوا بالأمم وتعلموا أعمالهم","106:36":"وعبدوا أصنامهم فصارت لهم شركا.","106:37":"وذبحوا بنيهم وبناتهم للأوثان","106:38":"وأهرقوا دما زكيا دم بنيهم وبناتهم الذين ذبحوهم لأصنام كنعان وتدنست الأرض بالدماء","106:39":"وتنجسوا بأعمالهم وزنوا بأفعالهم.","106:40":"فحمي غضب الرب على شعبه وكره ميراثه","106:41":"وأسلمهم ليد الأمم وتسلط عليهم مبغضوهم.","106:42":"وضغطهم أعداؤهم فذلوا تحت يدهم","106:43":"مرات كثيرة أنقذهم. أما هم فعصوه بمشورتهم وانحطوا بإثمهم.","106:44":"فنظر إلى ضيقهم إذ سمع صراخهم","106:45":"وذكر لهم عهده وندم حسب كثرة رحمته.","106:46":"وأعطاهم نعمة قدام كل الذين سبوهم.","106:47":"خلصنا أيها الرب إلهنا واجمعنا من بين الأمم لنحمد اسم قدسك ونتفاخر بتسبيحك.","106:48":"مبارك الرب إله إسرائيل من الأزل وإلى الأبد. ويقول كل الشعب: [آمين]. هللويا.","107:1":"احمدوا الرب لأنه صالح لأن إلى الأبد رحمته.","107:2":"ليقل مفديو الرب الذين فداهم من يد العدو","107:3":"ومن البلدان جمعهم من المشرق ومن المغرب من الشمال ومن البحر.","107:4":"تاهوا في البرية في قفر بلا طريق. لم يجدوا مدينة سكن.","107:5":"جياع عطاش أيضا أعيت أنفسهم فيهم.","107:6":"فصرخوا إلى الرب في ضيقهم فأنقذهم من شدائدهم","107:7":"وهداهم طريقا مستقيما ليذهبوا إلى مدينة سكن.","107:8":"فليحمدوا الرب على رحمته وعجائبه لبني آدم.","107:9":"لأنه أشبع نفسا مشتهية وملأ نفسا جائعة خبزا","107:10":"الجلوس في الظلمة وظلال الموت موثقين بالذل والحديد.","107:11":"لأنهم عصوا كلام الله وأهانوا مشورة العلي فأذل قلوبهم بتعب.","107:12":"عثروا ولا معين.","107:13":"ثم صرخوا إلى الرب في ضيقهم فخلصهم من شدائدهم.","107:14":"أخرجهم من الظلمة وظلال الموت وقطع قيودهم.","107:15":"فليحمدوا الرب على رحمته وعجائبه لبني آدم.","107:16":"لأنه كسر مصاريع نحاس وقطع عوارض حديد.","107:17":"والجهال من طريق معصيتهم ومن آثامهم يذلون.","107:18":"كرهت أنفسهم كل طعام واقتربوا إلى أبواب الموت.","107:19":"فصرخوا إلى الرب في ضيقهم فخلصهم من شدائدهم.","107:20":"أرسل كلمته فشفاهم ونجاهم من تهلكاتهم.","107:21":"فليحمدوا الرب على رحمته وعجائبه لبني آدم","107:22":"وليذبحوا له ذبائح الحمد وليعدوا أعماله بترنم.","107:23":"النازلون إلى البحر في السفن العاملون عملا في المياه الكثيرة","107:24":"هم رأوا أعمال الرب وعجائبه في العمق.","107:25":"أمر فأهاج ريحا عاصفة فرفعت أمواجه.","107:26":"يصعدون إلى السماوات يهبطون إلى الأعماق. ذابت أنفسهم بالشقاء.","107:27":"يتمايلون ويترنحون مثل السكران وكل حكمتهم ابتلعت.","107:28":"فيصرخون إلى الرب في ضيقهم ومن شدائدهم يخلصهم.","107:29":"يهدئ العاصفة فتسكن وتسكت أمواجها.","107:30":"فيفرحون لأنهم هدأوا فيهديهم إلى المرفإ الذي يريدونه.","107:31":"فليحمدوا الرب على رحمته وعجائبه لبني آدم.","107:32":"وليرفعوه في مجمع الشعب وليسبحوه في مجلس المشايخ.","107:33":"يجعل الأنهار قفارا ومجاري المياه معطشة","107:34":"والأرض المثمرة سبخة من شر الساكنين فيها.","107:35":"يجعل القفر غدير مياه وأرضا يبسا ينابيع مياه.","107:36":"ويسكن هناك الجياع فيهيئون مدينة سكن.","107:37":"ويزرعون حقولا ويغرسون كروما فتصنع ثمر غلة.","107:38":"ويباركهم فيكثرون جدا ولا يقلل بهائمهم.","107:39":"ثم يقلون وينحنون من ضغط الشر والحزن.","107:40":"يسكب هوانا على رؤساء ويضلهم في تيه بلا طريق","107:41":"ويعلي المسكين من الذل ويجعل القبائل مثل قطعان الغنم.","107:42":"يرى ذلك المستقيمون فيفرحون وكل إثم يسد فاه.","107:43":"من كان حكيما يحفظ هذا ويتعقل مراحم الرب.","108:1":"تسبيحة. مزمور لداود ثابت قلبي يا الله. أغني وأرنم. كذلك مجدي.","108:2":"استيقظي أيتها الرباب والعود. أنا أستيقظ سحرا.","108:3":"أحمدك بين الشعوب يا رب وأرنم لك بين الأمم.","108:4":"لأن رحمتك قد عظمت فوق السماوات وإلى الغمام حقك.","108:5":"ارتفع اللهم على السماوات وليرتفع على كل الأرض مجدك.","108:6":"لكي ينجو أحباؤك. خلص بيمينك واستجب لي.","108:7":"الله قد تكلم بقدسه. أبتهج أقسم شكيم وأقيس وادي سكوت.","108:8":"لي جلعاد لي منسى. أفرايم خوذة رأسي. يهوذا صولجاني.","108:9":"موآب مرحضتي. على أدوم أطرح نعلي. يا فلسطين اهتفي علي.","108:10":"من يقودني إلى المدينة المحصنة؟ من يهديني إلى أدوم؟","108:11":"أليس أنت يا الله الذي رفضتنا ولا تخرج يا الله مع جيوشنا؟","108:12":"أعطنا عونا في الضيق فباطل هو خلاص الإنسان.","108:13":"بالله نصنع ببأس وهو يدوس أعداءنا.","109:1":"لإمام المغنين. لداود. مزمور يا إله تسبيحي لا تسكت","109:2":"لأنه قد انفتح علي فم الشرير وفم الغش. تكلموا معي بلسان كذب","109:3":"بكلام بغض أحاطوا بي وقاتلوني بلا سبب.","109:4":"بدل محبتي يخاصمونني. أما أنا فصلاة.","109:5":"وضعوا علي شرا بدل خير وبغضا بدل حبي.","109:6":"فأقم أنت عليه شريرا وليقف شيطان عن يمينه.","109:7":"إذا حوكم فليخرج مذنبا وصلاته فلتكن خطية.","109:8":"لتكن أيامه قليلة ووظيفته ليأخذها آخر.","109:9":"ليكن بنوه أيتاما وامرأته أرملة.","109:10":"ليته بنوه تيهانا ويستعطوا ويلتمسوا خيرا من خربهم.","109:11":"ليصطد المرابي كل ما له ولينهب الغرباء تعبه.","109:12":"لا يكن له باسط رحمة ولا يكن مترغف على يتاماه.","109:13":"لتنقرض ذريته. في الجيل القادم ليمح اسمهم.","109:14":"ليذكر إثم آبائه لدى الرب ولا تمح خطية أمه.","109:15":"لتكن أمام الرب دائما وليقرض من الأرض ذكرهم.","109:16":"من أجل أنه لم يذكر أن يصنع رحمة بل طرد إنسانا مسكينا وفقيرا والمنسحق القلب ليميته.","109:17":"وأحب اللعنة فأتته ولم يسر بالبركة فتباعدت عنه.","109:18":"ولبس اللعنة مثل ثوبه فدخلت كمياه في حشاه وكزيت في عظامه.","109:19":"لتكن له كثوب يتعطف به وكمنطقة يتنطق بها دائما.","109:20":"هذه أجرة مبغضي من عند الرب وأجرة المتكلمين شرا على نفسي.","109:21":"أما أنت يا رب السيد فاصنع معي من أجل اسمك. لأن رحمتك طيبة نجني.","109:22":"فإني فقير ومسكين أنا وقلبي مجروح في داخلي.","109:23":"كظل عند ميله ذهبت. انتفضت كجرادة.","109:24":"ركبتاي ارتعشتا من الصوم ولحمي هزل عن سمن.","109:25":"وأنا صرت عارا عندهم. ينظرون إلي وينغضون رؤوسهم.","109:26":"أعني يا رب إلهي. خلصني حسب رحمتك.","109:27":"وليعلموا أن هذه هي يدك. أنت يا رب فعلت هذا.","109:28":"أما هم فيلعنون وأما أنت فتبارك. قاموا وخزوا أما عبدك فيفرح.","109:29":"ليلبس خصمائي خجلا وليتعطفوا بخزيهم كالرداء.","109:30":"أحمد الرب جدا بفمي وفي وسط كثيرين أسبحه.","109:31":"لأنه يقوم عن يمين المسكين ليخلصه من القاضين على نفسه.","110:1":"لداود. مزمور قال الرب لربي: [اجلس عن يميني حتى أضع أعداءك موطئا لقدميك].","110:2":"يرسل الرب قضيب عزك من صهيون. تسلط في وسط أعدائك.","110:3":"شعبك منتدب في يوم قوتك في زينة مقدسة من رحم الفجر. لك طل حداثتك.","110:4":"أقسم الرب ولن يندم: [أنت كاهن إلى الأبد على رتبة ملكي صادق].","110:5":"الرب عن يمينك يحطم في يوم رجزه ملوكا.","110:6":"يدين بين الأمم. ملأ جثثا أرضا واسعة. سحق رؤوسها.","110:7":"من النهر يشرب في الطريق لذلك يرفع الرأس.","111:1":"هللويا. أحمد الرب بكل قلبي في مجلس المستقيمين وجماعتهم.","111:2":"عظيمة هي أعمال الرب. مطلوبة لكل المسرورين بها.","111:3":"جلال وبهاء عمله وعدله قائم إلى الأبد.","111:4":"صنع ذكرا لعجائبه. حنان ورحيم هو الرب.","111:5":"أعطى خائفيه طعاما. يذكر إلى الأبد عهده.","111:6":"أخبر شعبه بقوة أعماله ليعطيهم ميراث الأمم.","111:7":"أعمال يديه أمانة وحق. كل وصاياه أمينة","111:8":"ثابتة مدى الدهر والأبد مصنوعة بالحق والاستقامة.","111:9":"أرسل فداء لشعبه. أقام إلى الأبد عهده. قدوس ومهوب اسمه.","111:10":"رأس الحكمة مخافة الرب. فطنة جيدة لكل عامليها. تسبيحه قائم إلى الأبد.","112:1":"هللويا. طوبى للرجل المتقي الرب المسرور جدا بوصاياه.","112:2":"نسله يكون قويا في الأرض. جيل المستقيمين يبارك.","112:3":"رغد وغنى في بيته وبره قائم إلى الأبد.","112:4":"نور أشرق في الظلمة للمستقيمين. هو حنان ورحيم وصديق.","112:5":"سعيد هو الرجل الذي يترأف ويقرض. يدبر أموره بالحق.","112:6":"لأنه لا يتزعزع إلى الدهر. الصديق يكون لذكر أبدي.","112:7":"لا يخشى من خبر سوء. قلبه ثابت متكلا على الرب.","112:8":"قلبه ممكن فلا يخاف حتى يرى بمضايقيه.","112:9":"فرق أعطى المساكين. بره قائم إلى الأبد. قرنه ينتصب بالمجد.","112:10":"الشرير يرى فيغضب. يحرق أسنانه ويذوب. شهوة الشرير تبيد.","113:1":"هللويا. سبحوا يا عبيد الرب. سبحوا اسم الرب.","113:2":"ليكن اسم الرب مباركا من الآن وإلى الأبد.","113:3":"من مشرق الشمس إلى مغربها اسم الرب مسبح.","113:4":"الرب عال فوق كل الأمم. فوق السماوات مجده.","113:5":"من مثل الرب إلهنا الساكن في الأعالي","113:6":"الناظر الأسافل في السماوات وفي الأرض","113:7":"المقيم المسكين من التراب الرافع البائس من المزبلة","113:8":"ليجلسه مع أشراف مع أشراف شعبه.","113:9":"المسكن العاقر في بيت أم أولاد فرحانة! هللويا.","114:1":"عند خروج إسرائيل من مصر وبيت يعقوب من شعب أعجم","114:2":"كان يهوذا مقدسه وإسرائيل محل سلطانه.","114:3":"البحر رآه فهرب. الأردن رجع إلى خلف.","114:4":"الجبال قفزت مثل الكباش والآكام مثل حملان الغنم.","114:5":"ما لك أيها البحر قد هربت وما لك أيها الأردن قد رجعت إلى خلف","114:6":"وما لكن أيتها الجبال قد قفزتن مثل الكباش وأيتها التلال مثل حملان الغنم؟","114:7":"أيتها الأرض تزلزلي من قدام الرب من قدام إله يعقوب!","114:8":"المحول الصخرة إلى غدران مياه الصوان إلى ينابيع مياه.","115:1":"ليس لنا يا رب ليس لنا لكن لاسمك أعط مجدا من أجل رحمتك من أجل أمانتك.","115:2":"لماذا يقول الأمم: [أين هو إلههم؟]","115:3":"إن إلهنا في السماء. كلما شاء صنع.","115:4":"أصنامهم فضة وذهب عمل أيدي الناس.","115:5":"لها أفواه ولا تتكلم. لها أعين ولا تبصر.","115:6":"لها آذان ولا تسمع. لها مناخر ولا تشم.","115:7":"لها أيد ولا تلمس. لها أرجل ولا تمشي ولا تنطق بحناجرها.","115:8":"مثلها يكون صانعوها بل كل من يتكل عليها.","115:9":"يا إسرائيل اتكل على الرب. هو معينهم ومجنهم.","115:10":"يا بيت هارون اتكلوا على الرب. هو معينهم ومجنهم.","115:11":"يا متقي الرب اتكلوا على الرب. هو معينهم ومجنهم.","115:12":"الرب قد ذكرنا فيبارك. يبارك بيت إسرائيل. يبارك بيت هارون.","115:13":"يبارك متقي الرب الصغار مع الكبار.","115:14":"ليزد الرب عليكم. عليكم وعلى أبنائكم.","115:15":"أنتم مباركون للرب الصانع السماوات والأرض.","115:16":"السماوات سماوات للرب أما الأرض فأعطاها لبني آدم.","115:17":"ليس الأموات يسبحون الرب ولا من ينحدر إلى أرض السكوت.","115:18":"أما نحن فنبارك الرب من الآن وإلى الدهر. هللويا.","116:1":"أحببت لأن الرب يسمع صوتي تضرعاتي.","116:2":"لأنه أمال أذنه إلي فأدعوه مدة حياتي.","116:3":"اكتنفتني حبال الموت. أصابتني شدائد الهاوية. كابدت ضيقا وحزنا.","116:4":"وباسم الرب دعوت: [آه يا رب نج نفسي].","116:5":"الرب حنان وصديق وإلهنا رحيم.","116:6":"الرب حافظ البسطاء. تذللت فخلصني.","116:7":"ارجعي يا نفسي إلى راحتك لأن الرب قد أحسن إليك.","116:8":"لأنك أنقذت نفسي من الموت وعيني من الدمعة ورجلي من الزلق.","116:9":"أسلك قدام الرب في أرض الأحياء.","116:10":"آمنت لذلك تكلمت. أنا تذللت جدا.","116:11":"أنا قلت في حيرتي: [كل إنسان كاذب].","116:12":"ماذا أرد للرب من أجل كل حسناته لي؟","116:13":"كأس الخلاص أتناول وباسم الرب أدعو.","116:14":"أوفي نذوري للرب مقابل كل شعبه.","116:15":"عزيز في عيني الرب موت أتقيائه.","116:16":"آه يا رب. لأني عبدك. أنا عبدك ابن أمتك. حللت قيودي.","116:17":"فلك أذبح ذبيحة حمد وباسم الرب أدعو.","116:18":"أوفي نذوري للرب مقابل شعبه","116:19":"في ديار بيت الرب في وسطك يا أورشليم. هللويا.","117:1":"سبحوا الرب يا كل الأمم. حمدوه يا كل الشعوب.","117:2":"لأن رحمته قد قويت علينا وأمانة الرب إلى الدهر. هللويا.","118:1":"احمدوا الرب لأنه صالح لأن إلى الأبد رحمته.","118:2":"ليقل إسرائيل: [إن إلى الأبد رحمته].","118:3":"ليقل بيت هارون: [إن إلى الأبد رحمته].","118:4":"ليقل متقو الرب: [إن إلى الأبد رحمته].","118:5":"من الضيق دعوت الرب فأجابني من الرحب.","118:6":"الرب لي فلا أخاف. ماذا يصنع بي الإنسان؟","118:7":"الرب لي بين معيني وأنا سأرى بأعدائي.","118:8":"الاحتماء بالرب خير من التوكل على إنسان.","118:9":"الاحتماء بالرب خير من التوكل على الرؤساء.","118:10":"كل الأمم أحاطوا بي. باسم الرب أبيدهم.","118:11":"أحاطوا بي واكتنفوني. باسم الرب أبيدهم.","118:12":"أحاطوا بي مثل النحل. انطفأوا كنار الشوك. باسم الرب أبيدهم.","118:13":"دحرتني دحورا لأسقط. أما الرب فعضدني.","118:14":"قوتي وترنمي الرب وقد صار لي خلاصا.","118:15":"صوت ترنم وخلاص في خيام الصديقين. يمين الرب صانعة ببأس.","118:16":"يمين الرب مرتفعة. يمين الرب صانعة ببأس.","118:17":"لا أموت بل أحيا وأحدث بأعمال الرب.","118:18":"تأديبا أدبني الرب وإلى الموت لم يسلمني.","118:19":"افتحوا لي أبواب البر. أدخل فيها وأحمد الرب.","118:20":"هذا الباب للرب. الصديقون يدخلون فيه.","118:21":"أحمدك لأنك استجبت لي وصرت لي خلاصا.","118:22":"الحجر الذي رفضه البناؤون قد صار رأس الزاوية.","118:23":"من قبل الرب كان هذا وهو عجيب في أعيننا.","118:24":"هذا هو اليوم الذي صنعه الرب. نبتهج ونفرح فيه.","118:25":"آه يا رب خلص! آه يا رب أنقذ!","118:26":"مبارك الآتي باسم الرب. باركناكم من بيت الرب.","118:27":"الرب هو الله وقد أنار لنا. أوثقوا الذبيحة بربط إلى قرون المذبح.","118:28":"إلهي أنت فأحمدك. إلهي فأرفعك.","118:29":"احمدوا الرب لأنه صالح لأن إلى الأبد رحمته.","119:1":"طوبى للكاملين طريقا السالكين في شريعة الرب.","119:2":"طوبى لحافظي شهاداته. من كل قلوبهم يطلبونه.","119:3":"أيضا لا يرتكبون إثما. في طرقه يسلكون.","119:4":"أنت أوصيت بوصاياك أن تحفظ تماما.","119:5":"ليت طرقي تثبت في حفظ فرائضك.","119:6":"حينئذ لا أخزى إذا نظرت إلى كل وصاياك.","119:7":"أحمدك باستقامة قلب عند تعلمي أحكام عدلك.","119:8":"وصاياك أحفظ. لا تتركني إلى الغاية.","119:9":"ب بم يزكي الشاب طريقه؟ بحفظه إياه حسب كلامك.","119:10":"بكل قلبي طلبتك. لا تضلني عن وصاياك.","119:11":"خبأت كلامك في قلبي لكيلا أخطئ إليك.","119:12":"مبارك أنت يا رب. علمني فرائضك.","119:13":"بشفتي حسبت كل أحكام فمك.","119:14":"بطريق شهاداتك فرحت كما على كل الغنى.","119:15":"بوصاياك ألهج وألاحظ سبلك.","119:16":"بفرائضك أتلذذ. لا أنسى كلامك.","119:17":"ج أحسن إلى عبدك فأحيا وأحفظ أمرك.","119:18":"اكشف عن عيني فأرى عجائب من شريعتك.","119:19":"غريب أنا في الأرض. لا تخف عني وصاياك.","119:20":"انسحقت نفسي شوقا إلى أحكامك في كل حين.","119:21":"انتهرت المتكبرين الملاعين الضالين عن وصاياك.","119:22":"دحرج عني العار والإهانة لأني حفظت شهاداتك.","119:23":"جلس أيضا رؤساء تقاولوا علي. أما عبدك فيناجي بفرائضك.","119:24":"أيضا شهاداتك هي لذتي أهل مشورتي.","119:25":"د لصقت بالتراب نفسي فأحيني حسب كلمتك.","119:26":"قد صرحت بطرقي فاستجبت لي. علمني فرائضك.","119:27":"طريق وصاياك فهمني فأناجي بعجائبك.","119:28":"قطرت نفسي من الحزن. أقمني حسب كلامك.","119:29":"طريق الكذب أبعد عني وبشريعتك ارحمني.","119:30":"اخترت طريق الحق. جعلت أحكامك قدامي.","119:31":"لصقت بشهاداتك. يا رب لا تخزني.","119:32":"في طريق وصاياك أجري لأنك ترحب قلبي.","119:33":"هـ علمني يا رب طريق فرائضك فأحفظها إلى النهاية.","119:34":"فهمني فألاحظ شريعتك وأحفظها بكل قلبي.","119:35":"دربني في سبيل وصاياك لأني به سررت.","119:36":"أمل قلبي إلى شهاداتك لا إلى المكسب.","119:37":"حول عيني عن النظر إلى الباطل. في طريقك أحيني.","119:38":"أقم لعبدك قولك الذي لمتقيك.","119:39":"أزل عاري الذي حذرت منه لأن أحكامك طيبة.","119:40":"هئنذا قد اشتهيت وصاياك. بعدلك أحيني.","119:41":"و لتأتني رحمتك يا رب خلاصك حسب قولك","119:42":"فأجاوب معيري كلمة لأني اتكلت على كلامك.","119:43":"ولا تنزع من فمي كلام الحق كل النزع لأني انتظرت أحكامك.","119:44":"فأحفظ شريعتك دائما إلى الدهر والأبد","119:45":"وأتمشى في رحب لأني طلبت وصاياك","119:46":"وأتكلم بشهاداتك قدام ملوك ولا أخزى","119:47":"وأتلذذ بوصاياك التي أحببت","119:48":"وأرفع يدي إلى وصاياك التي وددت وأناجي بفرائضك.","119:49":"ز اذكر لعبدك القول الذي جعلتني أنتظره.","119:50":"هذه هي تعزيتي في مذلتي لأن قولك أحياني.","119:51":"المتكبرون استهزأوا بي إلى الغاية. عن شريعتك لم أمل.","119:52":"تذكرت أحكامك منذ الدهر يا رب فتعزيت.","119:53":"الحمية أخذتني بسبب الأشرار تاركي شريعتك.","119:54":"ترنيمات صارت لي فرائضك في بيت غربتي.","119:55":"ذكرت في الليل اسمك يا رب وحفظت شريعتك.","119:56":"هذا صار لي لأني حفظت وصاياك.","119:57":"ح نصيبي الرب قلت لحفظ كلامك.","119:58":"ترضيت وجهك بكل قلبي. ارحمني حسب قولك.","119:59":"تفكرت في طرقي ورددت قدمي إلى شهاداتك.","119:60":"أسرعت ولم أتوان لحفظ وصاياك.","119:61":"حبال الأشرار التفت علي. أما شريعتك فلم أنسها.","119:62":"في منتصف الليل أقوم لأحمدك على أحكام برك.","119:63":"رفيق أنا لكل الذين يتقونك ولحافظي وصاياك.","119:64":"رحمتك يا رب قد ملأت الأرض. علمني فرائضك.","119:65":"ط خيرا صنعت مع عبدك يا رب حسب كلامك.","119:66":"ذوقا صالحا ومعرفة علمني لأني بوصاياك آمنت.","119:67":"قبل أن أذلل أنا ضللت أما الآن فحفظت قولك.","119:68":"صالح أنت ومحسن. علمني فرائضك.","119:69":"المتكبرون قد لفقوا علي كذبا أما أنا فبكل قلبي أحفظ وصاياك.","119:70":"سمن مثل الشحم قلبهم أما أنا فبشريعتك أتلذذ.","119:71":"خير لي أني تذللت لكي أتعلم فرائضك.","119:72":"شريعة فمك خير لي من ألوف ذهب وفضة.","119:73":"ي يداك صنعتاني وأنشأتاني. فهمني فأتعلم وصاياك.","119:74":"متقوك يرونني فيفرحون لأني انتظرت كلامك.","119:75":"قد علمت يا رب أن أحكامك عدل وبالحق أذللتني.","119:76":"فلتصر رحمتك لتعزيتي حسب قولك لعبدك.","119:77":"لتأتني مراحمك فأحيا لأن شريعتك هي لذتي.","119:78":"ليخز المتكبرون لأنهم زورا افتروا علي. أما أنا فأناجي بوصاياك.","119:79":"ليرجع إلي متقوك وعارفو شهاداتك.","119:80":"ليكن قلبي كاملا في فرائضك لكي لا أخزى.","119:81":"ك تاقت نفسي إلى خلاصك. كلامك انتظرت.","119:82":"كلت عيناي من النظر إلى قولك فأقول: [متى تعزيني؟]","119:83":"لأني قد صرت كزق في الدخان. أما فرائضك فلم أنسها.","119:84":"كم هي أيام عبدك؟ متى تجري حكما على مضطهدي؟","119:85":"المتكبرون قد كروا لي حفائر. ذلك ليس حسب شريعتك.","119:86":"كل وصاياك أمانة. زورا يضطهدونني. أعني.","119:87":"لولا قليل لأفنوني من الأرض. أما أنا فلم أترك وصاياك.","119:88":"حسب رحمتك أحيني فأحفظ شهادات فمك.","119:89":"ل إلى الأبد يا رب كلمتك مثبتة في السماوات.","119:90":"إلى دور فدور أمانتك. أسست الأرض فثبتت.","119:91":"على أحكامك ثبتت اليوم لأن الكل عبيدك.","119:92":"لو لم تكن شريعتك لذتي لهلكت حينئذ في مذلتي.","119:93":"إلى الدهر لا أنسى وصاياك لأنك بها أحييتني.","119:94":"لك أنا فخلصني لأني طلبت وصاياك.","119:95":"إياي انتظر الأشرار ليهلكوني. بشهاداتك أفطن.","119:96":"لكل كمال رأيت حدا أما وصيتك فواسعة جدا.","119:97":"م كم أحببت شريعتك! اليوم كله هي لهجي.","119:98":"وصيتك جعلتني أحكم من أعدائي لأنها إلى الدهر هي لي.","119:99":"أكثر من كل معلمي تعقلت لأن شهاداتك هي لهجي.","119:100":"أكثر من الشيوخ فطنت لأني حفظت وصاياك.","119:101":"من كل طريق شر منعت رجلي لكي أحفظ كلامك.","119:102":"عن أحكامك لم أمل لأنك أنت علمتني.","119:103":"ما أحلى قولك لحنكي! أحلى من العسل لفمي.","119:104":"من وصاياك أتفطن لذلك أبغضت كل طريق كذب.","119:105":"ن سراج لرجلي كلامك ونور لسبيلي.","119:106":"حلفت فأبره أن أحفظ أحكام برك.","119:107":"تذللت إلى الغاية. يا رب أحيني حسب كلامك.","119:108":"ارتض بمندوبات فمي يا رب وأحكامك علمني.","119:109":"نفسي دائما في كفي أما شريعتك فلم أنسها.","119:110":"الأشرار وضعوا لي فخا أما وصاياك فلم أضل عنها.","119:111":"ورثت شهاداتك إلى الدهر لأنها هي بهجة قلبي.","119:112":"عطفت قلبي لأصنع فرائضك إلى الدهر إلى النهاية.","119:113":"س المتقلبين أبغضت وشريعتك أحببت.","119:114":"ستري ومجني أنت. كلامك انتظرت.","119:115":"انصرفوا عني أيها الأشرار فأحفظ وصايا إلهي.","119:116":"اعضدني حسب قولك فأحيا ولا تخزني من رجائي.","119:117":"أسندني فأخلص وأراعي فرائضك دائما.","119:118":"احتقرت كل الضالين عن فرائضك لأن مكرهم باطل.","119:119":"كزغل عزلت كل أشرار الأرض لذلك أحببت شهاداتك.","119:120":"قد اقشعر لحمي من رعبك ومن أحكامك جزعت.","119:121":"ع أجريت حكما وعدلا. لا تسلمني إلى ظالمي.","119:122":"كن ضامن عبدك للخير لكي لا يظلمني المستكبرون.","119:123":"كلت عيناي اشتياقا إلى خلاصك وإلى كلمة برك.","119:124":"اصنع مع عبدك حسب رحمتك وفرائضك علمني.","119:125":"عبدك أنا. فهمني فأعرف شهاداتك.","119:126":"إنه وقت عمل للرب. قد نقضوا شريعتك.","119:127":"لأجل ذلك أحببت وصاياك أكثر من الذهب والإبريز.","119:128":"لأجل ذلك حسبت كل وصاياك في كل شيء مستقيمة. كل طريق كذب أبغضت.","119:129":"ف عجيبة هي شهاداتك لذلك حفظتها نفسي.","119:130":"فتح كلامك ينير يعقل الجهال.","119:131":"فغرت فمي ولهثت لأني إلى وصاياك اشتقت.","119:132":"التفت إلي وارحمني كحق محبي اسمك.","119:133":"ثبت خطواتي في كلمتك ولا يتسلط علي إثم.","119:134":"افدني من ظلم الإنسان فأحفظ وصاياك.","119:135":"أضيء بوجهك على عبدك وعلمني فرائضك.","119:136":"جداول مياه جرت من عيني لأنهم لم يحفظوا شريعتك.","119:137":"ص بار أنت يا رب وأحكامك مستقيمة.","119:138":"عدلا أمرت بشهاداتك وحقا إلى الغاية.","119:139":"أهلكتني غيرتي لأن أعدائي نسوا كلامك.","119:140":"كلمتك ممحصة جدا وعبدك أحبها.","119:141":"صغير أنا وحقير أما وصاياك فلم أنسها.","119:142":"عدلك عدل إلى الدهر وشريعتك حق.","119:143":"ضيق وشدة أصاباني أما وصاياك فهي لذاتي.","119:144":"عادلة شهاداتك إلى الدهر. فهمني فأحيا.","119:145":"ق صرخت من كل قلبي. استجب لي يا رب. فرائضك أحفظ.","119:146":"دعوتك. خلصني فأحفظ شهاداتك.","119:147":"تقدمت في الصبح وصرخت. كلامك انتظرت.","119:148":"تقدمت عيناي الهزع لكي ألهج بأقوالك.","119:149":"صوتي استمع حسب رحمتك. يا رب حسب أحكامك أحيني.","119:150":"اقترب التابعون الرذيلة. عن شريعتك بعدوا.","119:151":"قريب أنت يا رب وكل وصاياك حق.","119:152":"منذ زمان عرفت من شهاداتك أنك إلى الدهر أسستها.","119:153":"ر انظر إلى ذلي وأنقذني لأني لم أنس شريعتك.","119:154":"أحسن دعواي وفكني. حسب كلمتك أحيني.","119:155":"الخلاص بعيد عن الأشرار لأنهم لم يلتمسوا فرائضك.","119:156":"كثيرة هي مراحمك يا رب. حسب أحكامك أحيني.","119:157":"كثيرون مضطهدي ومضايقي. أما شهاداتك فلم أمل عنها.","119:158":"رأيت الغادرين ومقت لأنهم لم يحفظوا كلمتك.","119:159":"انظر أني أحببت وصاياك. يا رب حسب رحمتك أحيني.","119:160":"رأس كلامك حق وإلى الدهر كل أحكام عدلك.","119:161":"ش رؤساء اضطهدوني بلا سبب ومن كلامك جزع قلبي.","119:162":"أبتهج أنا بكلامك كمن وجد غنيمة وافرة.","119:163":"أبغضت الكذب وكرهته أما شريعتك فأحببتها.","119:164":"سبع مرات في النهار سبحتك على أحكام عدلك.","119:165":"سلامة جزيلة لمحبي شريعتك وليس لهم معثرة.","119:166":"رجوت خلاصك يا رب ووصاياك عملت.","119:167":"حفظت نفسي شهاداتك وأحبها جدا.","119:168":"حفظت وصاياك وشهاداتك لأن كل طرقي أمامك.","119:169":"ت ليبلغ صراخي إليك يا رب. حسب كلامك فهمني.","119:170":"لتدخل طلبتي إلى حضرتك. ككلمتك نجني.","119:171":"تنبع شفتاي تسبيحا إذا علمتني فرائضك.","119:172":"يغني لساني بأقوالك لأن كل وصاياك عدل.","119:173":"لتكن يدك لمعونتي لأنني اخترت وصاياك.","119:174":"اشتقت إلى خلاصك يا رب وشريعتك هي لذتي.","119:175":"لتحي نفسي وتسبحك وأحكامك لتعني.","119:176":"ضللت كشاة ضالة. اطلب عبدك لأني لم أنس وصاياك.","120:1":"ترنيمة المصاعد إلى الرب في ضيقي صرخت فاستجاب لي.","120:2":"يا رب نج نفسي من شفاه الكذب من لسان غش.","120:3":"ماذا يعطيك وماذا يزيد لك لسان الغش؟","120:4":"سهام جبار مسنونة مع جمر الرتم.","120:5":"ويلي لغربتي في ماشك لسكني في خيام قيدار!","120:6":"طال على نفسي سكنها مع مبغض السلام.","120:7":"أنا سلام وحينما أتكلم فهم للحرب.","121:1":"ترنيمة المصاعد أرفع عيني إلى الجبال من حيث يأتي عوني.","121:2":"معونتي من عند الرب صانع السماوات والأرض.","121:3":"لا يدع رجلك تزل. لا ينعس حافظك.","121:4":"إنه لا ينعس ولا ينام حافظ إسرائيل.","121:5":"الرب حافظك. الرب ظل لك عن يدك اليمنى.","121:6":"لا تضربك الشمس في النهار ولا القمر في الليل.","121:7":"الرب يحفظك من كل شر. يحفظ نفسك.","121:8":"الرب يحفظ خروجك ودخولك من الآن وإلى الدهر.","122:1":"ترنيمة المصاعد. لداود فرحت بالقائلين لي: [إلى بيت الرب نذهب].","122:2":"تقف أرجلنا في أبوابك يا أورشليم.","122:3":"أورشليم المبنية كمدينة متصلة كلها","122:4":"حيث صعدت الأسباط أسباط الرب شهادة لإسرائيل ليحمدوا اسم الرب.","122:5":"لأنه هناك استوت الكراسي للقضاء كراسي بيت داود.","122:6":"اسألوا سلامة أورشليم. ليسترح محبوك.","122:7":"ليكن سلام في أبراجك راحة في قصورك.","122:8":"من أجل إخوتي وأصحابي لأقولن: [سلام بك].","122:9":"من أجل بيت الرب إلهنا ألتمس لك خيرا.","123:1":"ترنيمة المصاعد إليك رفعت عيني يا ساكنا في السماوات.","123:2":"هوذا كما أن عيون العبيد نحو أيدي سادتهم كما أن عيني الجارية نحو يد سيدتها هكذا عيوننا نحو الرب إلهنا حتى يترأف علينا.","123:3":"ارحمنا يا رب ارحمنا لأننا كثيرا ما امتلأنا هوانا.","123:4":"كثيرا ما شبعت أنفسنا من هزء المستريحين وإهانة المستكبرين.","124:1":"ترنيمة المصاعد. لداو [لولا الرب الذي كان لنا]. ليقل إسرائيل:","124:2":"[لولا الرب الذي كان لنا عند ما قام الناس علينا","124:3":"إذا لابتلعونا أحياء عند احتماء غضبهم علينا","124:4":"إذا لجرفتنا المياه لعبر السيل على أنفسنا.","124:5":"إذا لعبرت على أنفسنا المياه الطامية].","124:6":"مبارك الرب الذي لم يسلمنا فريسة لأسنانهم.","124:7":"انفلتت أنفسنا مثل العصفور من فخ الصيادين. الفخ انكسر ونحن انفلتنا.","124:8":"عوننا باسم الرب الصانع السماوات والأرض.","125:1":"ترنيمة المصاعد المتوكلون على الرب مثل جبل صهيون الذي لا يتزعزع بل يسكن إلى الدهر.","125:2":"أورشليم الجبال حولها والرب حول شعبه من الآن وإلى الدهر.","125:3":"لأنه لا تستقر عصا الأشرار على نصيب الصديقين لكي لا يمد الصديقون أيديهم إلى الإثم.","125:4":"أحسن يا رب إلى الصالحين وإلى المستقيمي القلوب.","125:5":"أما العادلون إلى طرق معوجة فيذهبهم الرب مع فعلة الإثم. سلام على إسرائيل.","126:1":"ترنيمة المصاعد عندما رد الرب سبي صهيون صرنا مثل الحالمين.","126:2":"حينئذ امتلأت أفواهنا ضحكا وألسنتنا ترنما. حينئذ قالوا بين الأمم: [إن الرب قد عظم العمل مع هؤلاء].","126:3":"عظم الرب العمل معنا وصرنا فرحين.","126:4":"اردد يا رب سبينا مثل السواقي في الجنوب.","126:5":"الذين يزرعون بالدموع يحصدون بالابتهاج.","126:6":"الذاهب ذهابا بالبكاء حاملا مبذر الزرع مجيئا يجيء بالترنم حاملا حزمه.","127:1":"ترنيمة المصاعد. لسليمان إن لم يبن الرب البيت فباطلا يتعب البناؤون. إن لم يحفظ الرب المدينة فباطلا يسهر الحارس.","127:2":"باطل هو لكم أن تبكروا إلى القيام مؤخرين الجلوس آكلين خبز الأتعاب. لكنه يعطي حبيبه نوما.","127:3":"هوذا البنون ميراث من عند الرب ثمرة البطن أجرة.","127:4":"كسهام بيد جبار هكذا أبناء الشبيبة.","127:5":"طوبى للذي ملأ جعبته منهم. لا يخزون بل يكلمون الأعداء في الباب.","128:1":"ترنيمة المصاعد طوبى لكل من يتقي الرب ويسلك في طرقه","128:2":"لأنك تأكل تعب يديك. طوباك وخير لك.","128:3":"امرأتك مثل كرمة مثمرة في جوانب بيتك. بنوك مثل غروس الزيتون حول مائدتك.","128:4":"هكذا يبارك الرجل المتقي الرب.","128:5":"يباركك الرب من صهيون وتبصر خير أورشليم كل أيام حياتك","128:6":"وترى بني بنيك. سلام على إسرائيل.","129:1":"ترنيمة المصاعد [كثيرا ما ضايقوني منذ شبابي]. ليقل إسرائيل:","129:2":"[كثيرا ما ضايقوني منذ شبابي لكن لم يقدروا علي.","129:3":"على ظهري حرث الحراث. طولوا أتلامهم].","129:4":"الرب صديق. قطع ربط الأشرار.","129:5":"فليخز وليرتد إلى الوراء كل مبغضي صهيون.","129:6":"ليكونوا كعشب السطوح الذي ييبس قبل أن يقلع","129:7":"الذي لا يملأ الحاصد كفه منه ولا المحزم حضنه.","129:8":"ولا يقول العابرون: [بركة الرب عليكم. باركناكم باسم الرب].","130:1":"ترنيمة المصاعد من الأعماق صرخت إليك يا رب.","130:2":"يا رب اسمع صوتي. لتكن أذناك مصغيتين إلى صوت تضرعاتي.","130:3":"إن كنت تراقب الآثام يا رب يا سيد فمن يقف؟","130:4":"لأن عندك المغفرة. لكي يخاف منك.","130:5":"انتظرتك يا رب. انتظرت نفسي وبكلامه رجوت.","130:6":"نفسي تنتظر الرب أكثر من المراقبين الصبح. أكثر من المراقبين الصبح.","130:7":"ليرج إسرائيل الرب لأن عند الرب الرحمة وعنده فدى كثير","130:8":"وهو يفدي إسرائيل من كل آثامه.","131:1":"ترنيمة المصاعد. لداود يا رب لم يرتفع قلبي ولم تستعل عيناي ولم أسلك في العظائم ولا في عجائب فوقي.","131:2":"بل هدأت وسكت نفسي كفطيم نحو أمه. نفسي نحوي كفطيم.","131:3":"ليرج إسرائيل الرب من الآن وإلى الدهر.","132:1":"ترنيمة المصاعد اذكر يا رب داود كل ذله.","132:2":"كيف حلف للرب نذر لعزيز يعقوب:","132:3":"[لا أدخل خيمة بيتي. لا أصعد على سرير فراشي.","132:4":"لا أعطي وسنا لعيني ولا نوما لأجفاني","132:5":"أو أجد مقاما للرب مسكنا لعزيز يعقوب].","132:6":"هوذا قد سمعنا به في أفراتة. وجدناه في حقول الوعر.","132:7":"لندخل إلى مساكنه. لنسجد عند موطئ قدميه.","132:8":"قم يا رب إلى راحتك أنت وتابوت عزك.","132:9":"كهنتك يلبسون البر وأتقياؤك يهتفون.","132:10":"من أجل داود عبدك لا ترد وجه مسيحك.","132:11":"أقسم الرب لداود بالحق لا يرجع عنه: [من ثمرة بطنك أجعل على كرسيك.","132:12":"إن حفظ بنوك عهدي وشهاداتي التي أعلمهم إياها فبنوهم أيضا إلى الأبد يجلسون على كرسيك].","132:13":"لأن الرب قد اختار صهيون. اشتهاها مسكنا له:","132:14":"[هذه هي راحتي إلى الأبد. ههنا أسكن لأني اشتهيتها.","132:15":"طعامها أبارك بركة. مساكينها أشبع خبزا.","132:16":"كهنتها ألبس خلاصا وأتقياؤها يهتفون هتافا.","132:17":"هناك أنبت قرنا لداود. رتبت سراجا لمسيحي.","132:18":"أعداءه ألبس خزيا وعليه يزهر إكليله].","133:1":"ترنيمة المصاعد. لداود هوذا ما أحسن وما أجمل أن يسكن الإخوة معا!","133:2":"مثل الدهن الطيب على الرأس النازل على اللحية لحية هارون النازل إلى طرف ثيابه.","133:3":"مثل ندى حرمون النازل على جبل صهيون. لأنه هناك أمر الرب بالبركة حياة إلى الأبد.","134:1":"ترنيمة المصاعد هوذا باركوا الرب يا جميع عبيد الرب الواقفين في بيت الرب بالليالي.","134:2":"ارفعوا أيديكم نحو القدس وباركوا الرب.","134:3":"يباركك الرب من صهيون الصانع السماوات والأرض.","135:1":"هللويا. سبحوا اسم الرب. سبحوا يا عبيد الرب","135:2":"الواقفين في بيت الرب في ديار بيت إلهنا.","135:3":"سبحوا الرب لأن الرب صالح. رنموا لاسمه لأن ذاك حلو.","135:4":"لأن الرب قد اختار يعقوب لذاته وإسرائيل لخاصته.","135:5":"لأني أنا قد عرفت أن الرب عظيم وربنا فوق جميع الآلهة.","135:6":"كل ما شاء الرب صنع في السماوات وفي الأرض في البحار وفي كل اللجج.","135:7":"المصعد السحاب من أقاصي الأرض. الصانع بروقا للمطر. المخرج الريح من خزائنه.","135:8":"الذي ضرب أبكار مصر من الناس إلى البهائم.","135:9":"أرسل آيات وعجائب في وسطك يا مصر على فرعون وعلى كل عبيده.","135:10":"الذي ضرب أمما كثيرة وقتل ملوكا أعزاء:","135:11":"سيحون ملك الأموريين وعوج ملك باشان وكل ممالك كنعان.","135:12":"وأعطى أرضهم ميراثا ميراثا لإسرائيل شعبه.","135:13":"يا رب اسمك إلى الدهر. يا رب ذكرك إلى دور فدور.","135:14":"لأن الرب يدين شعبه وعلى عبيده يشفق.","135:15":"أصنام الأمم فضة وذهب عمل أيدي الناس.","135:16":"لها أفواه ولا تتكلم. لها أعين ولا تبصر.","135:17":"لها آذان ولا تسمع. كذلك ليس في أفواهها نفس!","135:18":"مثلها يكون صانعوها وكل من يتكل عليها.","135:19":"يا بيت إسرائيل باركوا الرب. يا بيت هارون باركوا الرب.","135:20":"يا بيت لاوي باركوا الرب. يا خائفي الرب باركوا الرب.","135:21":"مبارك الرب من صهيون الساكن في أورشليم. هللويا.","136:1":"احمدوا الرب لأنه صالح لأن إلى الأبد رحمته.","136:2":"احمدوا إله الآلهة لأن إلى الأبد رحمته.","136:3":"احمدوا رب الأرباب لأن إلى الأبد رحمته.","136:4":"الصانع العجائب العظام وحده لأن إلى الأبد رحمته.","136:5":"الصانع السماوات بفهم لأن إلى الأبد رحمته.","136:6":"الباسط الأرض على المياه لأن إلى الأبد رحمته.","136:7":"الصانع أنوارا عظيمة لأن إلى الأبد رحمته.","136:8":"الشمس لحكم النهار لأن إلى الأبد رحمته.","136:9":"القمر والكواكب لحكم الليل لأن إلى الأبد رحمته.","136:10":"الذي ضرب مصر مع أبكارها لأن إلى الأبد رحمته.","136:11":"وأخرج إسرائيل من وسطهم لأن إلى الأبد رحمته.","136:12":"بيد شديدة وذراع ممدودة لأن إلى الأبد رحمته.","136:13":"الذي شق بحر سوف إلى شقق لأن إلى الأبد رحمته.","136:14":"وعبر إسرائيل في وسطه لأن إلى الأبد رحمته.","136:15":"ودفع فرعون وقوته في بحر سوف لأن إلى الأبد رحمته.","136:16":"الذي سار بشعبه في البرية لأن إلى الأبد رحمته.","136:17":"الذي ضرب ملوكا عظماء لأن إلى الأبد رحمته.","136:18":"وقتل ملوكا أعزاء لأن إلى الأبد رحمته:","136:19":"سيحون ملك الأموريين لأن إلى الأبد رحمته","136:20":"وعوج ملك باشان لأن إلى الأبد رحمته.","136:21":"وأعطى أرضهم ميراثا لأن إلى الأبد رحمته","136:22":"ميراثا لإسرائيل عبده لأن إلى الأبد رحمته.","136:23":"الذي في مذلتنا ذكرنا لأن إلى الأبد رحمته.","136:24":"ونجانا من أعدائنا لأن إلى الأبد رحمته.","136:25":"الذي يعطي خبزا لكل بشر لأن إلى الأبد رحمته.","136:26":"احمدوا إله السماوات لأن إلى الأبد رحمته.","137:1":"على أنهار بابل هناك جلسنا. بكينا أيضا عند ما تذكرنا صهيون.","137:2":"على الصفصاف في وسطها علقنا أعوادنا.","137:3":"لأنه هناك سألنا الذين سبونا كلام ترنيمة ومعذبونا سألونا فرحا: [رنموا لنا من ترنيمات صهيون].","137:4":"كيف نرنم ترنيمة الرب في أرض غريبة؟","137:5":"إن نسيتك يا أورشليم تنسى يميني - ليلتصق لساني بحنكي إن لم أذكرك!","137:6":"إن لم أفضل أورشليم على أعظم فرحي!","137:7":"اذكر يا رب لبني أدوم يوم أورشليم القائلين: [هدوا هدوا حتى إلى أساسها].","137:8":"يا بنت بابل المخربة طوبى لمن يجازيك جزاءك الذي جازيتنا!","137:9":"طوبى لمن يمسك أطفالك ويضرب بهم الصخرة!","138:1":"لداود أحمدك من كل قلبي. قدام الآلهة أرنم لك.","138:2":"أسجد في هيكل قدسك وأحمد اسمك على رحمتك وحقك لأنك قد عظمت كلمتك على كل اسمك.","138:3":"في يوم دعوتك أجبتني. شجعتني قوة في نفسي.","138:4":"يحمدك يا رب كل ملوك الأرض إذا سمعوا كلمات فمك.","138:5":"ويرنمون في طرق الرب لأن مجد الرب عظيم.","138:6":"لأن الرب عال ويرى المتواضع. أما المتكبر فيعرفه من بعيد.","138:7":"إن سلكت في وسط الضيق تحيني. على غضب أعدائي تمد يدك وتخلصني يمينك.","138:8":"الرب يحامي عني. يا رب رحمتك إلى الأبد. عن أعمال يديك لا تتخل.","139:1":"لإمام المغنين. لداود. مزمور يا رب قد اختبرتني وعرفتني.","139:2":"أنت عرفت جلوسي وقيامي. فهمت فكري من بعيد.","139:3":"مسلكي ومربضي ذريت وكل طرقي عرفت.","139:4":"لأنه ليس كلمة في لساني إلا وأنت يا رب عرفتها كلها.","139:5":"من خلف ومن قدام حاصرتني وجعلت علي يدك.","139:6":"عجيبة هذه المعرفة فوقي. ارتفعت لا أستطيعها.","139:7":"أين أذهب من روحك ومن وجهك أين أهرب؟","139:8":"إن صعدت إلى السماوات فأنت هناك وإن فرشت في الهاوية فها أنت.","139:9":"إن أخذت جناحي الصبح وسكنت في أقاصي البحر","139:10":"فهناك أيضا تهديني يدك وتمسكني يمينك.","139:11":"فقلت: [إنما الظلمة تغشاني]. فالليل يضيء حولي!","139:12":"الظلمة أيضا لا تظلم لديك والليل مثل النهار يضيء. كالظلمة هكذا النور.","139:13":"لأنك أنت اقتنيت كليتي. نسجتني في بطن أمي.","139:14":"أحمدك من أجل أني قد امتزت عجبا. عجيبة هي أعمالك ونفسي تعرف ذلك يقينا.","139:15":"لم تختف عنك عظامي حينما صنعت في الخفاء ورقمت في أعماق الأرض.","139:16":"رأت عيناك أعضائي وفي سفرك كلها كتبت يوم تصورت إذ لم يكن واحد منها.","139:17":"ما أكرم أفكارك يا الله عندي! ما أكثر جملتها!","139:18":"إن أحصها فهي أكثر من الرمل. استيقظت وأنا بعد معك.","139:19":"ليتك تقتل الأشرار يا الله. فيا رجال الدماء ابعدوا عني.","139:20":"الذين يكلمونك بالمكر ناطقين بالكذب هم أعداؤك.","139:21":"ألا أبغض مبغضيك يا رب وأمقت مقاوميك.","139:22":"بغضا تاما أبغضتهم. صاروا لي أعداء.","139:23":"اختبرني يا الله واعرف قلبي. امتحني واعرف أفكاري.","139:24":"وانظر إن كان في طريق باطل واهدني طريقا أبديا.","140:1":"لإمام المغنين. مزمور لداود أنقذني يا رب من أهل الشر. من رجل الظلم احفظني.","140:2":"الذين يتفكرون بشرور في قلوبهم. اليوم كله يجتمعون للقتال.","140:3":"سنوا ألسنتهم كحية. حمة الأفعوان تحت شفاههم. سلاه.","140:4":"احفظني يا رب من يدي الشرير. من رجل الظلم أنقذني. الذين تفكروا في تعثير خطواتي.","140:5":"أخفى لي المستكبرون فخا وحبالا. مدوا شبكة بجانب الطريق. وضعوا لي أشراكا. سلاه.","140:6":"قلت للرب: [أنت إلهي. أصغ يا رب إلى صوت تضرعاتي.","140:7":"يا رب السيد قوة خلاصي ظللت رأسي في يوم القتال.","140:8":"لا تعط يا رب شهوات الشرير. لا تنجح مقاصده. يترفعون. سلاه.","140:9":"أما رؤوس المحيطين بي فشقاء شفاههم يغطيهم.","140:10":"ليسقط عليهم جمر. ليسقطوا في النار وفي غمرات فلا يقوموا.","140:11":"رجل لسان لا يثبت في الأرض. رجل الظلم يصيده الشر إلى هلاكه].","140:12":"قد علمت أن الرب يجري حكما للمساكين وحقا للبائسين.","140:13":"إنما الصديقون يحمدون اسمك. المستقيمون يجلسون في حضرتك.","141:1":"مزمور لداود يا رب إليك صرخت. أسرع إلي. أصغ إلى صوتي عند ما أصرخ إليك.","141:2":"لتستقم صلاتي كالبخور قدامك. ليكن رفع يدي كذبيحة مسائية.","141:3":"اجعل يا رب حارسا لفمي. احفظ باب شفتي.","141:4":"لا تمل قلبي إلى أمر رديء لأتعلل بعلل الشر مع أناس فاعلي إثم ولا آكل من نفائسهم.","141:5":"ليضربني الصديق فرحمة وليوبخني فزيت للرأس. لا يأبى رأسي. لأن صلاتي بعد في مصائبهم.","141:6":"قد انطرح قضاتهم من على الصخرة وسمعوا كلماتي لأنها لذيذة.","141:7":"كمن يفلح ويشق الأرض تبددت عظامنا عند فم الهاوية.","141:8":"لأنه إليك يا سيد يا رب عيناي. بك احتميت. لا تفرغ نفسي.","141:9":"احفظني من الفخ الذي قد نصبوه لي ومن أشراك فاعلي الإثم.","141:10":"ليسقط الأشرار في شباكهم حتى أنجو أنا بالكلية.","142:1":"قصيدة لداود لما كان في المغارة. صلاة بصوتي إلى الرب أصرخ. بصوتي إلى الرب أتضرع.","142:2":"أسكب أمامه شكواي. بضيقي قدامه أخبر.","142:3":"عند ما أعيت روحي في وأنت عرفت مسلكي - في الطريق التي أسلك أخفوا لي فخا.","142:4":"انظر إلى اليمين وأبصر فليس لي عارف. باد عني المناص. ليس من يسأل عن نفسي.","142:5":"صرخت إليك يا رب. قلت: [أنت ملجإي نصيبي في أرض الأحياء.","142:6":"أصغ إلى صراخي لأني قد تذللت جدا. نجني من مضطهدي لأنهم أشد مني.","142:7":"أخرج من الحبس نفسي لتحميد اسمك. الصديقون يكتنفونني لأنك تحسن إلي].","143:1":"مزمور لداود يا رب اسمع صلاتي وأصغ إلى تضرعاتي. بأمانتك استجب لي بعدلك.","143:2":"ولا تدخل في المحاكمة مع عبدك فإنه لن يتبرر قدامك حي.","143:3":"لأن العدو قد اضطهد نفسي. سحق إلى الأرض حياتي. أجلسني في الظلمات مثل الموتى منذ الدهر.","143:4":"أعيت في روحي. تحير في داخلي قلبي.","143:5":"تذكرت أيام القدم. لهجت بكل أعمالك. بصنائع يديك أتأمل.","143:6":"بسطت إليك يدي. نفسي نحوك كأرض يابسة. سلاه.","143:7":"أسرع أجبني يا رب. فنيت روحي. لا تحجب وجهك عني فأشبه الهابطين في الجب.","143:8":"أسمعني رحمتك في الغداة لأني عليك توكلت. عرفني الطريق التي أسلك فيها لأني إليك رفعت نفسي.","143:9":"أنقذني من أعدائي يا رب. إليك التجأت.","143:10":"علمني أن أعمل رضاك لأنك أنت إلهي. روحك الصالح يهديني في أرض مستوية.","143:11":"من أجل اسمك يا رب تحييني. بعدلك تخرج من الضيق نفسي","143:12":"وبرحمتك تستأصل أعدائي وتبيد كل مضايقي نفسي لأني أنا عبدك.","144:1":"لداود مبارك الرب صخرتي الذي يعلم يدي القتال وأصابعي الحرب.","144:2":"رحمتي وملجإي صرحي ومنقذي مجني والذي عليه توكلت المخضع شعبي تحتي.","144:3":"يا رب أي شيء هو الإنسان حتى تعرفه أو ابن الإنسان حتى تفتكر به؟","144:4":"الإنسان أشبه نفخة. أيامه مثل ظل عابر.","144:5":"يا رب طأطئ سماواتك وانزل. المس الجبال فتدخن.","144:6":"أبرق بروقا وبددهم. أرسل سهامك وأزعجهم.","144:7":"أرسل يدك من العلاء. أنقذني ونجني من المياه الكثيرة من أيدي الغرباء","144:8":"الذين تكلمت أفواههم بالباطل ويمينهم يمين كذب.","144:9":"يا الله أرنم لك ترنيمة جديدة. برباب ذات عشرة أوتار أرنم لك.","144:10":"المعطي خلاصا للملوك. المنقذ داود عبده من السيف السوء.","144:11":"أنقذني ونجني من أيدي الغرباء الذين تكلمت أفواههم بالباطل ويمينهم يمين كذب.","144:12":"لكي يكون بنونا مثل الغروس النامية في شبيبتها. بناتنا كأعمدة الزوايا منحوتات حسب بناء هيكل.","144:13":"أهراؤنا ملآنة تفيض من صنف فصنف. أغنامنا تنتج ألوفا وربوات في شوارعنا.","144:14":"بقرنا محملة. لا اقتحام ولا هجوم ولا شكوى في شوارعنا.","144:15":"طوبى للشعب الذي له كهذا. طوبى للشعب الذي الرب إلهه.","145:1":"تسبيحة لداود أرفعك يا إلهي الملك وأبارك اسمك إلى الدهر والأبد.","145:2":"في كل يوم أباركك وأسبح اسمك إلى الدهر والأبد.","145:3":"عظيم هو الرب وحميد جدا وليس لعظمته استقصاء.","145:4":"دور إلى دور يسبح أعمالك وبجبروتك يخبرون.","145:5":"بجلال مجد حمدك وأمور عجائبك ألهج.","145:6":"بقوة مخاوفك ينطقون وبعظمتك أحدث.","145:7":"ذكر كثرة صلاحك يبدون وبعدلك يرنمون.","145:8":"الرب حنان ورحيم طويل الروح وكثير الرحمة.","145:9":"الرب صالح للكل ومراحمه على كل أعماله.","145:10":"يحمدك يا رب كل أعمالك ويباركك أتقياؤك.","145:11":"بمجد ملكك ينطقون وبجبروتك يتكلمون","145:12":"ليعرفوا بني آدم قدرتك ومجد جلال ملكك.","145:13":"ملكك ملك كل الدهور وسلطانك في كل دور فدور.","145:14":"الرب عاضد كل الساقطين ومقوم كل المنحنين.","145:15":"أعين الكل إياك تترجى وأنت تعطيهم طعامهم في حينه.","145:16":"تفتح يدك فتشبع كل حي رضى.","145:17":"الرب بار في كل طرقه ورحيم في كل أعماله.","145:18":"الرب قريب لكل الذين يدعونه الذين يدعونه بالحق.","145:19":"يعمل رضى خائفيه ويسمع تضرعهم فيخلصهم.","145:20":"يحفظ الرب كل محبيه ويهلك جميع الأشرار.","145:21":"بتسبيح الرب ينطق فمي وليبارك كل بشر اسمه القدوس إلى الدهر والأبد.","146:1":"هللويا. سبحي يا نفسي الرب.","146:2":"أسبح الرب في حياتي. وأرنم لإلهي ما دمت موجودا.","146:3":"لا تتكلوا على الرؤساء ولا على ابن آدم حيث لا خلاص عنده.","146:4":"تخرج روحه فيعود إلى ترابه. في ذلك اليوم نفسه تهلك أفكاره.","146:5":"طوبى لمن إله يعقوب معينه ورجاؤه على الرب إلهه","146:6":"الصانع السماوات والأرض البحر وكل ما فيها. الحافظ الأمانة إلى الأبد.","146:7":"المجري حكما للمظلومين المعطي خبزا للجياع. الرب يطلق الأسرى.","146:8":"الرب يفتح أعين العمي. الرب يقوم المنحنين. الرب يحب الصديقين.","146:9":"الرب يحفظ الغرباء. يعضد اليتيم والأرملة. أما طريق الأشرار فيعوجه.","146:10":"يملك الرب إلى الأبد إلهك يا صهيون إلى دور فدور. هللويا.","147:1":"سبحوا الرب لأن الترنم لإلهنا صالح. لأنه ملذ. التسبيح لائق.","147:2":"الرب يبني أورشليم. يجمع منفيي إسرائيل.","147:3":"يشفي المنكسري القلوب ويجبر كسرهم.","147:4":"يحصي عدد الكواكب. يدعو كلها بأسماء.","147:5":"عظيم هو ربنا وعظيم القوة. لفهمه لا إحصاء.","147:6":"الرب يرفع الودعاء ويضع الأشرار إلى الأرض.","147:7":"أجيبوا الرب بحمد. رنموا لإلهنا بعود.","147:8":"الكاسي السماوات سحابا المهيئ للأرض مطرا المنبت الجبال عشبا","147:9":"المعطي للبهائم طعامها لفراخ الغربان التي تصرخ.","147:10":"لا يسر بقوة الخيل. لا يرضى بساقي الرجل.","147:11":"يرضى الرب بأتقيائه بالراجين رحمته.","147:12":"سبحي يا أورشليم الرب. سبحي إلهك يا صهيون.","147:13":"لأنه قد شدد عوارض أبوابك. بارك أبناءك داخلك.","147:14":"الذي يجعل تخومك سلاما ويشبعك من شحم الحنطة.","147:15":"يرسل كلمته في الأرض. سريعا جدا يجري قوله.","147:16":"الذي يعطي الثلج كالصوف ويذري الصقيع كالرماد.","147:17":"يلقي جمده كفتات. قدام برده من يقف؟","147:18":"يرسل كلمته فيذيبها. يهب بريحه فتسيل المياه.","147:19":"يخبر يعقوب بكلمته وإسرائيل بفرائضه وأحكامه.","147:20":"لم يصنع هكذا بإحدى الأمم وأحكامه لم يعرفوها. هللويا.","148:1":"هللويا. سبحوا الرب من السماوات. سبحوه في الأعالي.","148:2":"سبحوه يا جميع ملائكته. سبحوه يا كل جنوده.","148:3":"سبحيه يا أيتها الشمس والقمر. سبحيه يا جميع كواكب النور.","148:4":"سبحيه يا سماء السماوات ويا أيتها المياه التي فوق السماوات.","148:5":"لتسبح اسم الرب لأنه أمر فخلقت","148:6":"وثبتها إلى الدهر والأبد وضع لها حدا فلن تتعداه.","148:7":"سبحي الرب من الأرض يا أيتها التنانين وكل اللجج.","148:8":"النار والبرد الثلج والضباب الريح العاصفة الصانعة كلمته","148:9":"الجبال وكل الآكام الشجر المثمر وكل الأرز","148:10":"الوحوش وكل البهائم الدبابات والطيور ذوات الأجنحة","148:11":"ملوك الأرض وكل الشعوب الرؤساء وكل قضاة الأرض","148:12":"الأحداث والعذارى أيضا الشيوخ مع الفتيان","148:13":"ليسبحوا اسم الرب لأنه قد تعالى اسمه وحده. مجده فوق الأرض والسماوات.","148:14":"وينصب قرنا لشعبه فخرا لجميع أتقيائه لبني إسرائيل الشعب القريب إليه. هللويا.","149:1":"هللويا. غنوا للرب ترنيمة جديدة تسبيحته في جماعة الأتقياء.","149:2":"ليفرح إسرائيل بخالقه. ليبتهج بنو صهيون بملكهم.","149:3":"ليسبحوا اسمه برقص. بدف وعود ليرنموا له.","149:4":"لأن الرب راض عن شعبه. يجمل الودعاء بالخلاص.","149:5":"ليبتهج الأتقياء بمجد. ليرنموا على مضاجعهم.","149:6":"تنويهات الله في أفواههم وسيف ذو حدين في يدهم.","149:7":"ليصنعوا نقمة في الأمم وتأديبات في الشعوب.","149:8":"لأسر ملوكهم بقيود وشرفائهم بكبول من حديد.","149:9":"ليجروا بهم الحكم المكتوب. كرامة هذا لجميع أتقيائه. هللويا.","150:1":"هللويا. سبحوا الله في قدسه. سبحوه في فلك قوته.","150:2":"سبحوه على قواته. سبحوه حسب كثرة عظمته.","150:3":"سبحوه بصوت الصور. سبحوه برباب وعود.","150:4":"سبحوه بدف ورقص. سبحوه بأوتار ومزمار.","150:5":"سبحوه بصنوج التصويت. سبحوه بصنوج الهتاف.","150:6":"كل نسمة فلتسبح الرب. هللويا. Psa 151:1 ÃÃ¤Ã ÃÃÃ­ÃÃ ÃÃ¤Ã ÃÃ¬ ÃÃÃ¦ÃÃ¬ Ã¦ÃÃÃÃ ÃÃ¬ ÃÃ­Ã ÃÃÃ­ ÃÃ¤Ã ÃÃÃÃ­Ã ÃÃ¤Ã£ ÃÃÃ¬. Psa 151:2 Ã­ÃÃÃ­ ÃÃ¤ÃÃ ÃÃ¡ÃÃÃÃ¤ Ã¦ÃÃÃÃÃÃ­ ÃÃ¡ÃÃ ÃÃ¡Ã£ÃÃ£ÃÃ . ÃÃ¡Ã¡Ã­Ã¡Ã¦Ã­Ã. Psa 151:3 Ã£Ã¤ Ã¥Ã¦ ÃÃ¡ÃÃ¬ Ã­ÃÃÃ ÃÃ­ÃÃ¬ Ã¥Ã¦ ÃÃ¡ÃÃ ÃÃ¡ÃÃ¬ Ã­ÃÃÃÃ­Ã Ã¡Ã¡ÃÃ­Ã¤ Ã­ÃÃÃÃ¦Ã¤ ÃÃ¡Ã­Ã¥. Psa 151:4 Ã¥Ã¦ ÃÃÃÃ¡ Ã£Ã¡ÃÃÃ¥ Ã¦ÃÃÃÃ¤Ã­ Ã£Ã¤ ÃÃ¤Ã£ ÃÃÃ­ Ã¦Ã£ÃÃÃ¤Ã­ ÃÃÃ¥Ã¤ Ã£ÃÃÃÃ¥. Psa 151:5 ÃÃÃ¦ÃÃ­ ÃÃÃÃ¤ Ã¦Ã¥Ã£ ÃÃÃÃ Ã£Ã¤Ã­ Ã¦ÃÃ¡ÃÃ Ã¡Ã£ Ã­ÃÃ ÃÃ¥Ã£. Psa 151:6 ÃÃÃÃ Ã¡Ã¡ÃÃÃ ÃÃ¡ÃÃ¡ÃÃÃ­Ã¤Ã¬ ÃÃ¡ÃÃ¤Ã¤Ã­ ÃÃÃ¦ÃÃÃ¤Ã¥. Psa 151:7 Ã¡ÃÃ¤ ÃÃ¤Ã ÃÃ¡Ã¡Ã ÃÃ­ÃÃ¥ ÃÃ¡ÃÃ¬ ÃÃÃ¤ ÃÃ­ÃÃ¥ Ã¦ÃÃÃÃ ÃÃÃÃ¥. Psa 151:8 Ã¦Ã¤ÃÃÃ ÃÃ¡ÃÃÃ ÃÃ¤ ÃÃ¤Ã¬ ÃÃÃÃÃÃ­Ã¡ . ÃÃ¡Ã¡Ã­Ã¡Ã¦Ã­Ã."};
